let concernCategories = [];
let concernCategoriesRequest = null;
async function ensureConcernCategories() {
  if (concernCategories.length) return concernCategories;
  if (!concernCategoriesRequest) {
    concernCategoriesRequest = (async () => {
      const result = await getConcernCategoriesCall({ organizationSectors: true });
      concernCategories = Array.isArray(result.data?.categories) ? result.data.categories : [];
      if (!concernCategories.length) throw new Error("Concern categories are unavailable. Try again.");
      return concernCategories;
    })().finally(() => { concernCategoriesRequest = null; });
  }
  return concernCategoriesRequest;
}
function concernCategoryOptions(selected = "") {
  return `<option value="">Select category</option>${concernCategories.map((category) =>
    `<option value="${escapeAttribute(category.id)}" ${category.id === selected ? "selected" : ""}>${escapeHtml(category.name)}${category.sector ? ` (${category.sector === "private" ? "Private" : "Public"})` : ""}</option>`).join("")}`;
}
function organizationTypeOptions(sector, selected = "") {
  return `<option value="">Select type</option>${concernCategories.filter((category) => category.sector === sector).map((category) =>
    `<option value="${escapeAttribute(category.id)}" ${category.id === selected ? "selected" : ""}>${escapeHtml(category.name)}</option>`).join("")}`;
}
function organizationTypeIdFromRecord(organization) {
  const id = organization?.organizationTypeId || organization?.categoryId || "";
  return ({ peace_public_safety: "public_safety", roads_accessibility: "roads",
    infrastructure_facilities: "infrastructure", drainage_flooding: "drainage",
    sanitation_waste: "sanitation", streetlights_utilities: "electricity" })[id] || id;
}

