const byId = (id) => {
  const mounted = document.getElementById(id);
  if (mounted) return mounted;
  for (const view of routedPageViews.values()) {
    if (view.id === id) return view;
    const nested = view.querySelector(`#${id}`);
    if (nested) return nested;
  }
  return null;
};
