onAuthStateChanged(auth, async (user) => {
  if (organizationRegistrationInProgress) return;
  if (!user && registrationSuccessScreen && !registrationSuccessScreen.hidden) return;
  clearRealtimeListeners();
  if (isActivationRoute() && !activationFlowInProgress) {
    showActivation();
    return;
  }
  if (activationFlowInProgress) return;
  if (!user) {
    state.concerns = [];
    state.complaints = [];
    state.currentProfile = null;
    state.page = "dashboard";
    state.pendingRoute = "dashboard";
    if (window.location.hash && !isActivationRoute()) {
      window.history.replaceState({ page: "dashboard" }, "", window.location.pathname + window.location.search);
    }
    document.querySelectorAll(".nav-link").forEach((button) => {
      button.classList.toggle("active", button.dataset.page === "dashboard");
    });
    destroyConcernMap();
    showLogin();
    return;
  }
  await authorizeAdministrator(user);
});

document.addEventListener("click", (event) => {
  const button = event.target.closest("[data-toggle-password]");
  if (!button) return;
  event.preventDefault();
  const input = byId(button.dataset.togglePassword);
  if (!input) return;
  const revealing = input.type === "password";
  input.type = revealing ? "text" : "password";
  const icon = button.querySelector(".material-symbols-rounded");
  if (icon) icon.textContent = revealing ? "visibility_off" : "visibility";
  button.setAttribute("aria-label", revealing ? "Hide password" : "Show password");
});

// ── Registration proof file-card ──────────────────────────────────
(function initRegistrationFileCard() {
  const fileInput   = byId("registrationProofFile");
  const dropzone    = byId("registrationProofDropzone");
  const card        = byId("registrationProofCard");
  const preview     = byId("registrationProofPreview");
  const nameEl      = byId("registrationProofFileName");
  const sizeEl      = byId("registrationProofFileSize");
  const typeEl      = byId("registrationProofFileType");
  const badgeEl     = byId("registrationProofBadgeText");
  const changeBtn   = byId("registrationProofChange");
  const removeBtn   = byId("registrationProofRemove");
  if (!fileInput || !dropzone) return;

  function formatBytes(bytes) {
    if (bytes < 1024) return bytes + " B";
    if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + " KB";
    return (bytes / (1024 * 1024)).toFixed(2) + " MB";
  }

  function showFileCard(file) {
    const isImage = file.type.startsWith("image/");
    const ext = file.name.split(".").pop()?.toUpperCase() || (isImage ? "PHOTO" : "DOCUMENT");
    if (nameEl) nameEl.textContent = file.name;
    if (sizeEl) sizeEl.textContent = formatBytes(file.size);
    if (typeEl) typeEl.textContent = ext;
    if (badgeEl) badgeEl.textContent = isImage ? "SELECTED PHOTO" : "SELECTED DOCUMENT";

    if (preview) {
      preview.innerHTML = "";
      if (isImage) {
        const img = document.createElement("img");
        img.alt = "Preview";
        const reader = new FileReader();
        reader.onload = (e) => { img.src = e.target.result; };
        reader.readAsDataURL(file);
        preview.appendChild(img);
      } else {
        const icon = document.createElement("span");
        icon.className = "material-symbols-rounded";
        icon.textContent = "description";
        preview.appendChild(icon);
      }
    }
    dropzone.hidden = true;
    card.hidden = false;
  }

  function clearFileCard() {
    fileInput.value = "";
    if (preview) preview.innerHTML = '<span class="material-symbols-rounded">description</span>';
    if (nameEl) nameEl.textContent = "";
    if (sizeEl) sizeEl.textContent = "";
    card.hidden = true;
    dropzone.hidden = false;
  }

  dropzone.addEventListener("click", () => fileInput.click());
  changeBtn?.addEventListener("click", () => fileInput.click());
  removeBtn?.addEventListener("click", clearFileCard);

  // Drag and drop support
  ["dragenter", "dragover"].forEach((eventName) => {
    dropzone.addEventListener(eventName, (e) => {
      e.preventDefault();
      e.stopPropagation();
      dropzone.classList.add("is-dragover");
    });
  });
  ["dragleave", "drop"].forEach((eventName) => {
    dropzone.addEventListener(eventName, (e) => {
      e.preventDefault();
      e.stopPropagation();
      dropzone.classList.remove("is-dragover");
    });
  });
  dropzone.addEventListener("drop", (e) => {
    const dt = e.dataTransfer;
    const files = dt?.files;
    if (files && files.length > 0) {
      fileInput.files = files;
      showFileCard(files[0]);
    }
  });

  fileInput.addEventListener("change", () => {
    const file = fileInput.files?.[0];
    if (file) showFileCard(file);
    else clearFileCard();
  });

  byId("organizationRegistrationForm")?.addEventListener("reset", () => {
    setTimeout(clearFileCard, 0);
  });
})();

activationForm?.addEventListener("submit", async (event) => {
  event.preventDefault();
  const email = byId("activationEmail").value.trim().toLowerCase();
  const temporaryPassword = byId("activationTemporaryPassword").value;
  const newPassword = byId("activationNewPassword").value;
  const confirmation = byId("activationConfirmPassword").value;
  const message = byId("activationMessage");
  const submit = activationForm.querySelector("button[type='submit']");
  message.textContent = "";
  message.classList.remove("error", "success");
  if (!validStaffPassword(newPassword)) {
    setActivationMessage("Use at least 6 characters for your new password.", true);
    return;
  }
  if (newPassword !== confirmation) {
    setActivationMessage("The new passwords do not match.", true);
    return;
  }
  if (newPassword === temporaryPassword) {
    setActivationMessage("Choose a new password that is different from the temporary password.", true);
    return;
  }

  activationFlowInProgress = true;
  setButtonBusy(submit, true, "Securing account…");
  try {
    if (auth.currentUser) await signOut(auth);
    const credential = await signInWithEmailAndPassword(auth, email, temporaryPassword);
    const profileSnapshot = await getDoc(doc(db, "users", credential.user.uid));
    const profile = profileSnapshot.data();
    if (!profileSnapshot.exists() || accountStatus(profile) !== "approved") {
      throw new Error("This staff account is not active. Contact the E-SUGID administrator.");
    }
    if (profile.setupRequired !== true) {
      throw new Error("This account setup is already complete. Use the staff sign-in page instead.");
    }
    await completeStaffSetupCall({ password: newPassword });
    await signOut(auth);
    window.history.replaceState({}, document.title, window.location.pathname);
    byId("email").value = email;
    byId("password").value = "";
    showLogin();
    setAuthMessage("Your private password is ready. Sign in with your new password.", false, true);
    window.setTimeout(() => byId("password")?.focus(), 0);
  } catch (error) {
    if (auth.currentUser) await signOut(auth).catch(() => {});
    const messageText = error?.code === "auth/invalid-credential"
      ? "The login email or temporary password is incorrect. Copy both exactly from your E-SUGID email."
      : error?.message || callableErrorMessage(error);
    setActivationMessage(messageText, true);
  } finally {
    activationFlowInProgress = false;
    setButtonBusy(submit, false);
  }
});

byId("activationBackToLogin")?.addEventListener("click", async () => {
  if (auth.currentUser) await signOut(auth);
  window.history.replaceState({}, document.title, window.location.pathname);
  showLogin();
});

function setActivationMessage(message, isError = false) {
  const target = byId("activationMessage");
  if (!target) return;
  target.textContent = message;
  target.classList.toggle("error", isError);
  target.classList.toggle("success", !isError && Boolean(message));
}

loginForm.addEventListener("submit", async (event) => {
  event.preventDefault();
  setAuthMessage("");
  state.pendingRoute = "dashboard";
  state.justLoggedIn = true;
  if (window.location.hash) {
    window.history.replaceState({ page: "dashboard" }, "", window.location.pathname + window.location.search);
  }
  const submit = loginForm.querySelector("button[type='submit']");
  setButtonBusy(submit, true, "Signing in…");
  try {
    const identity = byId("email").value.trim().toLowerCase();
    const authEmail = identity.includes("@") ? identity : `${identity}@login.esugid.local`;
    await signInWithEmailAndPassword(auth, authEmail, byId("password").value);
  } catch (error) {
    setAuthMessage(humanAuthError(error), true);
  } finally {
    setButtonBusy(submit, false);
  }
});

function showOrganizationRegistrationMessage(message, isError = false) {
  const target = byId("organizationRegistrationMessage");
  if (!target) return;
  if (!message) {
    target.innerHTML = "";
    target.className = "form-message";
    target.hidden = true;
    return;
  }
  target.hidden = false;
  target.classList.toggle("error", isError);
  target.classList.toggle("success", !isError);

  if (!isError) {
    target.innerHTML = `
      <div class="registration-feedback-banner is-success">
        <span class="material-symbols-rounded registration-feedback-icon">check_circle</span>
        <div class="registration-feedback-text">
          <strong class="registration-feedback-title">Success</strong>
          <p class="registration-feedback-body">${escapeHtml(message)}</p>
        </div>
      </div>
    `;
    return;
  }

  // Detect whether this error indicates the account or organization already exists
  const isAccountExists = /already registered|already has an active account|already exists|already has a pending|differs from the municipal directory|differs from the Structure directory|already reviewed/i.test(message);

  const title = isAccountExists ? "Account or Organization Already Registered" : "Please Check Your Submission";
  const icon = isAccountExists ? "account_circle" : "error";
  const actionHtml = isAccountExists ? `
    <div class="registration-feedback-actions">
      <button type="button" class="reg-feedback-btn reg-feedback-btn--primary" id="regFeedbackSignInBtn">
        <span class="material-symbols-rounded">login</span>
        <span>Sign In to Your Account</span>
      </button>
      <button type="button" class="reg-feedback-btn reg-feedback-btn--ghost" id="regFeedbackForgotBtn">
        <span class="material-symbols-rounded">lock_reset</span>
        <span>Forgot Password?</span>
      </button>
    </div>
  ` : "";

  target.innerHTML = `
    <div class="registration-feedback-banner is-error">
      <div class="registration-feedback-main">
        <span class="material-symbols-rounded registration-feedback-icon">${icon}</span>
        <div class="registration-feedback-text">
          <strong class="registration-feedback-title">${escapeHtml(title)}</strong>
          <p class="registration-feedback-body">${escapeHtml(message)}</p>
        </div>
      </div>
      ${actionHtml}
    </div>
  `;

  if (isAccountExists) {
    const signInBtn = target.querySelector("#regFeedbackSignInBtn");
    if (signInBtn) {
      signInBtn.addEventListener("click", () => {
        const regEmail = (byId("registrationEmail")?.value || "").trim();
        showLogin();
        if (regEmail) {
          const emailInput = byId("email");
          if (emailInput) {
            emailInput.value = regEmail;
            byId("password")?.focus();
          }
        }
      });
    }
    const forgotBtn = target.querySelector("#regFeedbackForgotBtn");
    if (forgotBtn) {
      forgotBtn.addEventListener("click", () => {
        const regEmail = (byId("registrationEmail")?.value || "").trim();
        showLogin();
        if (regEmail) {
          const emailInput = byId("email");
          if (emailInput) emailInput.value = regEmail;
          byId("forgotPasswordBtn")?.click();
        }
      });
    }
  }

  try {
    target.scrollIntoView({ behavior: "smooth", block: "nearest" });
  } catch (_) {}
}
function setRegistrationSubmitStage(button, label, detail = label) {
  button.textContent = label;
  const progress = byId("organizationRegistrationProgress");
  progress.textContent = detail;
  progress.hidden = false;
}

function uploadRegistrationProof(reference, proof, contentType, onProgress) {
  return new Promise((resolve, reject) => {
    const task = uploadBytesResumable(reference, proof, { contentType });
    task.on("state_changed", (snapshot) => {
      if (snapshot.totalBytes) onProgress(Math.round(100 * snapshot.bytesTransferred / snapshot.totalBytes));
    }, reject, () => resolve(task.snapshot));
  });
}

function showOrganizationRegistrationSuccess(email) {
  dashboard.hidden = true;
  setupScreen.hidden = true;
  loginScreen.hidden = true;
  if (registrationTypeScreen) registrationTypeScreen.hidden = true;
  organizationRegistrationScreen.hidden = true;
  registrationSuccessScreen.hidden = false;
  const status = byId("registrationEmailStatus");
  status.classList.remove("is-error");
  status.textContent = `Sending a verification link to ${email}...`;
  byId("registrationSuccessSignIn").disabled = true;
}

