function setRegistrationSection(id, active) {
  const section = byId(id);
  section.hidden = !active;
  section.querySelectorAll("input, select, button").forEach((field) => { field.disabled = !active; });
}

function updateRegistrationConditionalFields() {
  for (const [fieldId, inputId, show] of [
    ["registrationOtherPositionField", "registrationOtherPosition", byId("registrationPositionId").value === "other_position"],
    ["registrationLguServiceDescriptionField", "registrationLguServiceDescription", byId("registrationLguServiceType").value === "other_lgu_service"],
    ["registrationOrganizationDescriptionField", "registrationOrganizationDescription", byId("registrationOrganizationType").value === "other_organization"],
    ["registrationProofDocumentNameField", "registrationProofDocumentName", byId("registrationProofType").value === "other"],
  ]) {
    const field = byId(fieldId);
    field.hidden = !show;
    byId(inputId).required = show;
    byId(inputId).disabled = !show;
    if (!show) byId(inputId).value = "";
  }
}

function renderRegistrationPositions() {
  const barangay = byId("registrationOfficialBarangay").value;
  const selected = byId("registrationPositionId").value;
  byId("registrationPositionMenu").innerHTML = (registrationOptions.positions || DEFAULT_REGISTRATION_POSITIONS)
    .filter((position) => !position.adminOnly)
    .map((position) => {
      const reason = !position.available
        ? position.occupiedSlots > 0 && position.maxSlots === position.occupiedSlots
          ? "Position already assigned" : "Pending request already exists"
        : position.maxSlots === null ? "Available" : `${position.availableSlots} available`;
      return `<button type="button" data-position-id="${escapeAttribute(position.id)}" class="registration-position-option${position.available ? "" : " is-unavailable"}" aria-disabled="${!position.available}"><strong>${escapeHtml(position.name)}</strong><small>${escapeHtml(barangay ? reason : "Select a barangay first")}</small></button>`;
    }).join("");
  const current = (registrationOptions.positions || DEFAULT_REGISTRATION_POSITIONS).find((position) => position.id === selected);
  if (!current?.available || !barangay) byId("registrationPositionId").value = "";
  byId("registrationPositionTrigger").textContent = byId("registrationPositionId").value
    ? current.name : "Select position";
  updateRegistrationConditionalFields();
}

function populateRegistrationDropdowns() {
  const office = byId("registrationOffice");
  if (office && registrationOptions.offices?.length) {
    const previousOffice = office.value;
    office.innerHTML = `<option value="">Select office / department</option>${registrationOptions.offices.map((item) =>
      `<option value="${escapeAttribute(item.id)}">${escapeHtml(item.name)}</option>`).join("")}`;
    office.value = previousOffice;
  }
  const lguSelect = byId("registrationLguServiceType");
  if (lguSelect && (registrationOptions.lguServiceTypes || DEFAULT_LGU_SERVICES).length) {
    const previousLgu = lguSelect.value;
    lguSelect.innerHTML = `<option value="">Select service type</option>${(registrationOptions.lguServiceTypes || DEFAULT_LGU_SERVICES).map((item) =>
      `<option value="${escapeAttribute(item.id)}">${escapeHtml(item.name)}</option>`).join("")}`;
    lguSelect.value = previousLgu;
  }
  const orgSelect = byId("registrationOrganizationType");
  const sector = byId("registrationOrganizationSector")?.value || "";
  const orgTypes = (registrationOptions.organizationTypes && registrationOptions.organizationTypes.length > 0)
    ? registrationOptions.organizationTypes
    : DEFAULT_ORGANIZATION_TYPES;
  if (orgSelect && orgTypes.length) {
    const previousOrg = orgSelect.value;
    const visibleTypes = orgTypes.filter((item) => item.sector === sector);
    orgSelect.innerHTML = `<option value="" disabled selected>${sector ? "Select type" : "Select sector first"}</option>${visibleTypes.map((item) =>
      `<option value="${escapeAttribute(item.id)}" ${previousOrg === item.id ? "selected" : ""}>${escapeHtml(item.name)}</option>`).join("")}`;
    orgSelect.value = visibleTypes.some((item) => item.id === previousOrg) ? previousOrg : "";
    orgSelect.disabled = !sector;
  }
  const orgDatalist = byId("organizationDirectoryList");
  if (orgDatalist && registrationOptions.organizations) {
    orgDatalist.innerHTML = registrationOptions.organizations.map((org) =>
      `<option value="${escapeAttribute(org.name)}">${escapeHtml(org.name)} (${org.sector === "private" ? "Private" : "Public"})</option>`).join("");
  }
  renderRegistrationPositions();
}

async function loadRegistrationOptions(barangayId = "") {
  const sequence = ++registrationOptionsSequence;
  try {
    const result = await getStaffRegistrationOptionsCall({ barangayId });
    if (sequence !== registrationOptionsSequence) return;
    if (result?.data) {
      registrationOptions = {
        positions: result.data.positions || DEFAULT_REGISTRATION_POSITIONS,
        offices: result.data.offices || [],
        organizations: result.data.organizations || [],
        lguServiceTypes: result.data.lguServiceTypes || DEFAULT_LGU_SERVICES,
        organizationTypes: result.data.organizationTypes || DEFAULT_ORGANIZATION_TYPES,
      };
    }
  } catch (error) {
    console.warn("Could not load registration options from server, using local defaults:", error);
  }
  populateRegistrationDropdowns();
}

function updateRegistrationAccountType() {
  const type = byId("registrationAccountType").value;
  setRegistrationSection("registrationOrganizationSection", type === "organization");
  setRegistrationSection("registrationPersonalSection", Boolean(type));
  setRegistrationSection("registrationProofSection", Boolean(type));
  setRegistrationSection("registrationAccountSection", Boolean(type));
  for (const [id, active] of [["registrationBarangayOfficialFields", type === "barangay"],
    ["registrationLguFields", type === "lgu"]]) setRegistrationSection(id, active);
  byId("registrationPersonalLegend").textContent = ({
    barangay: "Barangay Official information", lgu: "LGU Staff information",
    organization: "Organization representative",
  })[type] || "Account holder";
  byId("registrationProofType").innerHTML = `<option value="">Select proof type</option>${(REGISTRATION_PROOF_LABELS[type] || [])
    .map(([id, label]) => `<option value="${id}">${escapeHtml(label)}</option>`).join("")}`;
  updateRegistrationConditionalFields();
}

function showAccountTypeSelection() {
  dashboard.hidden = true;
  dashboard.style.setProperty("display", "none", "important");
  setupScreen.hidden = true;
  setupScreen.style.setProperty("display", "none", "important");
  loginScreen.hidden = true;
  loginScreen.style.setProperty("display", "none", "important");
  organizationRegistrationScreen.hidden = true;
  organizationRegistrationScreen.style.setProperty("display", "none", "important");
  registrationSuccessScreen.hidden = true;
  registrationSuccessScreen.style.setProperty("display", "none", "important");
  if (registrationTypeScreen) {
    registrationTypeScreen.hidden = false;
    registrationTypeScreen.style.setProperty("display", "grid", "important");
  }
}

async function startRegistrationFlow(accountType) {
  if (registrationTypeScreen) {
    registrationTypeScreen.hidden = true;
    registrationTypeScreen.style.setProperty("display", "none", "important");
  }
  dashboard.hidden = true;
  dashboard.style.setProperty("display", "none", "important");
  setupScreen.hidden = true;
  setupScreen.style.setProperty("display", "none", "important");
  loginScreen.hidden = true;
  loginScreen.style.setProperty("display", "none", "important");
  organizationRegistrationScreen.hidden = false;
  organizationRegistrationScreen.style.setProperty("display", "grid", "important");
  registrationSuccessScreen.hidden = true;
  registrationSuccessScreen.style.setProperty("display", "none", "important");
  showOrganizationRegistrationMessage("");

  const accountTypeInput = byId("registrationAccountType");
  if (accountTypeInput) accountTypeInput.value = accountType;

  const titleMap = {
    barangay: "Barangay Official Registration",
    lgu: "LGU Staff Registration",
    organization: "Organization Registration",
  };
  const titleEl = byId("registrationFormTitle");
  if (titleEl) titleEl.textContent = titleMap[accountType] || "Account Registration";

  for (const sectionId of ["registrationOrganizationSection", "registrationBarangayOfficialFields", "registrationLguFields"]) {
    const section = byId(sectionId);
    if (section) section.querySelectorAll("input, select").forEach((field) => { field.value = ""; });
  }
  byId("registrationPositionId").value = "";
  byId("registrationPositionMessage").textContent = "";

  const barangayOptions = `<option value="">Select barangay</option>${BARANGAYS.map((name) =>
    `<option value="${escapeAttribute(name)}">${escapeHtml(name)}</option>`).join("")}`;
  const barangaySelect = byId("registrationBarangay");
  if (barangaySelect) barangaySelect.innerHTML = barangayOptions;
  const officialBarangay = byId("registrationOfficialBarangay");
  if (officialBarangay) officialBarangay.innerHTML = barangayOptions;

  updateRegistrationAccountType();
  populateRegistrationDropdowns();
  loadRegistrationOptions();
}

byId("registrationAccountType")?.addEventListener("change", () => {
  for (const sectionId of ["registrationOrganizationSection", "registrationBarangayOfficialFields", "registrationLguFields"]) {
    byId(sectionId).querySelectorAll("input, select").forEach((field) => { field.value = ""; });
  }
  byId("registrationPositionId").value = "";
  byId("registrationPositionMessage").textContent = "";
  updateRegistrationAccountType();
  populateRegistrationDropdowns();
  renderRegistrationPositions();
});
byId("registrationOfficialBarangay")?.addEventListener("change", async (event) => {
  byId("registrationPositionId").value = "";
  byId("registrationPositionMessage").textContent = "";
  loadRegistrationOptions(barangayIdFor(event.target.value) || "");
});
byId("registrationPositionTrigger")?.addEventListener("click", () => {
  const menu = byId("registrationPositionMenu");
  menu.hidden = !menu.hidden;
  byId("registrationPositionTrigger").setAttribute("aria-expanded", String(!menu.hidden));
});
byId("registrationPositionMenu")?.addEventListener("click", (event) => {
  const button = event.target.closest("[data-position-id]");
  if (!button) return;
  const position = registrationOptions.positions.find((item) => item.id === button.dataset.positionId);
  const barangay = byId("registrationOfficialBarangay").value;
  if (!barangay) {
    byId("registrationPositionMessage").textContent = "Select a barangay first.";
    return;
  }
  if (!position?.available) {
    byId("registrationPositionMessage").textContent = position.occupiedSlots >= position.maxSlots
      ? `${position.name} is already assigned for Barangay ${barangay}.`
      : `There is already a pending request for ${position.name} in Barangay ${barangay}.`;
    return;
  }
  byId("registrationPositionId").value = position.id;
  byId("registrationPositionTrigger").textContent = position.name;
  byId("registrationPositionMessage").textContent = "";
  byId("registrationPositionMenu").hidden = true;
  byId("registrationPositionTrigger").setAttribute("aria-expanded", "false");
  updateRegistrationConditionalFields();
});
for (const id of ["registrationLguServiceType", "registrationOrganizationType", "registrationProofType"]) {
  byId(id)?.addEventListener("change", updateRegistrationConditionalFields);
}
byId("registrationOrganizationSector")?.addEventListener("change", () => {
  populateRegistrationDropdowns();
  updateRegistrationConditionalFields();
});
byId("registrationOrganizationName")?.addEventListener("input", (e) => {
  const val = e.target.value.trim().toLowerCase();
  const matched = (registrationOptions.organizations || []).find((org) => org.name.toLowerCase() === val);
  if (matched) {
    const sectorEl = byId("registrationOrganizationSector");
    if (sectorEl && matched.sector && sectorEl.value !== matched.sector) {
      sectorEl.value = matched.sector;
      populateRegistrationDropdowns();
    }
    const typeEl = byId("registrationOrganizationType");
    if (typeEl && matched.organizationTypeId) {
      typeEl.value = matched.organizationTypeId;
      updateRegistrationConditionalFields();
    }
  }
});

byId("openOrganizationRegistration")?.addEventListener("click", showAccountTypeSelection);
byId("registrationTypeBackToLogin")?.addEventListener("click", () => {
  if (registrationTypeScreen) registrationTypeScreen.hidden = true;
  showLogin();
});
byId("changeAccountTypeBtn")?.addEventListener("click", () => {
  organizationRegistrationScreen.hidden = true;
  showAccountTypeSelection();
});
document.querySelectorAll("[data-account-type]").forEach((btn) => {
  btn.addEventListener("click", () => {
    const type = btn.getAttribute("data-account-type");
    if (type) startRegistrationFlow(type);
  });
});
byId("organizationRegistrationSignIn")?.addEventListener("click", async () => {
  if (auth.currentUser) await signOut(auth);
  showLogin();
});

organizationRegistrationForm?.addEventListener("submit", async (event) => {
  event.preventDefault();
  if (organizationRegistrationInProgress) return;
  showOrganizationRegistrationMessage("");
  const value = (id) => byId(id)?.value.trim() || "";
  const accountType = value("registrationAccountType");
  if (!["barangay", "lgu", "organization"].includes(accountType)) {
    showOrganizationRegistrationMessage("Select an account type.", true);
    return;
  }
  if (accountType === "barangay" && (!value("registrationOfficialBarangay") || !value("registrationPositionId"))) {
    showOrganizationRegistrationMessage("Select a barangay and an available position.", true);
    return;
  }
  if (accountType === "lgu" && (!value("registrationOffice") || !value("registrationLguPosition") || !value("registrationLguServiceType"))) {
    showOrganizationRegistrationMessage("Complete the office, position, and LGU service type.", true);
    return;
  }
  if (accountType === "organization" && (!value("registrationOrganizationSector") || !value("registrationOrganizationType"))) {
    showOrganizationRegistrationMessage("Select an organization sector and type.", true);
    return;
  }
  const email = value("registrationEmail").toLowerCase();
  const password = byId("registrationPassword").value;
  const proof = byId("registrationProofFile").files?.[0];
  const extension = proof?.name.split(".").pop()?.toLowerCase() || "";
  const contentType = ({ pdf: "application/pdf", jpg: "image/jpeg", jpeg: "image/jpeg", png: "image/png" })[extension];
  if (password.length < 10 || password !== byId("registrationConfirmPassword").value) {
    showOrganizationRegistrationMessage("Use a password of at least 10 characters and confirm it exactly.", true);
    return;
  }
  if (!/^09\d{9}$/.test(value("registrationContactNumber").replace(/\s/g, ""))) {
    showOrganizationRegistrationMessage("Enter an 11-digit Philippine mobile number starting with 09.", true);
    return;
  }
  if (!proof || !contentType || proof.size < 1 || proof.size > 8 * 1024 * 1024) {
    showOrganizationRegistrationMessage("Upload a PDF, JPG, or PNG proof document under 8 MB.", true);
    return;
  }
  const submit = organizationRegistrationForm.querySelector("button[type='submit']");
  organizationRegistrationInProgress = true;
  setButtonBusy(submit, true, accountType === "organization" ? "Creating account..." : "Submitting...");
  if (accountType === "organization") setRegistrationSubmitStage(submit, "Creating account...", "Step 1 of 3: Creating your account");
  let uploadedPath = "";
  let requestSaved = false;
  try {
    if (auth.currentUser && normalize(auth.currentUser.email) !== email) await signOut(auth);
    let user = auth.currentUser;
    let createdNewUser = false;
    if (!user) {
      try {
        user = (await createUserWithEmailAndPassword(auth, email, password)).user;
        createdNewUser = true;
      } catch (error) {
        if (error?.code !== "auth/email-already-in-use") throw error;
        try {
          user = (await signInWithEmailAndPassword(auth, email, password)).user;
        } catch (signInError) {
          throw new Error("This email is already registered. If you already have an account, please sign in. If you forgot your password, reset it from the sign-in screen.");
        }
      }
    }
    // A newly created Auth user cannot already have a staff profile. Avoid an
    // extra Firestore round trip on the usual Organization sign-up path.
    const profileSnapshot = createdNewUser && accountType === "organization"
      ? null : await getDoc(doc(db, "users", user.uid));
    if (profileSnapshot?.exists()) {
      if (!["organization_self_registration", "staff_self_registration"].includes(profileSnapshot.data().creationSource)
          || profileSnapshot.data().accountType !== accountType) {
        throw new Error("This email already has an E-SUGID account.");
      }
      if (profileSnapshot.data().accountStatus !== "pending_approval") {
        throw new Error("This organization request has already been reviewed. Sign in or contact the LGU administrator.");
      }
      requestSaved = true;
    } else {
      uploadedPath = `${accountType === "organization" ? "organization" : "staff"}_registration_proofs/${user.uid}/proof-${crypto.randomUUID()}.${extension}`;
      if (accountType === "organization") {
        setRegistrationSubmitStage(submit, "Uploading proof...", "Step 2 of 3: Uploading your proof document");
        await uploadRegistrationProof(storageRef(storage, uploadedPath), proof, contentType, (percent) => {
          setRegistrationSubmitStage(submit, `Uploading ${percent}%`, `Step 2 of 3: Uploading your proof document (${percent}%)`);
        });
      } else {
        await uploadBytes(storageRef(storage, uploadedPath), proof, { contentType });
      }
      const registration = {
        accountType,
        firstName: value("registrationFirstName"),
        middleName: value("registrationMiddleName"),
        lastName: value("registrationLastName"),
        extensionName: value("registrationExtension"),
        contactNumber: value("registrationContactNumber"),
        email, proofType: value("registrationProofType"),
        proofDocumentName: value("registrationProofDocumentName"), proofStoragePath: uploadedPath,
      };
      if (accountType === "organization") {
        setRegistrationSubmitStage(submit, "Saving request...", "Step 3 of 3: Saving your registration request");
        await httpsCallable(functions, "submitOrganizationRegistration")({
          ...registration,
          organizationName: value("registrationOrganizationName"),
          organizationSector: value("registrationOrganizationSector"),
          organizationTypeId: value("registrationOrganizationType"),
          organizationDescription: value("registrationOrganizationDescription"),
          organizationAddress: value("registrationOrganizationAddress"),
          barangay: value("registrationBarangay") || "",
          barangayId: barangayIdFor(value("registrationBarangay") || "") || "",
        });
      } else {
        const barangay = value("registrationOfficialBarangay");
        await submitStaffRegistrationCall({
          ...registration,
          ...(accountType === "barangay" ? {
            barangay, barangayId: barangayIdFor(barangay),
            positionId: value("registrationPositionId"), otherPosition: value("registrationOtherPosition"),
          } : {
            officeId: value("registrationOffice"), positionTitle: value("registrationLguPosition"),
            serviceTypeId: value("registrationLguServiceType"),
            serviceDescription: value("registrationLguServiceDescription"),
          }),
        });
      }
      requestSaved = true;
      uploadedPath = "";
    }
    if (accountType === "organization") showOrganizationRegistrationSuccess(email);
    let verificationSent = true;
    if (!user.emailVerified) {
      try { await sendEmailVerification(user, { url: ADMIN_PORTAL_URL }); }
      catch (error) { verificationSent = false; console.warn("Organization verification email failed", { code: error?.code }); }
    }
    await signOut(auth);
    organizationRegistrationForm.reset();
    updateRegistrationAccountType();
    if (accountType === "organization") {
      const status = byId("registrationEmailStatus");
      status.textContent = !verificationSent
        ? "We could not send the verification link. Sign in again to retry email verification."
        : user.emailVerified
          ? "Your email is already verified. Your request is waiting for LGU review."
          : `Verification link sent to ${email}. Check your inbox or spam folder.`;
      status.classList.toggle("is-error", !verificationSent);
      byId("registrationSuccessSignIn").disabled = false;
    } else {
      showLogin();
      setAuthMessage(verificationSent
        ? "Registration request submitted. Verify your email, then wait for LGU approval."
        : "Registration request submitted, but the verification email could not be sent. Sign in again to retry email verification.");
    }
  } catch (error) {
    if (requestSaved && accountType === "organization") {
      if (registrationSuccessScreen.hidden) showOrganizationRegistrationSuccess(email);
      const status = byId("registrationEmailStatus");
      status.textContent = "Your request was saved, but email verification could not be completed. Refresh this page, then sign in to retry.";
      status.classList.add("is-error");
      byId("registrationSuccessSignIn").disabled = false;
      await signOut(auth).catch(() => {});
    } else if (uploadedPath && auth.currentUser) {
      // A network error can arrive after the request committed. Keep its proof
      // unless the server confirms no pending profile was created.
      const profile = await getDoc(doc(db, "users", auth.currentUser.uid)).catch(() => null);
      if (profile && !profile.exists()) {
        await deleteObject(storageRef(storage, uploadedPath)).catch(() => {});
      }
    }
    if (!requestSaved || accountType !== "organization") {
      showOrganizationRegistrationMessage(callableErrorMessage(error), true);
    }
  } finally {
    organizationRegistrationInProgress = false;
    setButtonBusy(submit, false);
    const progress = byId("organizationRegistrationProgress");
    progress.hidden = true;
    progress.textContent = "";
  }
});
// Auth Helper Handlers
byId("forgotPasswordBtn").addEventListener("click", () => {
  const email = byId("email").value.trim();
  if (!email) {
    showToast("Enter your email address or username first.", true);
    byId("email").focus();
    return;
  }
  if (!email.includes("@")) {
    showToast("Username accounts must request an access reset from a municipal administrator.", true);
    return;
  }
  openModal("Reset Password", "Send a reset link?", `<p>We will send a password reset link to <strong>${escapeHtml(email)}</strong>. Please check your inbox (and spam folder) after clicking send.</p>`, `<button class="button button--secondary" type="button" onclick="closeModal()">Cancel</button><button class="button button--primary" type="button" id="confirmResetBtn">Send reset link</button>`);
  byId("confirmResetBtn").addEventListener("click", async () => {
    const btn = byId("confirmResetBtn");
    setButtonBusy(btn, true, "Sending…");
    try {
      await sendPasswordResetEmail(auth, email, { url: `${ADMIN_PORTAL_URL}/?reset=1` });
      closeModal();
      showToast("Reset link sent! Please check your email.");
    } catch (error) {
      showToast(humanAuthError(error), true);
      setButtonBusy(btn, false);
    }
  });
});

async function authorizeAdministrator(user) {
  const generation = state.sessionGeneration;
  const isCurrentSession = () => state.sessionGeneration === generation
    && auth.currentUser?.uid === user.uid;
  if (!isCurrentSession()) return;
  let profileSnapshot;
  try {
    profileSnapshot = await getDoc(doc(db, "users", user.uid));
    if (!isCurrentSession()) return;
    if (!profileSnapshot.exists()) {
      try {
        const recovery = await recoverPendingOrganizationRegistrationCall();
        if (!isCurrentSession()) return;
        if (recovery?.data?.recovered) {
          profileSnapshot = await getDoc(doc(db, "users", user.uid));
        }
      } catch (recoveryErr) {
        console.warn("Self-registration recovery attempt:", recoveryErr);
      }
    }
  } catch (error) {
    if (!isCurrentSession()) return;
    await signOut(auth);
    const denied = error?.code === "permission-denied" || String(error?.message || "").includes("permission");
    setAuthMessage(denied
      ? "Your account was found, but its staff profile cannot be accessed. Please contact the system administrator."
      : "We could not check your staff account. Check your connection and try again.", true);
    return;
  }

  if (!isCurrentSession()) return;
  const profile = profileSnapshot.data();
  const role = canonicalRole(profile?.role);
  const selfRegistration = ["organization_self_registration", "staff_self_registration"]
    .includes(profile?.creationSource);
  if (selfRegistration && accountStatus(profile) === "rejected") {
    await signOut(auth);
    setAuthMessage(`Registration request rejected. Reason: ${profile.rejectionReason || "Unable to verify account"}${profile.rejectionNote ? ` — ${profile.rejectionNote}` : ""}. Contact the LGU administrator if you need help.`, true);
    return;
  }
  if (selfRegistration
      && accountStatus(profile) !== "approved" && !user.emailVerified) {
    let sent = true;
    try { await sendEmailVerification(user, { url: ADMIN_PORTAL_URL }); }
    catch (error) { sent = false; console.warn("Organization verification email failed", { code: error?.code }); }
    await signOut(auth);
    setAuthMessage(sent
      ? "Verify your email using the link we sent. Your registration request remains pending LGU approval."
      : "Your request is pending, but verification email could not be sent. Try again later or contact the LGU administrator.", true);
    return;
  }
  const permittedRoles = ["super_admin", "mayor", "lgu", "barangay_captain", "barangay_vice_captain", "barangay_secretary", "barangay_councilor", "organization"];
  if (!profileSnapshot.exists() || !permittedRoles.includes(role) || accountStatus(profile) !== "approved") {
    await signOut(auth);
    setAuthMessage(!profileSnapshot.exists()
      ? "This login has no staff profile yet. Please contact the system administrator."
      : accountStatus(profile) !== "approved"
        ? (() => {
          const roleLabel = profile?.positionTitle || labelForRole(profile?.role);
          const assignment = profile?.organizationName
            || (profile?.barangay ? `Barangay ${profile.barangay}` : "");
          return `Account awaiting approval. Your ${roleLabel}${assignment ? ` account for ${assignment}` : " account"} is currently being reviewed. You will be notified once a decision is made.`;
        })()
        : "This account is not assigned to an admin or staff role.", true);
    return;
  }

  state.currentProfile = { id: user.uid, ...profile, legacyRole: normalize(profile.role), role, status: "approved" };
  if (profile.setupRequired === true) {
    if (profile.activationExpiresAt && dateValue(profile.activationExpiresAt) < Date.now()) {
      await signOut(auth);
      setAuthMessage("This temporary access has expired. Ask a municipal administrator to reset the account.", true);
      return;
    }
    pendingSetupUser = user;
    openInitialPasswordSetup();
    return;
  }
  await finishAdministratorAuthorization(user);
}

async function finishAdministratorAuthorization(user) {
  const generation = state.sessionGeneration;
  const profile = state.currentProfile;
  const isCurrentSession = () => state.sessionGeneration === generation
    && auth.currentUser?.uid === user.uid && state.currentProfile === profile;
  if (!isCurrentSession()) return;

  // Apply this office's policy before enabling controls or starting its listeners.
  const policyId = accessPolicyIdForProfile(profile);
  let policy = {};
  if (policyId) {
    try {
      const snapshot = await getDoc(doc(db, "access_policies", policyId));
      if (!isCurrentSession()) return;
      if (snapshot.exists()) policy = snapshot.data() || {};
    } catch (error) {
      if (!isCurrentSession()) return;
      console.error("Office access settings could not be loaded", { code: error?.code });
      await signOut(auth);
      if (!auth.currentUser) {
        setAuthMessage("Your office access settings could not be loaded. Check your connection and sign in again.", true);
      }
      return;
    }
  }
  state.currentAccessPolicy = policy;
  showDashboard(user);

  try {
    configureRoleAccess();
    attachRealtimeListeners();
  } catch (error) {
    console.error("Staff dashboard initialization failed", error);
    showToast("You are signed in, but part of the dashboard could not load. Refresh the page to try again.", true);
  }

  // Non-blocking background sync
  (async () => {
    if (isCurrentSession() && user.email && normalize(user.email) !== normalize(profile.email)) {
      try {
        const synced = await syncStaffEmailCall();
        if (isCurrentSession()) profile.email = synced.data.email;
      } catch (error) {
        console.error("Verified login email could not be synchronized", error);
      }
    }
    try {
      await updateDoc(doc(db, "users", user.uid), {
        lastLoginAt: serverTimestamp(),
        lastActiveAt: serverTimestamp(),
        loginHistory: arrayUnion(new Date().toISOString())
      });
    } catch (error) {
      console.warn("Could not record last login timestamp:", error);
    }
  })();
}

window.toggleSetupPasswordVisibility = (inputId, button) => {
  const input = byId(inputId);
  if (!input) return;
  const isCurrentlyPassword = input.type === "password";
  input.type = isCurrentlyPassword ? "text" : "password";
  const icon = button?.querySelector(".material-symbols-rounded");
  if (icon) icon.textContent = isCurrentlyPassword ? "visibility_off" : "visibility";
  button?.setAttribute("aria-label", isCurrentlyPassword ? "Hide password" : "Show password");
};

window.onInitialPasswordInput = () => {
  const newPw = byId("initialNewPassword")?.value || "";
  const confirmPw = byId("initialConfirmPassword")?.value || "";
  
  const lengthRule = byId("setupRuleLength");
  const matchRule = byId("setupRuleMatch");
  const strengthBar = byId("setupStrengthBar");
  const strengthLabel = byId("setupStrengthLabel");

  const hasLength = newPw.length >= 6;
  const matches = Boolean(confirmPw && newPw === confirmPw);

  if (lengthRule) {
    lengthRule.classList.toggle("is-met", hasLength);
    const icon = lengthRule.querySelector(".rule-icon");
    if (icon) icon.textContent = hasLength ? "check_circle" : "radio_button_unchecked";
  }

  if (matchRule) {
    matchRule.classList.toggle("is-met", matches);
    const icon = matchRule.querySelector(".rule-icon");
    if (icon) icon.textContent = matches ? "check_circle" : "radio_button_unchecked";
  }

  if (strengthBar && strengthLabel) {
    if (!newPw) {
      strengthBar.style.width = "0%";
      strengthBar.className = "setup-strength-bar";
      strengthLabel.textContent = "Enter password";
      strengthLabel.style.color = "light-dark(#557567, var(--textSecondary))";
      strengthLabel.style.background = "light-dark(#e2ece6, var(--surfaceAlt))";
    } else if (newPw.length < 6) {
      strengthBar.style.width = "30%";
      strengthBar.className = "setup-strength-bar is-weak";
      strengthLabel.textContent = "Too short (min 6)";
      strengthLabel.style.color = "light-dark(#b91c1c, var(--error))";
      strengthLabel.style.background = "light-dark(#fee2e2, var(--errorSurface))";
    } else if (newPw.length >= 8 && /[A-Z]/.test(newPw) && /[0-9]/.test(newPw)) {
      strengthBar.style.width = "100%";
      strengthBar.className = "setup-strength-bar is-strong";
      strengthLabel.textContent = "Strong password";
      strengthLabel.style.color = "light-dark(#065f46, var(--primaryGreen))";
      strengthLabel.style.background = "light-dark(#d1fae5, var(--successSurface))";
    } else {
      strengthBar.style.width = "65%";
      strengthBar.className = "setup-strength-bar is-medium";
      strengthLabel.textContent = "Good password";
      strengthLabel.style.color = "light-dark(#92400e, var(--warning))";
      strengthLabel.style.background = "light-dark(#fef3c7, var(--warningSurface))";
    }
  }
};

