function fallbackBarangayFeatureCollection(groups) {
  return {
    type: "FeatureCollection",
    features: BARANGAYS.map((name) => {
      const barangayId = barangayIdFor(name);
      const group = groups.get(barangayId);
      const coords = BARILI_BARANGAY_CENTERS[name] || [123.5334, 10.1131];
      return {
        type: "Feature",
        id: barangayId,
        geometry: {
          type: "Point",
          coordinates: coords
        },
        properties: {
          barangayId,
          barangayName: name,
          activeCount: group?.activeCount || 0
        }
      };
    })
  };
}

function concernMapStyle(mapType = state.concernMapType || "roadmap") {
  let lyrs = "m";
  if (mapType === "hybrid" || mapType === "satellite") lyrs = "y";
  else if (mapType === "terrain") lyrs = "p";

  return {
    version: 8,
    sources: {
      "google-maps": {
        type: "raster",
        tiles: [
          `https://mt0.google.com/vt/lyrs=${lyrs}&hl=en&gl=ph&scale=2&x={x}&y={y}&z={z}`,
          `https://mt1.google.com/vt/lyrs=${lyrs}&hl=en&gl=ph&scale=2&x={x}&y={y}&z={z}`,
          `https://mt2.google.com/vt/lyrs=${lyrs}&hl=en&gl=ph&scale=2&x={x}&y={y}&z={z}`,
          `https://mt3.google.com/vt/lyrs=${lyrs}&hl=en&gl=ph&scale=2&x={x}&y={y}&z={z}`
        ],
        tileSize: 256,
        attribution: "Map data © Google"
      }
    },
    layers: [
      {
        id: "google-tiles",
        type: "raster",
        source: "google-maps",
        paint: {
          "raster-opacity": 1.0,
          "raster-resampling": "linear"
        }
      }
    ]
  };
}

function concernMapBounds(geoJson) {
  const bounds = new maplibregl.LngLatBounds();
  const visit = (coordinates) => {
    if (!Array.isArray(coordinates)) return;
    if (coordinates.length >= 2 && coordinates.every((value) => typeof value === "number")) {
      bounds.extend(coordinates);
      return;
    }
    coordinates.forEach(visit);
  };
  geoJson?.features?.forEach((feature) => visit(feature.geometry?.coordinates));
  return bounds.isEmpty() ? null : bounds;
}

function concernMapFitToBarili(map = state.concernMapInstance, assignedBarangayId = concernMapAssignedBarangayId(), animate = false) {
  const bounds = concernMapBounds(state.concernMapRenderedGeoJson) || BARILI_BOUNDS;
  window.requestAnimationFrame(() => {
    if (!map || map !== state.concernMapInstance) return;
    const container = map.getContainer();
    if (container.clientWidth < 80 || container.clientHeight < 80) return;
    map.resize();
    map.fitBounds(bounds, {
      padding: assignedBarangayId ? 36 : 28,
      duration: animate ? 700 : 0,
      maxZoom: 12.8,
      pitch: assignedBarangayId ? 28 : 0,
      bearing: assignedBarangayId ? -5 : 0
    });
    state.concernMapScopeId = assignedBarangayId;
  });
}

function focusBariliOnConcernMap() {
  if (!state.concernMapInstance) return;
  concernMapFitToBarili(state.concernMapInstance, concernMapAssignedBarangayId(), true);
}

function setConcernMapType(type = "roadmap") {
  state.concernMapType = type;
  document.querySelectorAll(".concern-map-type-btn").forEach((btn) => {
    const active = btn.dataset.mapType === type;
    btn.classList.toggle("is-active", active);
    btn.setAttribute("aria-selected", String(active));
  });
  if (state.concernMapInstance) {
    state.concernMapInstance.setStyle(concernMapStyle(type));
  }
}

function createConcernMapPopupContent(properties) {
  const content = document.createElement("div");
  content.className = "concern-map-popup-card";
  const name = properties.barangayName || "Barangay";
  const activeCount = Number(properties.activeCount || 0);
  const color = concernMapCountColor(activeCount);
  
  content.innerHTML = `
    <div class="concern-map-popup-card__header">
      <span class="concern-map-popup-card__dot" style="background:${color}"></span>
      <strong class="concern-map-popup-card__title">${escapeHtml(name)}</strong>
    </div>
    <div class="concern-map-popup-card__meta">
      <span class="concern-map-popup-card__count" style="color:var(--${activeCount >= 10 ? 'onBrandError' : activeCount >= 4 ? 'onBrandWarning' : 'onBrandSuccess'})">${activeCount} Active Concern${activeCount === 1 ? "" : "s"}</span>
      <span class="concern-map-popup-card__action">Click to inspect</span>
    </div>
  `;
  return content;
}

function showConcernMapDetails(barangayId) {
  const assignedBarangayId = concernMapAssignedBarangayId();
  if (assignedBarangayId && barangayId !== assignedBarangayId) return;
  const group = state.concernMapGroups?.get(barangayId);
  const panel = byId("concernMapDetail");
  if (!group || !panel) return;
  state.selectedConcernMapBarangayId = barangayId;
  byId("concernMapDetailName").textContent = group.name.toUpperCase();
  byId("concernMapDetailActive").textContent = formatNumber(group.activeCount);
  byId("concernMapDetailNew").textContent = formatNumber(group.newCount);
  byId("concernMapDetailHandled").textContent = formatNumber(group.beingHandledCount);
  byId("concernMapDetailNeedsInfo").textContent = formatNumber(group.needsInformationCount);
  byId("concernMapDetailCategory").textContent = group.mostCommonCategory || "None";
  panel.hidden = false;
  panel.scrollIntoView({ behavior: "smooth", block: "nearest" });
  byId("viewConcernMapBarangay")?.focus({ preventScroll: true });
}

function destroyConcernMap() {
  if (state.concernMapOverlayFrame) window.cancelAnimationFrame(state.concernMapOverlayFrame);
  state.concernMapPopup?.remove();
  state.concernMapInstance?.remove();
  state.concernMapInstance = null;
  state.concernMapPopup = null;
  state.concernMapOverlayFrame = null;
  state.concernMapScopeId = null;
  state.concernMapRenderedGeoJson = null;
  state.concernMapOutsideMask = null;
  state.concernMapGroups = new Map();
  state.selectedConcernMapBarangayId = null;
  const detail = byId("concernMapDetail");
  if (detail) detail.hidden = true;
}

function setupConcernMapLayers(map) {
  if (!map || !state.concernMapRenderedGeoJson) return;
  const assignedBarangayId = concernMapAssignedBarangayId();

  // 1. Outside Barili Dimming Mask (prominently highlights Barili municipality)
  const mask = state.concernMapOutsideMask || createOutsideBariliMask(state.concernMapGeoJson);
  if (mask) {
    state.concernMapOutsideMask = mask;
    if (!map.getSource("outside-barili-mask")) {
      map.addSource("outside-barili-mask", {
        type: "geojson",
        data: mask
      });
    } else {
      map.getSource("outside-barili-mask").setData(mask);
    }

    if (map.getLayer("outside-barili-mask-layer")) {
      map.removeLayer("outside-barili-mask-layer");
    }

    if (!map.getLayer("outside-barili-perimeter")) {
      map.addLayer({
        id: "outside-barili-perimeter",
        type: "line",
        source: "outside-barili-mask",
        paint: {
          "line-color": "#059669",
          "line-width": 1.1,
          "line-opacity": 0.50
        }
      });
    }
  }

  // 2. Barili Barangay Concern Boundaries Source
  if (!map.getSource(CONCERN_MAP_SOURCE_ID)) {
    map.addSource(CONCERN_MAP_SOURCE_ID, {
      type: "geojson",
      data: state.concernMapRenderedGeoJson,
      promoteId: "barangayId"
    });
  } else {
    map.getSource(CONCERN_MAP_SOURCE_ID).setData(state.concernMapRenderedGeoJson);
  }

  // 3. Fill Layer
  if (!map.getLayer(CONCERN_MAP_FILL_LAYER_ID)) {
    map.addLayer({
      id: CONCERN_MAP_FILL_LAYER_ID,
      type: "fill",
      source: CONCERN_MAP_SOURCE_ID,
      paint: {
        "fill-color": concernMapFillColorExpression(assignedBarangayId),
        "fill-opacity": [
          "case",
          ["boolean", ["feature-state", "hover"], false],
          0.24,
          ...(assignedBarangayId
            ? [["==", ["get", "barangayId"], assignedBarangayId], 0.22]
            : []),
          ["==", ["get", "activeCount"], 0],
          0.015,
          0.18
        ]
      }
    });
  }

  // 4. Extrusion Layer (if assigned barangay)
  if (!map.getLayer(CONCERN_MAP_EXTRUSION_LAYER_ID)) {
    map.addLayer({
      id: CONCERN_MAP_EXTRUSION_LAYER_ID,
      type: "fill-extrusion",
      source: CONCERN_MAP_SOURCE_ID,
      filter: ["==", ["get", "barangayId"], assignedBarangayId || "__none__"],
      paint: {
        "fill-extrusion-color": concernMapCountColorExpression(),
        "fill-extrusion-height": assignedBarangayId ? 160 : 0,
        "fill-extrusion-base": 0,
        "fill-extrusion-opacity": 0.75,
        "fill-extrusion-vertical-gradient": true
      }
    });
  }

  // 5. Line Layer (barangay internal boundaries - light, delicate stroke)
  if (!map.getLayer(CONCERN_MAP_LINE_LAYER_ID)) {
    map.addLayer({
      id: CONCERN_MAP_LINE_LAYER_ID,
      type: "line",
      source: CONCERN_MAP_SOURCE_ID,
      paint: {
        "line-color": [
          "case",
          ["boolean", ["feature-state", "hover"], false],
          "#059669",
          ...(assignedBarangayId
            ? [["==", ["get", "barangayId"], assignedBarangayId], "#d97706"]
            : []),
          "#059669"
        ],
        "line-width": [
          "case",
          ["boolean", ["feature-state", "hover"], false],
          1.1,
          ...(assignedBarangayId
            ? [["==", ["get", "barangayId"], assignedBarangayId], 1.5]
            : []),
          0.60
        ],
        "line-opacity": [
          "case",
          ["boolean", ["feature-state", "hover"], false],
          0.70,
          0.30
        ]
      }
    });
  }

  // 6. Highlight Layer
  if (!map.getLayer(CONCERN_MAP_HIGHLIGHT_LAYER_ID)) {
    map.addLayer({
      id: CONCERN_MAP_HIGHLIGHT_LAYER_ID,
      type: "line",
      source: CONCERN_MAP_SOURCE_ID,
      filter: ["==", ["get", "barangayId"], assignedBarangayId || "__none__"],
      paint: {
        "line-color": "#f59e0b",
        "line-width": 2.2,
        "line-opacity": 0.75,
        "line-blur": 1.0
      }
    });
  }
}

function initializeConcernMap() {
  if (state.concernMapInstance || !state.concernMapRenderedGeoJson) return;
  const container = byId("concernMap");
  if (!container) return;
  try {
    const styleObj = concernMapStyle(state.concernMapType || "roadmap");
    const map = new maplibregl.Map({
      container,
      style: styleObj,
      center: BARILI_CENTER,
      zoom: 11.0,
      minZoom: 9.5,
      maxZoom: 16.5,
      maxBounds: BARILI_MAX_BOUNDS,
      attributionControl: false,
      antialias: true
    });
    state.concernMapInstance = map;
    state.concernMapPopup = new maplibregl.Popup({ closeButton: false, closeOnClick: false, offset: 12 });
    map.addControl(new maplibregl.NavigationControl({ showCompass: false }), "top-right");

    map.on("style.load", () => {
      setupConcernMapLayers(map);
      concernMapFitToBarili(map);
    });

    let hoveredBarangayId = null;
    map.on("mousemove", CONCERN_MAP_FILL_LAYER_ID, (event) => {
      const feature = event.features?.[0];
      if (!feature) return;
      const barangayId = feature.properties?.barangayId;
      const assignedBarangayId = concernMapAssignedBarangayId();
      if (assignedBarangayId && barangayId !== assignedBarangayId) {
        if (hoveredBarangayId) map.setFeatureState({ source: CONCERN_MAP_SOURCE_ID, id: hoveredBarangayId }, { hover: false });
        hoveredBarangayId = null;
        map.getCanvas().style.cursor = "";
        state.concernMapPopup?.remove();
        return;
      }
      if (hoveredBarangayId && hoveredBarangayId !== barangayId) {
        map.setFeatureState({ source: CONCERN_MAP_SOURCE_ID, id: hoveredBarangayId }, { hover: false });
      }
      hoveredBarangayId = barangayId;
      map.setFeatureState({ source: CONCERN_MAP_SOURCE_ID, id: hoveredBarangayId }, { hover: true });
      map.getCanvas().style.cursor = "pointer";
      state.concernMapPopup
        .setLngLat(event.lngLat)
        .setDOMContent(createConcernMapPopupContent(feature.properties))
        .addTo(map);
    });

    map.on("mouseleave", CONCERN_MAP_FILL_LAYER_ID, () => {
      if (hoveredBarangayId) map.setFeatureState({ source: CONCERN_MAP_SOURCE_ID, id: hoveredBarangayId }, { hover: false });
      hoveredBarangayId = null;
      map.getCanvas().style.cursor = "";
      state.concernMapPopup?.remove();
    });

    map.on("click", CONCERN_MAP_FILL_LAYER_ID, (event) => {
      const barangayId = event.features?.[0]?.properties?.barangayId;
      const assignedBarangayId = concernMapAssignedBarangayId();
      if (barangayId && (!assignedBarangayId || barangayId === assignedBarangayId)) {
        showConcernMapDetails(barangayId);
      }
    });

    if (typeof ResizeObserver !== "undefined") {
      const shell = byId("concernMapShell") || container;
      const ro = new ResizeObserver(() => {
        const activeMap = state.concernMapInstance;
        activeMap?.resize();
        if (activeMap && state.concernMapScopeId !== concernMapAssignedBarangayId()) {
          concernMapFitToBarili(activeMap);
        }
      });
      ro.observe(shell);
    }
    window.addEventListener("resize", () => state.concernMapInstance?.resize());

    map.on("error", (event) => {
      if (event?.error) console.error("Concern map error", event.error);
    });
  } catch (error) {
    console.error("Concern map could not be initialized", error);
    container.innerHTML = '<div class="concern-map-load-error">The map could not be loaded.</div>';
  }
}

function updateConcernMap() {
  const municipalView = byId("municipalConcernMap");
  const barangayView = byId("barangayConcernInsights");
  const role = canonicalRole(state.currentProfile?.role);
  const isBarangay = isBarangayRole(role) || canManageBarangay(role) || Boolean(state.currentProfile?.barangay && String(role).includes("barangay"));
  const showMunicipalMap = ["super_admin", "mayor", "organization", "lgu"].includes(role) && !isBarangay;

  if (isBarangay) {
    if (municipalView) municipalView.hidden = true;
    if (barangayView) barangayView.hidden = false;
    updateBarangayConcernOverview();
    return;
  }

  if (barangayView) barangayView.hidden = true;
  const orgInsights = byId("organizationConcernInsights");
  if (orgInsights) orgInsights.hidden = true;
  if (municipalView) municipalView.hidden = !showMunicipalMap;
  if (!showMunicipalMap) return;

  const showBarangayMap = false;
  const assignedBarangayId = "";
  const assignedBarangay = "";

  const isLgu = role === "lgu";
  const deptName = isLgu ? currentStaffDepartmentName() : "";
  if (byId("concernMapEyebrow")) {
    byId("concernMapEyebrow").textContent = showBarangayMap ? "Barangay concern overview" : "Concern overview";
  }
  byId("concernMapTitle").textContent = showBarangayMap && assignedBarangay
    ? `${assignedBarangay.toUpperCase()} CONCERN MAP`
    : "CONCERN MAP";
  byId("concernMapSubtitle").textContent = showBarangayMap && assignedBarangay
    ? `Active concerns assigned to Barangay ${assignedBarangay}`
    : isLgu && deptName
      ? `Active ${deptName} concerns across Barili`
      : "Current active concerns across Barili";
  if (byId("topConcernLabel")) {
    byId("topConcernLabel").textContent = showBarangayMap ? "Assigned Barangay" : "Most Active Barangay";
  }
  const scopeBadge = byId("concernMapScopeBadge");
  if (scopeBadge) scopeBadge.hidden = !showBarangayMap;
  if (byId("concernMapScopeName")) byId("concernMapScopeName").textContent = assignedBarangay;
  byId("concernMapShell")?.classList.toggle("is-barangay-scope", showBarangayMap);

  if (!state.concernMapGeoJson) {
    if (!state.concernMapLoading) {
      state.concernMapLoading = fetch("assets/barili-barangays.geojson")
        .then((response) => { if (!response.ok) throw new Error("Boundary data unavailable"); return response.json(); })
        .then((data) => {
          if (data.type !== "FeatureCollection" || !Array.isArray(data.features)) throw new Error("Invalid boundary data");
          state.concernMapGeoJson = data;
          state.concernMapOutsideMask = createOutsideBariliMask(data);
          state.concernMapLoading = null;
          updateConcernMap();
        })
        .catch((error) => {
          console.warn("Boundary GeoJSON fetch failed, using verified Barili points fallback:", error);
          state.concernMapLoading = null;
          state.concernMapGeoJson = fallbackBarangayFeatureCollection(state.concernMapGroups || createConcernMapGroups());
          updateConcernMap();
        });
    }
    return;
  }

  state.concernMapGroups = createConcernMapGroups();
  state.concernMapRenderedGeoJson = concernMapFeatureCollection(state.concernMapGroups);
  if (!state.concernMapOutsideMask && state.concernMapGeoJson) {
    state.concernMapOutsideMask = createOutsideBariliMask(state.concernMapGeoJson);
  }
  const ranked = [...state.concernMapGroups.values()]
    .sort((left, right) => right.activeCount - left.activeCount || left.name.localeCompare(right.name));
  const top = showBarangayMap ? state.concernMapGroups.get(assignedBarangayId) : ranked[0];
  const hasActiveConcerns = Boolean(top?.activeCount);
  if (byId("topConcernBarangay")) {
    byId("topConcernBarangay").textContent = showBarangayMap
      ? (top?.name || assignedBarangay || "Unassigned")
      : (hasActiveConcerns ? top.name : "None");
  }
  const topConcernNum = hasActiveConcerns ? formatNumber(top.activeCount) : "0";
  const topConcernLabel = hasActiveConcerns
    ? `Active Concern${top.activeCount === 1 ? "" : "s"}`
    : "Active Concerns";
  const topConcernEl = byId("topConcernCount");
  if (topConcernEl) {
    topConcernEl.setAttribute("aria-label", `${topConcernNum} ${topConcernLabel}`);
    topConcernEl.innerHTML = `<span class="top-concern-kpi-num">${topConcernNum}</span><span class="top-concern-kpi-label">${topConcernLabel}</span>`;
  }
  byId("concernMapEmpty").textContent = showBarangayMap
    ? `No active concerns in Barangay ${assignedBarangay}.`
    : "No active concerns across Barili.";
  byId("concernMapEmpty").hidden = hasActiveConcerns;

  if (showBarangayMap && state.selectedConcernMapBarangayId !== assignedBarangayId) closeConcernMapDetails();
  else if (state.selectedConcernMapBarangayId) showConcernMapDetails(state.selectedConcernMapBarangayId);
  if (!state.concernMapInstance) initializeConcernMap();
  else {
    const source = state.concernMapInstance.getSource(CONCERN_MAP_SOURCE_ID);
    if (source) source.setData(state.concernMapRenderedGeoJson);
    const maskSource = state.concernMapInstance.getSource("outside-barili-mask");
    if (maskSource && state.concernMapOutsideMask) maskSource.setData(state.concernMapOutsideMask);
    window.requestAnimationFrame(() => {
      state.concernMapInstance?.resize();
      if (state.concernMapScopeId !== assignedBarangayId) concernMapFitToBarili(state.concernMapInstance, assignedBarangayId);
    });
  }
}

function renderDashboardEmergencyBanner() {
  const banner = byId("dashboardActiveEmergencyBanner") || byId("barangayActiveEmergencyBanner");
  if (!banner) return;
  banner.hidden = true;
  banner.style.display = "none";
}

const renderBarangayEmergencyBanner = renderDashboardEmergencyBanner;

window.openDashboardEmergency = () => {
  const banner = byId("dashboardActiveEmergencyBanner") || byId("barangayActiveEmergencyBanner");
  const alertId = banner?.dataset.alertId;
  navigateTo("emergency");
  if (alertId && typeof window.openAlertDetails === "function") {
    window.openAlertDetails(alertId);
  }
};

const PHILIPPINE_TIME_ZONE = "Asia/Manila";
const philippineDateFormatter = new Intl.DateTimeFormat("en-PH", {
  timeZone: PHILIPPINE_TIME_ZONE,
  year: "numeric",
  month: "2-digit",
  day: "2-digit"
});

function philippineDateParts(value) {
  const date = parseDate(value);
  if (!date.valueOf()) return null;
  const parts = Object.fromEntries(
    philippineDateFormatter.formatToParts(date)
      .filter((part) => part.type !== "literal")
      .map((part) => [part.type, Number(part.value)])
  );
  return parts.year && parts.month && parts.day ? parts : null;
}

function philippineDateKey(value) {
  const parts = philippineDateParts(value);
  return parts ? `${parts.year}-${String(parts.month).padStart(2, "0")}-${String(parts.day).padStart(2, "0")}` : "";
}

function philippineMonthKey(value) {
  const parts = philippineDateParts(value);
  return parts ? `${parts.year}-${String(parts.month).padStart(2, "0")}` : "";
}

function concernCategoryTheme(categoryName) {
  const name = String(categoryName || "").toLowerCase();
  if (name.includes("environment") || name.includes("nature") || name.includes("tree")) {
    return { icon: "eco", color: "light-dark(#087454, var(--primaryGreen))", bg: "light-dark(#e6f7f0, var(--successSurface))", gradient: "linear-gradient(90deg, light-dark(#087454, var(--primaryGreen)), light-dark(#087f60, var(--primaryGreen)))", glow: "light-dark(rgba(14, 165, 122, 0.35), color-mix(in srgb, var(--primaryGreen) 35%, transparent))" };
  }
  if (name.includes("road") || name.includes("street") || name.includes("repair") || name.includes("pothole")) {
    return { icon: "construction", color: "light-dark(#2563eb, var(--info))", bg: "light-dark(#eff6ff, var(--infoSurface))", gradient: "linear-gradient(90deg, light-dark(#2563eb, var(--info)), light-dark(#60a5fa, var(--info)))", glow: "light-dark(rgba(37, 99, 235, 0.35), color-mix(in srgb, var(--info) 35%, transparent))" };
  }
  if (name.includes("waste") || name.includes("garbage") || name.includes("trash")) {
    return { icon: "delete_sweep", color: "light-dark(#995b00, var(--warning))", bg: "light-dark(#fef3c7, var(--warningSurface))", gradient: "linear-gradient(90deg, light-dark(#995b00, var(--warning)), light-dark(#fbbf24, var(--warning)))", glow: "light-dark(rgba(245, 158, 11, 0.35), color-mix(in srgb, var(--warning) 35%, transparent))" };
  }
  if (name.includes("safety") || name.includes("peace") || name.includes("crime") || name.includes("security")) {
    return { icon: "shield", color: "light-dark(#b52d38, var(--error))", bg: "light-dark(#fee2e2, var(--errorSurface))", gradient: "linear-gradient(90deg, light-dark(#b52d38, var(--error)), light-dark(#f87171, var(--error)))", glow: "light-dark(rgba(239, 68, 68, 0.35), color-mix(in srgb, var(--error) 35%, transparent))" };
  }
  if (name.includes("health") || name.includes("medical") || name.includes("clinic")) {
    return { icon: "local_hospital", color: "light-dark(#8b5cf6, var(--purple))", bg: "light-dark(#f3e8ff, var(--purpleSurface))", gradient: "linear-gradient(90deg, light-dark(#8b5cf6, var(--purple)), light-dark(#c084fc, var(--purple)))", glow: "light-dark(rgba(139, 92, 246, 0.35), color-mix(in srgb, var(--purple) 35%, transparent))" };
  }
  if (name.includes("water") || name.includes("electric") || name.includes("power") || name.includes("utility")) {
    return { icon: "bolt", color: "light-dark(#0284c7, var(--info))", bg: "light-dark(#e0f2fe, var(--infoSurface))", gradient: "linear-gradient(90deg, light-dark(#0284c7, var(--info)), light-dark(#38bdf8, var(--info)))", glow: "light-dark(rgba(2, 132, 199, 0.35), color-mix(in srgb, var(--info) 35%, transparent))" };
  }
  if (name.includes("flood") || name.includes("disaster")) {
    return { icon: "tsunami", color: "light-dark(#0369a1, var(--info))", bg: "light-dark(#e0f2fe, var(--infoSurface))", gradient: "linear-gradient(90deg, light-dark(#0369a1, var(--info)), light-dark(#38bdf8, var(--info)))", glow: "light-dark(rgba(3, 105, 161, 0.35), color-mix(in srgb, var(--info) 35%, transparent))" };
  }
  return { icon: "assignment", color: "light-dark(#0d9488, var(--primaryGreen))", bg: "light-dark(#ccfbf1, var(--successSurface))", gradient: "linear-gradient(90deg, light-dark(#0d9488, var(--primaryGreen)), light-dark(#2dd4bf, var(--primaryGreen)))", glow: "light-dark(rgba(13, 148, 136, 0.35), color-mix(in srgb, var(--primaryGreen) 35%, transparent))" };
}

function updateBarangayConcernOverview() {
  try {
    const barangayId = String(state.currentProfile?.barangayId || "").trim();
    const rawBarangayName = currentStaffBarangay() || state.currentProfile?.barangay || "";
    const formattedBarangay = rawBarangayName
      ? String(rawBarangayName).trim().replace(/\w\S*/g, (txt) => txt.charAt(0).toUpperCase() + txt.substr(1).toLowerCase())
      : "Barangay";
    const barangayName = rawBarangayName ? `Barangay ${formattedBarangay}` : "Your Barangay";

    // Update card title
    const titleEl = byId("barangayConcernTitle");
    if (titleEl) titleEl.textContent = `${formattedBarangay} Concern Overview`;

    // Filter concerns strictly for this barangay
    const barangayConcerns = (state.concerns || []).filter((item) => {
      if (barangayId && item.barangayId && String(item.barangayId).trim() !== barangayId) return false;
      return true;
    });

    // Group by Category and Rank by Concern Volume (Highest count on top)
    const catMap = new Map();
    barangayConcerns.forEach((item) => {
      const label = String(item.category || item.title || "General Concern").trim() || "General Concern";
      const key = normalize(label);
      const curr = catMap.get(key) || { label, count: 0 };
      curr.count++;
      catMap.set(key, curr);
    });
    const sortedCats = [...catMap.values()].sort((a, b) => b.count - a.count || a.label.localeCompare(b.label));
    const totalConcerns = barangayConcerns.length;
    const topCategory = sortedCats[0];
    state.barangayTopCategory = topCategory?.label || "";

    // 2. Update Note Subtitle
    const subtitleEl = byId("barangayOverviewSubtitle");
    const topCategories = sortedCats.slice(0, 5);
    if (subtitleEl) {
      const count = topCategories.length;
      const countText = count > 0 ? `top ${count}` : "the";
      subtitleEl.innerHTML = `<span class="material-symbols-rounded note-icon">info</span><span class="note-text"><strong>Note:</strong> Showing ${countText} most reported concerns</span>`;
    }

    // 3. Update Ranked Category List (Clean Monochromatic 3D Cards)
    const rankedList = byId("barangayRankedCategoryList");
    if (rankedList) {
      if (!sortedCats.length || totalConcerns === 0) {
        rankedList.innerHTML = `<div class="barangay-empty-categories">
          <div class="empty-shield-icon"><span class="material-symbols-rounded">verified_user</span></div>
          <strong>All clear in ${escapeHtml(barangayName)}!</strong>
          <p>No concern categories reported so far.</p>
        </div>`;
      } else {
        const maxCount = Math.max(...topCategories.map((item) => item.count), 1);
        rankedList.innerHTML = topCategories.map((cat) => {
          const theme = concernCategoryTheme(cat.label);
          const pct = Math.round((cat.count / totalConcerns) * 100);
          const fillWidth = Math.max(12, Math.round((cat.count / maxCount) * 100));

          return `<button type="button" class="category-rank-card" onclick="openBarangayConcernsByCategory('${escapeAttribute(cat.label)}')" aria-label="View concerns for category ${escapeAttribute(cat.label)}, count ${cat.count}">
            <div class="rank-gem-3d">
              <span class="material-symbols-rounded">${theme.icon}</span>
            </div>
            <div class="rank-body">
              <div class="rank-title-row">
                <span class="rank-category-name" title="${escapeAttribute(cat.label)}">${escapeHtml(cat.label)}</span>
                <span class="rank-percentage">${pct}%</span>
              </div>
              <div class="rank-3d-track" role="presentation">
                <div class="rank-3d-fill" style="width:${fillWidth}%;">
                  <i class="fill-gloss-highlight"></i>
                </div>
              </div>
            </div>
            <div class="rank-count-capsule-3d">
              <span>${formatNumber(cat.count)}</span>
              <span class="material-symbols-rounded rank-arrow-hint">arrow_forward</span>
            </div>
          </button>`;
        }).join("");
      }
    }

    // View All Button
    const viewAllText = byId("barangayViewAllText");
    if (viewAllText) {
      viewAllText.textContent = totalConcerns > 0 ? `View All ${formatNumber(totalConcerns)} Concerns` : "View All Concerns";
    }
  } catch (error) {
    console.error("updateBarangayConcernOverview error:", error);
  }
}

function updateBarangayConcernInsights() {
  updateBarangayConcernOverview();
}

window.openBarangayConcernsByStatus = (status = "all") => {
  window.jumpToPage("concerns");
  state.concernStatus = status;
  state.concernPage = 1;
  document.querySelectorAll("#concernStatusTabs button").forEach((button) => {
    button.classList.toggle("active", button.dataset.status === status);
  });
  renderConcerns();
};

window.openBarangayConcernsByCategory = (categoryName) => {
  window.jumpToPage("concerns");
  const isBarangay = isBarangayRole(state.currentProfile?.role);
  if (!isBarangay) {
    const brgyFilter = byId("concernBarangayFilter");
    const brgyName = currentStaffBarangay() || state.currentProfile?.barangay || "";
    if (brgyFilter && brgyName) {
      const opt = [...brgyFilter.options].find((item) => normalize(item.value) === normalize(brgyName));
      if (opt) brgyFilter.value = opt.value;
    }
  }

  // Clear filters so nothing is confusingly filtered
  const typeFilter = byId("concernTypeFilter");
  if (typeFilter) typeFilter.value = "all";
  const searchInput = byId("globalSearch") || byId("concernSearch");
  if (searchInput) searchInput.value = "";
  const yearSelect = byId("concernReportYear");
  if (yearSelect) yearSelect.value = "all";
  const monthSelect = byId("concernReportMonth");
  if (monthSelect) monthSelect.value = "all";

  // Directly open this category's concerns without filtering them out
  state.concernReportCategory = normalize(categoryName);
  state.concernCategorySubTab = null;
  state.concernStatus = "all";
  state.concernPage = 1;

  document.querySelectorAll("#concernStatusTabs button").forEach((button) => {
    button.classList.toggle("active", button.dataset.status === "all");
  });
  renderConcerns();
};

window.openBarangayTopCategory = () => {
  if (state.barangayTopCategory) {
    window.openBarangayConcernsByCategory(state.barangayTopCategory);
  } else {
    window.openBarangayConcerns();
  }
};

function openBarangayConcerns(barangay) {
  window.jumpToPage("concerns");
  const isBarangay = isBarangayRole(state.currentProfile?.role);
  if (!isBarangay) {
    const filter = byId("concernBarangayFilter");
    const option = [...filter.options].find((item) => normalize(item.value) === normalize(barangay));
    if (option) filter.value = option.value;
  }
  state.concernReportCategory = null;
  state.concernCategorySubTab = null;
  const typeFilter = byId("concernTypeFilter");
  if (typeFilter) typeFilter.value = "all";
  const searchInput = byId("globalSearch") || byId("concernSearch");
  if (searchInput) searchInput.value = "";
  const yearSelect = byId("concernReportYear");
  if (yearSelect) yearSelect.value = "all";
  const monthSelect = byId("concernReportMonth");
  if (monthSelect) monthSelect.value = "all";
  state.concernStatus = "all";
  state.concernPage = 1;
  document.querySelectorAll("#concernStatusTabs button").forEach((button) => button.classList.toggle("active", button.dataset.status === "all"));
  renderConcerns();
}
window.openBarangayConcerns = openBarangayConcerns;

