window.forwardRoutedConcern = async (id) => {
  const recipientId = byId("routingDestination")?.value || "";
  const referralReason = byId("routingReason")?.value.trim() || "";
  if (!recipientId) return;
  if (referralReason.length < 3) {
    showToast("Please enter a reason for the referral.", true);
    byId("routingReason")?.focus();
    return;
  }
  const button = modal.querySelector(".button--primary");
  setButtonBusy(button, true, "Forwarding...");
  try {
    await forwardConcernCall({ submissionId: id, recipientId, referralReason });
    closeModal();
    showToast(`Concern ${id} was referred.`);
    openConcern(id);
  } catch (error) {
    showToast(callableErrorMessage(error), true);
    setButtonBusy(button, false);
  }
};

function recipientAccountOptions(selectedId = "") {
  return state.users
    .filter((user) => accountStatus(user) === "approved" && canonicalRole(user.role) !== "resident")
    .map((user) => `<option value="${escapeAttribute(user.id)}" ${user.id === selectedId ? "selected" : ""}>${escapeHtml(user.name || user.email || user.id)} - ${escapeHtml(labelForRole(user.role))}</option>`)
    .join("");
}

window.openRecipientEditor = (id = "") => {
  if (!can("routing:manage")) return;
  const item = state.concernRecipients.find((recipient) => recipient.recipientId === id) || {};
  openModal(
    id ? "Manage Concern Recipient" : "Add Concern Recipient",
    "Only active recipients with a connected receiving account appear to residents.",
    `<form id="recipientEditorForm" onsubmit="event.preventDefault(); saveConcernRecipient('${safeId(id)}')">
      <label class="field field--full"><span>Display Name</span><input id="recipientDisplayName" maxlength="120" required value="${escapeAttribute(item.displayName || "")}" placeholder="e.g. Municipal Health Office"></label>
      <label class="field field--full"><span>Recipient Type</span><select id="recipientType"><option value="municipalOffice" ${item.recipientType === "municipalOffice" ? "selected" : ""}>Municipal Office</option><option value="partnerOrganization" ${item.recipientType === "partnerOrganization" ? "selected" : ""}>Partner Organization</option><option value="barangay" ${item.recipientType === "barangay" ? "selected" : ""}>Barangay Office</option></select></label>
      <label class="field field--full"><span>Connected Receiving Account</span><select id="recipientAccount"><option value="">Select an active account</option>${recipientAccountOptions(item.receiverAccountId || "")}</select></label>
      <label class="field field--full"><span>Categories Handled</span><input id="recipientCategories" value="${escapeAttribute((item.categoriesHandled || []).join(", "))}" placeholder="Health Services, Sanitation"></label>
      <label class="field field--full"><span>Fallback Recipient ID</span><input id="recipientFallback" maxlength="160" value="${escapeAttribute(item.fallbackRecipientId || "")}" placeholder="Optional"></label>
      <label class="toggle-row"><input id="recipientEnabled" type="checkbox" ${normalize(item.status || "active") === "active" && item.canReceiveConcerns !== false ? "checked" : ""}><span>Active and able to receive concerns</span></label>
    </form>`,
    `<button class="button button--secondary" type="button" onclick="closeModal()">Cancel</button>
     <button class="button button--primary" type="button" onclick="saveConcernRecipient('${safeId(id)}')">Save Recipient</button>`
  );
};

window.saveConcernRecipient = async (existingId = "") => {
  const displayName = byId("recipientDisplayName")?.value.trim() || "";
  const receiverAccountId = byId("recipientAccount")?.value || "";
  const enabled = byId("recipientEnabled")?.checked === true;
  if (!displayName || (enabled && !receiverAccountId)) {
    showToast(enabled ? "Display name and receiving account are required." : "Display name is required.", true);
    return;
  }
  const button = modal.querySelector(".button--primary");
  setButtonBusy(button, true, "Saving...");
  try {
    await manageConcernRecipientCall({
      recipientId: existingId || displayName,
      displayName,
      recipientType: byId("recipientType")?.value,
      receiverAccountId,
      categoriesHandled: (byId("recipientCategories")?.value || "").split(",").map((item) => item.trim()).filter(Boolean),
      fallbackRecipientId: byId("recipientFallback")?.value.trim() || "",
      status: enabled ? "active" : "inactive",
      canReceiveConcerns: enabled
    });
    closeModal();
    await loadConcernRecipients();
    showToast("Concern recipient saved.");
  } catch (error) {
    showToast(callableErrorMessage(error), true);
    setButtonBusy(button, false);
  }
};

function concernReportDate(item) {
  return parseDate(item.date || item.createdAt);
}

function usesConcernReportTable() {
  const role = canonicalRole(state.currentProfile?.role);
  return role === "super_admin" || role === "lgu" || canManageBarangay(role) || role === "organization";
}

function populateConcernReportYears() {
  const yearSelect = byId("concernReportYear");
  const monthSelect = byId("concernReportMonth");
  if (!yearSelect || !monthSelect) return;
  if (!monthSelect.dataset.initialized) {
    monthSelect.insertAdjacentHTML("beforeend", Array.from({ length: 12 }, (_, month) => `<option value="${month + 1}">${new Intl.DateTimeFormat("en-PH", { month: "long" }).format(new Date(2024, month, 1))}</option>`).join(""));
    monthSelect.dataset.initialized = "true";
  }
  const currentYear = new Date().getFullYear();
  const selectedYear = yearSelect.value || String(currentYear);
  const years = [...new Set([currentYear, ...state.concerns.map((item) => concernReportDate(item).getFullYear()).filter((year) => year > 1970)])].sort((a, b) => b - a);
  const optionsHtml = `<option value="all">All Years</option>` + years.map((year) => `<option value="${year}">${year}</option>`).join("");
  if (yearSelect.innerHTML !== optionsHtml) {
    yearSelect.innerHTML = optionsHtml;
  }
  if (selectedYear === "all") {
    yearSelect.value = "all";
  } else if (years.includes(Number(selectedYear))) {
    yearSelect.value = selectedYear;
  } else {
    yearSelect.value = String(years[0]);
  }
}

function matchesConcernReportPeriod(item) {
  const date = concernReportDate(item);
  const yearVal = byId("concernReportYear")?.value;
  const year = Number(yearVal);
  const monthVal = byId("concernReportMonth")?.value;
  const month = Number(monthVal);
  const yearMatch = !yearVal || yearVal === "all" || isNaN(year) || date.getFullYear() === year;
  const monthMatch = !monthVal || monthVal === "all" || isNaN(month) || date.getMonth() + 1 === month;
  return yearMatch && monthMatch;
}

function concernReportItems() {
  return getFilteredConcerns().filter(matchesConcernReportPeriod);
}

function concernReportCategoryRows(groups, total) {
  const totalResidentReports = total;
  return groups.map((group, index) => {
    const residentReports = group.residentReports;
    const pct = totalResidentReports > 0 ? (residentReports / totalResidentReports * 100).toFixed(1) : "0.0";
    return `<tr>
      <td class="concern-report-row-number"><span class="concern-report-num-badge">${String(index + 1).padStart(2, "0")}</span></td>
      <td>
        <button class="concern-report-category" type="button" onclick="openConcernReportCategory(${index})" aria-label="View ${escapeAttribute(group.category)} concerns">
          <span class="concern-report-category-icon material-symbols-rounded" aria-hidden="true">folder</span>
          <strong>${escapeHtml(group.category)}</strong>
        </button>
      </td>
      <td><span class="concern-report-count-pill"><strong>${formatNumber(residentReports)}</strong> ${residentReports === 1 ? 'Report' : 'Reports'}</span></td>
      <td>
        <div class="concern-report-pct-cell">
          <div class="concern-report-pct-bar" aria-hidden="true">
            <div class="concern-report-pct-fill" style="width: ${Math.min(100, Math.max(Number(pct) > 0 ? 6 : 0, Number(pct)))}%;"></div>
          </div>
          <span class="concern-report-pct-num">${pct}%</span>
        </div>
      </td>
      <td>
        <button class="concern-report-view" type="button" onclick="openConcernReportCategory(${index})">
          <span class="material-symbols-rounded" aria-hidden="true">visibility</span><span>View</span>
        </button>
      </td>
    </tr>`;
  }).join("");
}

let concernReportGroups = [];
window.setConcernReportSort = (key) => {
  if (!["category", "issues", "reports", "percent", "latest"].includes(key)) return;
  const current = state.concernReportSort;
  state.concernReportSort = {
    key,
    direction: current.key === key ? current.direction === "desc" ? "asc" : "desc" : key === "category" ? "asc" : "desc"
  };
  renderConcerns();
};

window.setConcernCategorySubTab = (tab) => {
  state.concernCategorySubTab = tab;
  renderConcerns();
};

function renderConcernReport(target) {
  const items = concernReportItems();
  const totalIssues = items.length;
  const groups = new Map();
  let totalResidentReports = 0;

  for (const item of items) {
    const category = String(item.category || "General Concern").trim() || "General Concern";
    const key = normalize(category);
    if (!groups.has(key)) groups.set(key, { key, category, items: [], residentReports: 0, latest: 0 });
    const group = groups.get(key);
    group.items.push(item);
    const count = Number(item.reporterCount) || (Array.isArray(item.reporterIds) ? item.reporterIds.length : 1);
    group.residentReports += count;
    totalResidentReports += count;
    group.latest = Math.max(group.latest, concernReportDate(item).valueOf());
  }

  const { key, direction } = state.concernReportSort;
  const sortDirection = direction === "asc" ? 1 : -1;
  concernReportGroups = [...groups.values()].sort((a, b) => {
    const comparison = key === "category" ? a.category.localeCompare(b.category)
      : key === "issues" ? a.items.length - b.items.length
      : ["reports", "percent"].includes(key) ? a.residentReports - b.residentReports
      : a.latest - b.latest;
    return comparison * sortDirection || b.latest - a.latest || a.category.localeCompare(b.category);
  });

  const selected = concernReportGroups.find((group) => group.key === state.concernReportCategory);
  const detailView = Boolean(selected);
  if (state.concernReportCategory && !selected) state.concernReportCategory = null;

  if (typeof byId === "function") {
    byId("page-concerns")?.classList.toggle("concern-category-detail-view", detailView);
    if (byId("concernStatusTabs")) byId("concernStatusTabs").hidden = detailView;
    const browserHeader = byId("concernBrowser")?.querySelector(".concern-browser-header");
    if (browserHeader) browserHeader.hidden = detailView;
  }

  if (detailView) {
    const groupedItems = selected.items.filter((item) => (Number(item.reporterCount) || 1) > 1 || (Array.isArray(item.reporterIds) && item.reporterIds.length > 1));
    const singleItems = selected.items.filter((item) => !groupedItems.includes(item));
    const subTab = state.concernCategorySubTab || (groupedItems.length > 0 ? "grouped" : "single");

    const reportCountStr = `${formatNumber(selected.residentReports)} ${selected.residentReports === 1 ? "Report" : "Reports"}`;
    const activityStr = selected.latest ? `Updated ${escapeHtml(formatShortDate(new Date(selected.latest)))}` : "";

    const categoryBanner = `
      <div class="concern-detail-header-card">
        <div class="concern-detail-header-card__top">
          <button type="button" class="concern-report-back" onclick="backToConcernReport()">
            <span class="material-symbols-rounded">arrow_back</span>
            <span>Back to categories</span>
          </button>
        </div>
        <div class="concern-detail-header-card__body">
          <div class="concern-detail-header-card__info">
            <div class="concern-detail-icon-box" aria-hidden="true">
              <span class="material-symbols-rounded">folder</span>
            </div>
            <div class="concern-detail-title-group">
              <div class="concern-detail-title-row">
                <h2>${escapeHtml(selected.category)}</h2>
                <span class="concern-report-count-badge">${reportCountStr}</span>
              </div>
              ${activityStr ? `<div class="concern-detail-activity"><span class="material-symbols-rounded">schedule</span><span>${activityStr}</span></div>` : ""}
            </div>
          </div>
          <div class="concern-subtabs concern-subtabs--pills" role="tablist">
            <button type="button" class="concern-subtab--pill ${subTab === 'grouped' ? 'active' : ''}" onclick="setConcernCategorySubTab('grouped')" role="tab" aria-selected="${subTab === 'grouped'}">
              <span class="material-symbols-rounded">groups</span>
              <span>Group Reports</span>
              ${groupedItems.length > 0 ? `<span class="concern-subtab-badge">${groupedItems.length}</span>` : ""}
            </button>
            <button type="button" class="concern-subtab--pill ${subTab === 'single' ? 'active' : ''}" onclick="setConcernCategorySubTab('single')" role="tab" aria-selected="${subTab === 'single'}">
              <span class="material-symbols-rounded">description</span>
              <span>Single Reports</span>
              ${singleItems.length > 0 ? `<span class="concern-subtab-badge">${singleItems.length}</span>` : ""}
            </button>
          </div>
        </div>
      </div>
    `;

    let contentHtml = "";
    if (subTab === "grouped") {
      if (!groupedItems.length) {
        contentHtml = `<div class="empty-state-card" style="padding: 44px 20px; text-align: center; background: light-dark(#fff, var(--surface)); border: 1px solid light-dark(#e2e8f0, var(--infoBorder)); border-radius: 12px; margin-bottom: 24px;">
          <span class="material-symbols-rounded" style="font-size: 40px; color: light-dark(#64748b, var(--textSecondary));">groups</span>
          <h3 style="margin: 12px 0 4px; color: light-dark(#0f172a, var(--textPrimary)); font-size: 16px; font-weight: 700;">No Group Reports</h3>
          <p style="color: light-dark(#64748b, var(--textSecondary)); margin: 0; font-size: 13.5px;">All submitted concerns in this category are single reports.</p>
        </div>`;
      } else {
        contentHtml = groupedItems.map((item) => {
          const count = Number(item.reporterCount || (item.reporterIds ? item.reporterIds.length : 1));
          const status = concernStatus(item);
          const rawRef = item.id.replace(/[^a-zA-Z0-9]/g, "");
          const groupRef = `GC-2024-${rawRef.slice(-5).padStart(5, "0")}`;
          const locString = item.location ? `${item.location}, Brgy. ${concernBarangay(item) || ""}` : `Barangay ${concernBarangay(item) || "Not specified"}`;

          return `
            <div class="grouped-concern-card">
              <div class="grouped-card-top">
                <div class="grouped-card-identity">
                  <div class="grouped-card-avatar" aria-hidden="true">
                    <span class="material-symbols-rounded">groups</span>
                  </div>
                  <div class="grouped-card-main-title">
                    <div class="grouped-card-badges">
                      <span class="grouped-card-ref">Ref. ${escapeHtml(groupRef)}</span>
                      <span class="grouped-card-count-badge">
                        <span class="material-symbols-rounded">groups</span>
                        <strong>${formatNumber(count)}</strong> Reports
                      </span>
                      <span class="grouped-card-status-pill">${statusPill(status)}</span>
                    </div>
                    <h3 class="grouped-card-title" title="${escapeAttribute(item.title || item.category || 'Concern')}">
                      ${escapeHtml(item.title || item.category || "Concern")}
                    </h3>
                    <div class="grouped-card-meta">
                      <span class="grouped-meta-item" title="Location">
                        <span class="material-symbols-rounded">location_on</span>
                        <span>${escapeHtml(locString)}</span>
                      </span>
                      <span class="grouped-meta-dot">·</span>
                      <span class="grouped-meta-item" title="Category">
                        <span class="material-symbols-rounded">folder</span>
                        <span>${escapeHtml(selected.category)}</span>
                      </span>
                      <span class="grouped-meta-dot">·</span>
                      <span class="grouped-meta-item" title="Date Submitted">
                        <span class="material-symbols-rounded">schedule</span>
                        <span>${escapeHtml(formatDate(item.date || item.createdAt))}</span>
                      </span>
                    </div>
                  </div>
                </div>
                <div class="grouped-card-action-wrap">
                  <button type="button" class="grouped-action-btn" onclick="toggleConcernActionDropdown('${safeId(item.id)}', event)">
                    <span class="material-symbols-rounded">tune</span>
                    <span>Action</span>
                    <span class="material-symbols-rounded arrow-icon">expand_more</span>
                  </button>
                  <div id="groupActionDropdown_${safeId(item.id)}" class="grouped-action-menu" hidden>
                    <button type="button" class="grouped-action-menu-item" onclick="triggerConcernActionFromDetail('${safeId(item.id)}', 'handle')" ${status === "being_handled" || status === "resolved" ? "disabled title='Already In Progress or Resolved'" : ""}>
                      <span class="action-dot dot-in-progress"></span>
                      <span>In Progress</span>
                    </button>
                    <button type="button" class="grouped-action-menu-item" onclick="triggerConcernActionFromDetail('${safeId(item.id)}', 'request_information')" ${status === "needs_information" || status === "resolved" ? "disabled title='Already Needs Information or Resolved'" : ""}>
                      <span class="action-dot dot-needs-attention"></span>
                      <span>Needs Information</span>
                    </button>
                    <button type="button" class="grouped-action-menu-item" onclick="triggerConcernActionFromDetail('${safeId(item.id)}', 'resolve')" ${status === "resolved" ? "disabled title='Already Resolved'" : ""}>
                      <span class="action-dot dot-resolved"></span>
                      <span>Resolved</span>
                    </button>
                  </div>
                </div>
              </div>
            </div>

            <!-- Resident Reports Table for this Group Concern -->
            <div class="grouped-resident-reports-section">
              <div class="grouped-resident-reports-header">
                <div class="grouped-resident-reports-title">
                  <span class="material-symbols-rounded">folder_shared</span>
                  <span>Resident Reports</span>
                  <span class="reports-count-pill">${formatNumber(count)}</span>
                </div>
              </div>
              <div id="residentReportsContainer_${safeId(item.id)}" class="grouped-resident-reports-table-wrap">
                <div class="grouped-submissions-loading" style="padding: 24px; text-align: center; color: light-dark(#64748b, var(--textSecondary));">
                  <span class="material-symbols-rounded spin" style="vertical-align: middle;">progress_activity</span>
                  <span style="margin-left: 8px;">Loading reports...</span>
                </div>
              </div>
            </div>
          `;
        }).join("");
      }
    } else {
      if (!singleItems.length) {
        contentHtml = `<div class="empty-state-card" style="padding: 44px 20px; text-align: center; background: light-dark(#fff, var(--surface)); border: 1px solid light-dark(#e2e8f0, var(--infoBorder)); border-radius: 12px; margin-bottom: 24px;">
          <span class="material-symbols-rounded" style="font-size: 40px; color: light-dark(#64748b, var(--textSecondary));">description</span>
          <h3 style="margin: 12px 0 4px; color: light-dark(#0f172a, var(--textPrimary)); font-size: 16px; font-weight: 700;">No Single Reports</h3>
          <p style="color: light-dark(#64748b, var(--textSecondary)); margin: 0; font-size: 13.5px;">All submitted concerns in this category are group reports.</p>
        </div>`;
      } else {
        contentHtml = `
          <div class="grouped-resident-reports-section">
            <div class="grouped-resident-reports-table-wrap">
              <table class="resident-reports-table">
                <thead>
                  <tr>
                    <th style="width: 44px; text-align: center;">#</th>
                    <th style="width: 130px;">Reference</th>
                    <th>Resident</th>
                    <th>Concern</th>
                    <th style="width: 140px;">Date</th>
                    <th style="width: 130px;">Status</th>
                    <th style="width: 160px; text-align: right;">Action</th>
                  </tr>
                </thead>
                <tbody>
                  ${singleItems.map((item, idx) => {
                    const status = concernStatus(item);
                    const subDate = formatDate(item.date || item.createdAt);
                    const refNo = `CON-${item.id.replace(/[^a-zA-Z0-9]/g, '').slice(-6).toUpperCase()}`;
                    const resName = residentName(item);
                    return `
                      <tr>
                        <td style="text-align: center; color: light-dark(#64748b, var(--textSecondary)); font-weight: 600;">${idx + 1}</td>
                        <td><span class="concern-ref-badge">${escapeHtml(refNo)}</span></td>
                        <td style="font-weight: 600; color: light-dark(#0f172a, var(--textPrimary));">${escapeHtml(resName)}</td>
                        <td style="max-width: 260px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: light-dark(#334155, var(--textPrimary));" title="${escapeAttribute(item.title || item.category || 'Concern')}">
                          ${escapeHtml(item.title || item.category || "Concern")}
                        </td>
                        <td style="color: light-dark(#64748b, var(--textSecondary)); font-size: 13px; white-space: nowrap;">${escapeHtml(subDate)}</td>
                        <td>${statusPill(status)}</td>
                        <td style="text-align: right;">
                          <div style="display: inline-flex; align-items: center; justify-content: flex-end;">
                            <div class="grouped-card-action-wrap" style="display: inline-block;">
                              <button type="button" class="grouped-action-btn-compact" onclick="toggleConcernActionDropdown('${safeId(item.id)}', event)" title="Action menu">
                                <span class="material-symbols-rounded">more_vert</span>
                              </button>
                              <div id="groupActionDropdown_${safeId(item.id)}" class="grouped-action-menu" hidden>
                                <button type="button" class="grouped-action-menu-item" onclick="openSingleOfficialReport('${safeId(item.id)}')">
                                  <span class="material-symbols-rounded" style="font-size: 16px; color: light-dark(#047857, var(--primaryGreen));">description</span>
                                  <span>Official Resident Concern Report</span>
                                </button>
                                <div class="grouped-action-divider" style="height: 1px; background: light-dark(#e2e8f0, var(--surfaceAlt)); margin: 4px 0;"></div>
                                <button type="button" class="grouped-action-menu-item" onclick="triggerConcernActionFromDetail('${safeId(item.id)}', 'handle')" ${status === "being_handled" || status === "resolved" ? "disabled title='Already In Progress or Resolved'" : ""}>
                                  <span class="action-dot dot-in-progress"></span>
                                  <span>In Progress</span>
                                </button>
                                <button type="button" class="grouped-action-menu-item" onclick="triggerConcernActionFromDetail('${safeId(item.id)}', 'request_information')" ${status === "needs_information" || status === "resolved" ? "disabled title='Already Needs Information or Resolved'" : ""}>
                                  <span class="action-dot dot-needs-attention"></span>
                                  <span>Needs Information</span>
                                </button>
                                <button type="button" class="grouped-action-menu-item" onclick="triggerConcernActionFromDetail('${safeId(item.id)}', 'resolve')" ${status === "resolved" ? "disabled title='Already Resolved'" : ""}>
                                  <span class="action-dot dot-resolved"></span>
                                  <span>Resolved</span>
                                </button>
                              </div>
                            </div>
                          </div>
                        </td>
                      </tr>
                    `;
                  }).join("")}
                </tbody>
              </table>
            </div>
          </div>
        `;
      }
    }

    target.innerHTML = `${categoryBanner}${contentHtml}`;

    if (subTab === "grouped" && groupedItems.length) {
      groupedItems.forEach((item) => {
        void loadResidentReportsForConcern(item.id);
      });
    }
    return;
  }

  const rows = concernReportCategoryRows(concernReportGroups, totalResidentReports);
  const sortHeading = (label, sortKey) => `<button class="concern-report-sort" type="button" onclick="setConcernReportSort('${sortKey}')" aria-label="Sort by ${label}">${label}<span class="material-symbols-rounded" aria-hidden="true">${key === sortKey ? direction === "asc" ? "arrow_upward" : "arrow_downward" : "unfold_more"}</span></button>`;
  const columns = [
    "No.",
    sortHeading("Category", "category"),
    sortHeading("Resident Reports", "reports"),
    sortHeading("% of Reports", "percent"),
    "Action"
  ];
  const empty = `
    <div class="concern-table-empty-box">
      <div class="concern-table-empty-icon" aria-hidden="true">
        <span class="material-symbols-rounded">inbox</span>
      </div>
      <h4>No Concerns Found</h4>
      <p>No concerns were recorded for this status and period.</p>
    </div>
  `;
  target.innerHTML = `<div class="concern-report-table-wrap"><table class="concern-report-table"><thead><tr>${columns.map((column) => `<th scope="col">${column}</th>`).join("")}</tr></thead><tbody>${rows || `<tr><td class="concern-report-empty" colspan="5">${empty}</td></tr>`}</tbody>${totalResidentReports ? `<tfoot><tr><th scope="row" colspan="2">Total</th><td><span class="concern-report-total-badge">${formatNumber(totalResidentReports)} Reports</span></td><td>100%</td><td>—</td></tr></tfoot>` : ""}</table></div>`;
}

window.openConcernReportCategory = (index) => {
  state.concernReportCategory = concernReportGroups[index]?.key || null;
  state.concernCategorySubTab = null;
  renderConcerns();
};
window.backToConcernReport = () => {
  state.concernReportCategory = null;
  state.concernCategorySubTab = null;
  renderConcerns();
};

window.toggleConcernActionDropdown = (id, event) => {
  if (event) {
    event.stopPropagation();
    event.preventDefault();
  }
  const allMenus = document.querySelectorAll(".grouped-action-menu");
  const targetMenu = byId(`groupActionDropdown_${id}`);
  const btn = event?.currentTarget || event?.target?.closest("button");
  const wasHidden = targetMenu ? targetMenu.hidden : true;
  allMenus.forEach((m) => {
    m.hidden = true;
    m.style.position = "";
    m.style.top = "";
    m.style.bottom = "";
    m.style.left = "";
    m.style.right = "";
  });
  if (targetMenu && wasHidden) {
    targetMenu.hidden = false;
    if (btn) {
      const rect = btn.getBoundingClientRect();
      targetMenu.style.position = "fixed";
      targetMenu.style.zIndex = "99999";
      const menuHeight = 145;
      const spaceBelow = window.innerHeight - rect.bottom;
      if (spaceBelow < menuHeight && rect.top > menuHeight) {
        targetMenu.style.top = `${Math.max(10, rect.top - menuHeight - 4)}px`;
      } else {
        targetMenu.style.top = `${Math.min(window.innerHeight - menuHeight - 10, rect.bottom + 4)}px`;
      }
      targetMenu.style.right = `${Math.max(12, window.innerWidth - rect.right)}px`;
      targetMenu.style.left = "auto";
    }
  }
};

if (typeof document !== "undefined" && !window._groupedActionMenuDismissBound) {
  window._groupedActionMenuDismissBound = true;
  document.addEventListener("click", (e) => {
    if (!e.target.closest(".grouped-card-action-wrap") && !e.target.closest(".grouped-action-menu")) {
      document.querySelectorAll(".grouped-action-menu").forEach((m) => { m.hidden = true; });
    }
  });
  window.addEventListener("scroll", () => {
    document.querySelectorAll(".grouped-action-menu").forEach((m) => { m.hidden = true; });
  }, true);
}

window.triggerConcernActionFromDetail = (id, action) => {
  document.querySelectorAll(".grouped-action-menu").forEach((m) => { m.hidden = true; });
  const item = findCase(id);
  const status = item ? concernStatus(item) : "";
  if (action === "handle") {
    if (status === "being_handled" || status === "resolved") return;
    window.startHandlingConcern(id);
  } else if (action === "request_information") {
    if (status === "needs_information" || status === "resolved") return;
    window.openAskInfoModal(id);
  } else if (action === "resolve") {
    if (status === "resolved") return;
    window.openResolveConcernModal(id);
  } else if (action === "issue_summons") {
    window.openIssueSummonsModal(id);
  } else if (action === "view_summons") {
    window.openOfficialSummonsModal(id);
  } else if (action === "notify_reporter") {
    window.openNotifyReporterModal(id);
  } else if (action === "print_summons") {
    window.printBarangaySummons(id);
  }
};

window.loadResidentReportsForConcern = async (parentId) => {
  const container = byId(`residentReportsContainer_${parentId}`);
  if (!container) return;
  const parent = findCase(parentId);
  if (!parent) return;

  try {
    const snapshot = await getDocs(collection(db, "submissions", parentId, "reports"));
    const subReports = snapshot.docs.map((docSnap) => ({ id: docSnap.id, ...docSnap.data() }))
      .sort((a, b) => dateValue(a.submittedAt) - dateValue(b.submittedAt));

    let allReports = [];
    if (subReports.length > 0) {
      allReports = subReports;
      const hasParentUser = subReports.some((r) => r.reporterId === parent.userId || r.id === parent.userId);
      if (!hasParentUser && parent.userId) {
        allReports.unshift({
          id: parent.userId,
          reporterId: parent.userId,
          reporterName: residentName(parent),
          submittedAt: parent.date || parent.createdAt,
          location: parent.location,
          description: parent.description || parent.title,
          attachmentUrl: parent.attachmentUrl || parent.imageUrl,
          isPrimary: true,
        });
      }
    } else {
      allReports = [{
        id: parent.userId || "primary",
        reporterId: parent.userId || "primary",
        reporterName: residentName(parent),
        submittedAt: parent.date || parent.createdAt,
        location: parent.location,
        description: parent.description || parent.title,
        attachmentUrl: parent.attachmentUrl || parent.imageUrl,
        isPrimary: true,
      }];
    }

    if (!window._residentNameCache) window._residentNameCache = new Map();
    for (const r of allReports) {
      if (r.reporterName && r.reporterName.trim().toLowerCase() !== "resident") {
        if (r.reporterId) window._residentNameCache.set(r.reporterId, r.reporterName.trim());
      }
    }

    const countEl = byId(`residentReportsCount_${parentId}`);
    if (countEl) countEl.textContent = formatNumber(allReports.length);

    if (!window._concernReportsMemory) window._concernReportsMemory = new Map();
    window._concernReportsMemory.set(parentId, allReports);

    container.innerHTML = `
      <table class="resident-reports-table">
        <thead>
          <tr>
            <th style="width: 44px; text-align: center;">#</th>
            <th style="width: 130px;">Reference</th>
            <th>Resident</th>
            <th style="width: 120px; text-align: right;">Action</th>
          </tr>
        </thead>
        <tbody>
          ${allReports.map((report, idx) => {
            const reportRef = `CON-${String(idx + 1).padStart(3, '0')}`;
            let name = report.reporterName;
            if (!name || name.trim().toLowerCase() === "resident") {
              if (report.reporterId && window._residentNameCache.has(report.reporterId)) {
                name = window._residentNameCache.get(report.reporterId);
              } else {
                name = residentName(parent);
              }
            }
            if (!name || name.trim().toLowerCase() === "resident") {
              name = `Resident #${idx + 1}`;
            }

            return `
              <tr>
                <td style="text-align: center; color: light-dark(#64748b, var(--textSecondary)); font-weight: 600;">${idx + 1}</td>
                <td><span class="concern-ref-badge">${escapeHtml(reportRef)}</span></td>
                <td style="font-weight: 600; color: light-dark(#0f172a, var(--textPrimary));">${escapeHtml(name)}</td>
                <td style="text-align: right;">
                  <button type="button" class="btn-view-official-report" onclick="openIndividualOfficialReport('${safeId(parentId)}', ${idx})">
                    <span class="material-symbols-rounded">description</span>
                    <span>View</span>
                  </button>
                </td>
              </tr>
            `;
          }).join("")}
        </tbody>
      </table>
    `;
  } catch (err) {
    console.error("Failed to load resident reports", err);
    container.innerHTML = `<p class="concern-report-empty" style="padding: 16px;">Could not load individual resident reports: ${escapeHtml(callableErrorMessage(err))}</p>`;
  }
};

window.openIndividualOfficialReport = (parentId, reportIndex) => {
  const parent = findCase(parentId);
  if (!parent) return;
  const isComplaint = isComplaintCase(parent) || String(parent.kind || "").toLowerCase() === "complaint" || !!parent.complaint;
  const reportsList = window._concernReportsMemory?.get(parentId) || [];
  const compDetails = isComplaint ? complaintDetails(parent) : {};
  const respondent = isComplaint ? complaintRespondent(parent) : "";
  const report = reportsList[reportIndex] || {
    reporterName: residentName(parent),
    submittedAt: parent.date || parent.createdAt,
    location: (compDetails.respondentAddress || parent.location || ""),
    description: (compDetails.narration || compDetails.details || parent.description || parent.title || ""),
    attachmentUrl: parent.attachmentUrl || parent.imageUrl,
  };

  let name = report.reporterName;
  if (!name || name.trim().toLowerCase() === "resident") {
    if (report.reporterId && window._residentNameCache?.has(report.reporterId)) {
      name = window._residentNameCache.get(report.reporterId);
    } else {
      name = residentName(parent);
    }
  }
  if (!name || name.trim().toLowerCase() === "resident") {
    name = isComplaint ? "Complainant" : "Resident";
  }

  const category = (isComplaint ? (compDetails.complaintType || parent.type || parent.category) : parent.category) || (isComplaint ? "General Dispute" : "General Concern");
  const barangay = (isComplaint ? (parent.barangay || compDetails.barangay) : concernBarangay(parent)) || "Barili";
  const dateVal = report.submittedAt || parent.date || parent.createdAt;
  const dateLongStr = dateVal ? new Date(dateValue(dateVal)).toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" }) : "Recent";
  const status = isComplaint ? complaintStage(parent) : concernStatus(parent);
  const refNo = isComplaint
    ? (parent.id || `CMP-${parentId.replace(/[^a-zA-Z0-9]/g, "").slice(-6).toUpperCase()}`)
    : `CON-${parent.id.replace(/[^a-zA-Z0-9]/g, "").slice(-6).toUpperCase()}-${String(reportIndex + 1).padStart(2, "0")}`;
  const title = isComplaint
    ? (compDetails.complaintType || parent.title || parent.type || "Barangay Dispute Complaint")
    : (report.title || parent.title || category);
  const description = report.description || compDetails.narration || compDetails.details || parent.description || "No description provided.";
  const location = report.location || compDetails.respondentAddress || parent.location || "";
  const attachmentUrl = report.attachmentUrl || parent.attachmentUrl || "";
  const barangayLogo = barangayLogoForCase(parent);

  const reportData = {
    parentId,
    reportIndex,
    isComplaint,
    refNo,
    residentName: name,
    respondent,
    barangay,
    barangayLogo,
    category,
    dateSubmitted: dateLongStr,
    status,
    title,
    description,
    location,
    attachmentUrl,
  };

  window._activeIndividualReport = reportData;

  const contentEl = byId("officialReportModalContent");
  if (!contentEl) return;

  const modalTitleEl = byId("officialReportModalTitle");
  if (modalTitleEl) {
    modalTitleEl.textContent = isComplaint ? "Official Resident Complaint Report" : "Official Resident Concern Report";
  }

  contentEl.innerHTML = `
    <article id="individualOfficialRecord" class="concern-document-sheet-container" style="max-width: 100%; width: 100%;">
      <section class="doc-sheet-paper" style="box-shadow: 0 4px 20px rgba(0,0,0,0.06); margin: 0 auto; width: 100%; max-width: 820px; background: light-dark(#fff, var(--surface)); padding: 36px 42px; border-radius: 12px; position: relative;">
        <!-- Watermark -->
        <div class="doc-sheet-watermark" aria-hidden="true">
          <img src="assets/barili-logoo.png" alt="" class="doc-sheet-watermark-img" onerror="this.src='assets/barili-logo.png'">
        </div>

        <!-- Top Letterhead -->
        <header class="doc-sheet-letterhead">
          <div class="doc-sheet-seal-left">
            <img src="assets/barili-logoo.png" alt="Municipality of Barili Official Seal" class="doc-seal-img" onerror="this.src='assets/esugid-logo.png'">
          </div>

          <div class="doc-sheet-titles-center">
            <span class="doc-country-label">Republic of the Philippines</span>
            <h1 class="doc-lgu-title">MUNICIPALITY OF BARILI</h1>
            <span class="doc-province-label">Province of Cebu</span>
            <span class="doc-official-motto">Limpyo nga Barili para sa tanan.</span>
          </div>

          <div class="doc-sheet-seal-right">
            <img src="${escapeAttribute(barangayLogo || "assets/bagong-pilipinas.png")}" alt="${barangayLogo ? `Barangay ${escapeAttribute(barangay)} seal` : "Bagong Pilipinas Seal"}" class="doc-national-img" onerror="this.onerror=null;this.src='${MUNICIPALITY_SEAL}'">
          </div>
        </header>

        <!-- Solid Dark Green Rule -->
        <div class="doc-sheet-green-rule"></div>

        <!-- Report Heading & Reference Number -->
        <div class="doc-sheet-report-lead">
          <h2 class="doc-sheet-report-title">${isComplaint ? "OFFICIAL RESIDENT COMPLAINT REPORT" : "RESIDENT CONCERN REPORT"}</h2>
          <div class="doc-sheet-ref-line">REF: <strong>${escapeHtml(refNo)}</strong></div>
        </div>

        <!-- Aligned Metadata Definition List -->
        <div class="doc-sheet-meta-list">
          <div class="doc-meta-item">
            <span class="doc-meta-key">${isComplaint ? "Complainant" : "Resident Name"}</span>
            <span class="doc-meta-colon">:</span>
            <strong class="doc-meta-val" style="color: light-dark(#0d3827, var(--textPrimary)); font-size: 15px;">${escapeHtml(name)}</strong>
          </div>
          ${respondent ? `
          <div class="doc-meta-item">
            <span class="doc-meta-key">Respondent</span>
            <span class="doc-meta-colon">:</span>
            <strong class="doc-meta-val" style="color: light-dark(#7f1d1d, var(--error)); font-size: 15px;">${escapeHtml(respondent)}</strong>
          </div>` : ""}
          <div class="doc-meta-item">
            <span class="doc-meta-key">Barangay</span>
            <span class="doc-meta-colon">:</span>
            <strong class="doc-meta-val">${escapeHtml(barangay)}</strong>
          </div>
          <div class="doc-meta-item">
            <span class="doc-meta-key">${isComplaint ? "Complaint" : "Concern Category"}</span>
            <span class="doc-meta-colon">:</span>
            <span class="doc-meta-val">${escapeHtml(category)}</span>
          </div>
          <div class="doc-meta-item">
            <span class="doc-meta-key">${isComplaint ? "Date Filed" : "Date Submitted"}</span>
            <span class="doc-meta-colon">:</span>
            <span class="doc-meta-val">${escapeHtml(dateLongStr)}</span>
          </div>
          <div class="doc-meta-item">
            <span class="doc-meta-key">Status</span>
            <span class="doc-meta-colon">:</span>
            <span class="doc-meta-val">${isComplaint ? complaintStagePill(status, parent) : statusPill(status)}</span>
          </div>
        </div>

        <!-- System-arranged Subject and Narrative -->
        <div class="doc-sheet-arranged-content">
          <div class="doc-sheet-thin-rule"></div>
          <h3 class="doc-sheet-arranged-headline">${escapeHtml(title)}</h3>
          <div class="doc-sheet-thin-rule subtle"></div>
          <div class="doc-sheet-arranged-body">${escapeHtml(description).replace(/\n/g, "<br>")}</div>
        </div>

        <!-- Location if present -->
        ${location ? `
        <div class="doc-sheet-location-callout" style="margin-top: 18px;">
          <span class="material-symbols-rounded">location_on</span>
          <div>
            <span><strong>Location:</strong> ${escapeHtml(location)}, Barangay ${escapeHtml(barangay)}</span>
          </div>
        </div>` : ""}

        <!-- Supporting Evidence Photos -->
        ${attachmentUrl ? `
        <div class="doc-sheet-evidence-section" style="margin-top: 20px;">
          <h4 class="doc-sheet-section-title">Supporting Evidence</h4>
          <div class="doc-sheet-evidence-gallery">
            <figure class="doc-sheet-photo-card">
              <a href="${escapeAttribute(attachmentUrl)}" target="_blank" rel="noopener noreferrer" class="doc-photo-thumb-btn">
                <img src="${escapeAttribute(attachmentUrl)}" alt="Submitted evidence photo" loading="lazy">
                <span class="doc-photo-zoom-overlay"><span class="material-symbols-rounded">zoom_in</span>View</span>
              </a>
              <figcaption class="doc-photo-name">evidence_photo.jpg</figcaption>
            </figure>
          </div>
        </div>` : ""}

        <!-- Official Document Footer -->
        <footer class="doc-sheet-official-footer" style="margin-top: 32px;">
          <div class="doc-sheet-footer-line"></div>
          <div class="doc-sheet-footer-content">
            <div class="doc-footer-left">
              <span class="material-symbols-rounded doc-footer-verify-icon">verified</span>
              <div class="doc-footer-legal-copy">
                <strong>Municipality of Barili &bull; E-SUGID Platform</strong>
                <span>${isComplaint ? "Official Electronic Resident Complaint Record" : "Official Electronic Resident Concern Record"} &bull; Province of Cebu</span>
                <span class="doc-footer-timestamp">System Record Verified on ${escapeHtml(new Date().toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" }))}</span>
              </div>
            </div>
            <div class="doc-footer-right">
              <span class="doc-footer-barcode-art" aria-hidden="true">||| | || |||| | ||| | ||</span>
              <span class="doc-footer-tracking">${escapeHtml(refNo)}</span>
              <small class="doc-footer-certified">Certified Digital Copy</small>
            </div>
          </div>
        </footer>
      </section>
    </article>
  `;

  const downloadBtn = byId("officialReportDownloadPdfBtn");
  if (downloadBtn) {
    downloadBtn.onclick = () => downloadIndividualOfficialPdf(reportData);
  }
  const downloadBtnBottom = byId("officialReportDownloadPdfBtnBottom");
  if (downloadBtnBottom) {
    downloadBtnBottom.onclick = () => downloadIndividualOfficialPdf(reportData);
  }
  const printBtn = byId("officialReportPrintBtn");
  if (printBtn) {
    printBtn.onclick = () => printIndividualOfficialReport();
  }
  const printBtnBottom = byId("officialReportPrintBtnBottom");
  if (printBtnBottom) {
    printBtnBottom.onclick = () => printIndividualOfficialReport();
  }
  const closeBtnBottom = byId("officialReportCloseBtnBottom");
  if (closeBtnBottom) {
    closeBtnBottom.onclick = () => closeOfficialReportModal();
  }

  const overlay = byId("officialReportModalOverlay");
  if (overlay) {
    overlay.hidden = false;
    overlay.style.display = "flex";
    document.body.style.overflow = "hidden";
  }
};

window.openSingleOfficialReport = (id) => {
  openIndividualOfficialReport(id, 0);
};

window.closeOfficialReportModal = () => {
  const overlay = byId("officialReportModalOverlay");
  if (overlay) {
    overlay.hidden = true;
    overlay.style.display = "none";
  }
  document.body.style.overflow = "";
};

window.downloadIndividualOfficialPdf = async (data) => {
  const button = byId("officialReportDownloadPdfBtn");
  const buttonBottom = byId("officialReportDownloadPdfBtnBottom");
  if (button) setButtonBusy(button, true, "Preparing PDF...");
  if (buttonBottom) setButtonBusy(buttonBottom, true, "Preparing PDF...");
  try {
    const pdf = new jsPDF({ unit: "mm", format: "a4", orientation: "portrait" });
    const green = [7, 92, 68];
    const muted = [91, 111, 103];
    const pageWidth = pdf.internal.pageSize.getWidth();
    const margin = 18;
    let y = 18;
    const [seal, receivingLogo] = await Promise.all([
      imageToPngDataUrl(MUNICIPALITY_SEAL).catch(() => null),
      imageToPngDataUrl(data.barangayLogo || "assets/bagong-pilipinas.png")
        .catch(() => imageToPngDataUrl(MUNICIPALITY_SEAL).catch(() => null))
    ]);
    if (seal) pdf.addImage(seal, "PNG", margin, y, 22, 22);
    if (receivingLogo) pdf.addImage(receivingLogo, "PNG", pageWidth - margin - 22, y, 22, 22);
    pdf.setTextColor(...muted); pdf.setFont("helvetica", "bold"); pdf.setFontSize(9);
    pdf.text("REPUBLIC OF THE PHILIPPINES", pageWidth / 2, y + 2, { align: "center" });
    pdf.setTextColor(...green); pdf.setFontSize(15); pdf.text("MUNICIPALITY OF BARILI", pageWidth / 2, y + 9, { align: "center" });
    pdf.setTextColor(...muted); pdf.setFontSize(9); pdf.text("PROVINCE OF CEBU", pageWidth / 2, y + 15, { align: "center" });
    pdf.setTextColor(...green); pdf.setFontSize(11); pdf.text(data.isComplaint ? "OFFICIAL RESIDENT COMPLAINT REPORT" : "RESIDENT CONCERN REPORT", pageWidth / 2, y + 22, { align: "center" });
    y += 31; pdf.setDrawColor(...green); pdf.setLineWidth(0.8); pdf.line(margin, y, pageWidth - margin, y); y += 10;

    const ensureSpace = (height) => { if (y + height > 278) { pdf.addPage(); y = 18; } };
    const drawField = (label, value, x, width, minHeight = 18) => {
      const lines = pdf.splitTextToSize(String(value || "Not provided"), width - 8);
      const height = Math.max(minHeight, 12 + lines.length * 5);
      ensureSpace(height + 4);
      pdf.setFillColor(248, 251, 249); pdf.setDrawColor(210, 225, 218); pdf.roundedRect(x, y, width, height, 2.5, 2.5, "FD");
      pdf.setTextColor(...muted); pdf.setFont("helvetica", "bold"); pdf.setFontSize(8); pdf.text(label.toUpperCase(), x + 4, y + 5.5);
      pdf.setTextColor(15, 43, 34); pdf.setFont("helvetica", "normal"); pdf.setFontSize(10.5); pdf.text(lines, x + 4, y + 11);
      return height;
    };
    const columnWidth = (pageWidth - (margin * 2) - 5) / 2;
    let height = Math.max(
      drawField(data.isComplaint ? "Complainant" : "Resident Name", data.residentName, margin, columnWidth),
      drawField(data.isComplaint ? "Date Filed" : "Date Submitted", data.dateSubmitted, margin + columnWidth + 5, columnWidth)
    );
    y += height + 5;
    if (data.isComplaint && data.respondent) {
      height = Math.max(
        drawField("Respondent", data.respondent, margin, columnWidth),
        drawField("Barangay", data.barangay, margin + columnWidth + 5, columnWidth)
      );
      y += height + 5;
      height = Math.max(
        drawField("Complaint", data.category, margin, columnWidth),
        drawField("Case / Ref Number", data.refNo, margin + columnWidth + 5, columnWidth)
      );
      y += height + 5;
    } else {
      height = Math.max(
        drawField("Barangay", data.barangay, margin, columnWidth),
        drawField("Reference Number", data.refNo, margin + columnWidth + 5, columnWidth)
      );
      y += height + 5;
      height = Math.max(
        drawField(data.isComplaint ? "Complaint" : "Concern Category", data.category, margin, columnWidth),
        drawField("Status", statusLabel(data.status), margin + columnWidth + 5, columnWidth)
      );
      y += height + 5;
    }
    if (data.location) {
      y += drawField("Location", data.location, margin, pageWidth - margin * 2) + 5;
    }
    y += drawField(data.isComplaint ? "Dispute Type" : "Statement of Concern", data.title, margin, pageWidth - margin * 2) + 5;
    y += drawField("Narrative / Description", data.description, margin, pageWidth - margin * 2, 30) + 7;

    ensureSpace(22);
    pdf.setFillColor(235, 247, 241); pdf.setDrawColor(188, 218, 205); pdf.roundedRect(margin, y, pageWidth - margin * 2, 20, 2.5, 2.5, "FD");
    pdf.setTextColor(...green); pdf.setFont("helvetica", "bold"); pdf.setFontSize(9); pdf.text(data.isComplaint ? "OFFICIAL E-SUGID COMPLAINT RECORD" : "OFFICIAL E-SUGID RECORD", margin + 5, y + 6);
    pdf.setTextColor(...muted); pdf.setFont("helvetica", "normal"); pdf.setFontSize(8.5);
    pdf.text(pdf.splitTextToSize(`This official ${data.isComplaint ? "complaint" : "concern"} record was submitted through the E-SUGID citizen portal of the Municipality of Barili, Province of Cebu. Use the reference number above for official tracking.`, pageWidth - margin * 2 - 10), margin + 5, y + 11);

    pdf.save(`${data.isComplaint ? "Official-Complaint-Report-" : "Official-Report-"}${String(data.refNo).replace(/[^a-z0-9-]/gi, "-")}.pdf`);
    showToast(`PDF for ${data.refNo} downloaded.`);
  } catch (err) {
    console.error("PDF generation error", err);
    showToast(`PDF could not be created: ${callableErrorMessage(err)}`, true);
  } finally {
    if (button) setButtonBusy(button, false);
    if (buttonBottom) setButtonBusy(buttonBottom, false);
  }
};

window.printIndividualOfficialReport = () => {
  document.body.classList.add("printing-individual-report");
  window.print();
  window.setTimeout(() => {
    document.body.classList.remove("printing-individual-report");
  }, 350);
};

document.addEventListener("click", (event) => {
  if (!event.target.closest(".grouped-card-action-wrap")) {
    document.querySelectorAll(".grouped-action-menu").forEach((m) => { m.hidden = true; });
  }
});

function renderConcerns() {
  // Shared case actions call this after saving; on the Complaints page the
  // complaint board is what needs refreshing.
  if (state.page === "complaints") {
    renderComplaints();
    return;
  }
  const target = byId("concernDocumentGrid");
  if (!target) return;
  updateConcernFilterIndicator();
  const reportView = usesConcernReportTable();
  const organizationView = canonicalRole(state.currentProfile?.role) === "organization";
  const isOversightRole = isLguAdmin() || canonicalRole(state.currentProfile?.role) === "mayor";
  const browserTitle = byId("concernBrowser")?.querySelector(".concern-browser-title");
  if (browserTitle) browserTitle.textContent = isOversightRole ? "Barangay Concern Records" : (organizationView ? "Assigned Concerns" : "Resident Reports");
  const newTab = byId("concernStatusTabs")?.querySelector('[data-status="new"]');
  const resolvedTab = byId("concernStatusTabs")?.querySelector('[data-status="resolved"]');
  if (newTab?.childNodes[1]) newTab.childNodes[1].textContent = "Active ";
  if (resolvedTab?.childNodes[1]) resolvedTab.childNodes[1].textContent = "Resolved ";
  const allTab = byId("concernStatusTabs")?.querySelector('[data-status="all"]');
  if (allTab) allTab.hidden = reportView;
  if (byId("concernReportPeriod")) byId("concernReportPeriod").hidden = !reportView;
  byId("page-concerns").classList.toggle("concern-table-report", reportView);
  if (reportView && state.concernStatus === "all" && !state.concernReportCategory) state.concernStatus = "new";
  document.querySelectorAll("#concernStatusTabs button").forEach((button) => button.classList.toggle("active", button.dataset.status === state.concernStatus));
  closeConcernActions();
  populateConcernReportYears();
  const statuses = (reportView ? state.concerns.filter(matchesConcernReportPeriod) : state.concerns).map(concernStatus);
  const updateConcernTabBadge = (id, count) => {
    const el = byId(id);
    if (!el) return;
    el.textContent = formatNumber(count);
    const isZero = count === 0;
    el.hidden = isZero;
    el.classList.toggle("is-zero", isZero);
    el.style.display = isZero ? "none" : "";
  };
  updateConcernTabBadge("concernAllCount", state.concerns.length);
  updateConcernTabBadge("concernNewCount", statuses.filter((status) => status === "new").length);
  updateConcernTabBadge("concernBeingHandledCount", statuses.filter((status) => status === "being_handled").length);
  updateConcernTabBadge("concernNeedsInfoCount", statuses.filter((status) => status === "needs_information").length);
  updateConcernTabBadge("concernResolvedCount", statuses.filter((status) => status === "resolved").length);
  const isCategoryDetail = reportView && Boolean(state.concernReportCategory);
  byId("page-concerns")?.classList.toggle("concern-category-detail-view", isCategoryDetail);
  if (byId("concernStatusTabs")) {
    byId("concernStatusTabs").hidden = isCategoryDetail;
  }
  const browserHeader = byId("concernBrowser")?.querySelector(".concern-browser-header");
  if (browserHeader) {
    browserHeader.hidden = isCategoryDetail;
  }

  if (reportView) {
    renderConcernReport(target);
    byId("concernPagination").innerHTML = "";
    return;
  }
  const filtered = getFilteredConcerns();
  const totalPages = Math.max(1, Math.ceil(filtered.length / state.concernPageSize));
  state.concernPage = Math.min(state.concernPage, totalPages);
  const start = (state.concernPage - 1) * state.concernPageSize;
  const visible = filtered.slice(start, start + state.concernPageSize);
  target.innerHTML = visible.length
    ? visible.map(concernDocumentCardMarkup).join("")
    : '<div class="concern-browser-empty"><span class="material-symbols-rounded">find_in_page</span><strong>No concerns match these filters.</strong><small>Try another status or filter.</small></div>';
  renderPagination(totalPages);
  if (!visible.length) {
    state.selectedConcernId = null;
    renderConcernDetailEmpty();
    return;
  }
  const page = byId("page-concerns");
  const selected = visible.find((item) => item.id === state.selectedConcernId);
  if (page?.classList.contains("show-detail") && selected) {
    openConcern(selected.id, { preserveBrowserPosition: true });
  } else {
    page?.classList.remove("show-detail");
    state.selectedConcernId = null;
    renderConcernDetailEmpty();
  }
}

window.handleConcernRowKey = (event, id) => {
  if (event.target.closest("button")) return;
  if (event.key === "Enter" || event.key === " ") {
    event.preventDefault();
    openConcern(id);
  }
};

let activeConcernActionMenu = null;

function closeConcernActions(restoreFocus = false) {
  if (!activeConcernActionMenu) return;
  const { menu, button } = activeConcernActionMenu;
  menu.remove();
  button.setAttribute("aria-expanded", "false");
  activeConcernActionMenu = null;
  if (restoreFocus) button.focus();
}

window.openConcernActions = (button, id) => {
  if (activeConcernActionMenu?.button === button) {
    closeConcernActions(true);
    return;
  }
  closeConcernActions();
  const item = findCase(id);
  if (!item) return;
  const menu = document.createElement("div");
  menu.className = "concern-action-menu";
  menu.setAttribute("role", "menu");
  menu.setAttribute("aria-label", `Actions for ${item.id}`);
  const isReadOnlyOversight = isLguAdmin() || canonicalRole(state.currentProfile?.role) === "mayor";
  menu.innerHTML = `
    <button type="button" role="menuitem" onclick="runConcernAction('${isReadOnlyOversight ? "view" : "review"}','${safeId(item.id)}')"><span class="material-symbols-rounded">${isReadOnlyOversight ? "visibility" : "rate_review"}</span><span><strong>${isReadOnlyOversight ? "View Record" : "Review Case"}</strong><small>${isReadOnlyOversight ? "Open the read-only case file" : "Open case workspace"}</small></span></button>
    <button type="button" role="menuitem" onclick="runConcernAction('pdf','${safeId(item.id)}')"><span class="material-symbols-rounded">picture_as_pdf</span><span><strong>Download PDF</strong><small>Save official record</small></span></button>`;
  document.body.appendChild(menu);
  const rect = button.getBoundingClientRect();
  const menuWidth = 290;
  const left = Math.max(12, Math.min(window.innerWidth - menuWidth - 12, rect.right - menuWidth));
  const estimatedHeight = 220;
  const opensUp = rect.bottom + estimatedHeight > window.innerHeight - 12;
  menu.style.left = `${left}px`;
  menu.style.top = `${opensUp ? Math.max(12, rect.top - estimatedHeight - 6) : rect.bottom + 6}px`;
  button.setAttribute("aria-expanded", "true");
  activeConcernActionMenu = { menu, button };
  menu.querySelector("button")?.focus();
};

window.runConcernAction = (action, id) => {
  closeConcernActions();
  if (action === "review" || action === "view") openConcern(id);
  if (action === "timeline") openConcern(id);
  if (action === "pdf") downloadConcernPdf(id);
};

document.addEventListener("click", (event) => {
  if (activeConcernActionMenu && !activeConcernActionMenu.menu.contains(event.target) && event.target !== activeConcernActionMenu.button) closeConcernActions();
});
window.addEventListener("resize", () => closeConcernActions());
window.addEventListener("scroll", () => closeConcernActions(), true);
document.addEventListener("keydown", (event) => {
  if (event.key === "Escape" && activeConcernActionMenu) {
    event.stopPropagation();
    closeConcernActions(true);
  }
});

function populateConcernFilters() {
  populateConcernReportYears();
  const isBarangay = isBarangayRole(state.currentProfile?.role);
  const barangays = unique(state.concerns.map(concernBarangay).filter(Boolean));
  const concernTypes = unique(state.concerns.map((item) => item.category || item.title || "General concern").filter(Boolean));
  populateSelect(byId("concernBarangayFilter"), barangays, "All barangays", true);
  const barangayFilterField = byId("concernBarangayFilter")?.closest(".concern-filter-field");
  if (barangayFilterField) {
    barangayFilterField.hidden = isBarangay;
    barangayFilterField.style.display = isBarangay ? "none" : "";
  }
  if (isBarangay && byId("concernBarangayFilter")) byId("concernBarangayFilter").value = "all";
  populateSelect(byId("concernTypeFilter"), concernTypes, "All concern types", true);
  renderConcerns();
}

function renderConcernLoadError(error) {
  const target = byId("concernDocumentGrid");
  if (target) target.innerHTML = `<div class="concern-browser-empty error"><span class="material-symbols-rounded">error</span><strong>Concern records could not be loaded.</strong><small>${escapeHtml(callableErrorMessage(error))}</small></div>`;
  const detail = byId("concernDetailPane");
  if (detail) detail.innerHTML = '<div class="concern-detail-empty"><span class="material-symbols-rounded">cloud_off</span><h2>Records unavailable</h2><p>Please check the connection and try again.</p></div>';
}

document.querySelectorAll("#concernStatusTabs button").forEach((button) => button.addEventListener("click", () => {
  state.concernStatus = button.dataset.status;
  state.concernReportCategory = null;
  state.concernPage = 1;
  document.querySelectorAll("#concernStatusTabs button").forEach((item) => item.classList.toggle("active", item === button));
  renderConcerns();
}));
["concernReportYear", "concernReportMonth", "concernBarangayFilter", "concernTypeFilter"].forEach((id) => {
  byId(id)?.addEventListener("change", () => {
    state.concernReportCategory = null;
    state.concernPage = 1;
    updateConcernFilterIndicator();
    renderConcerns();
  });
});

function setConcernFilterPopoverOpen(open, restoreFocus = false) {
  const isBarangay = isBarangayRole(state.currentProfile?.role);
  const barangayFilterField = byId("concernBarangayFilter")?.closest(".concern-filter-field");
  if (barangayFilterField) {
    barangayFilterField.hidden = isBarangay;
    barangayFilterField.style.display = isBarangay ? "none" : "";
  }
  if (isBarangay && byId("concernBarangayFilter")) {
    byId("concernBarangayFilter").value = "all";
  }
  byId("concernFilterPopover").hidden = !open;
  byId("concernFilterToggle").setAttribute("aria-expanded", String(open));
  if (restoreFocus) byId("concernFilterToggle").focus();
}

byId("concernFilterToggle").addEventListener("click", () => {
  setConcernFilterPopoverOpen(byId("concernFilterPopover").hidden);
});

byId("concernFilterClear").addEventListener("click", () => {
  const currentYear = String(new Date().getFullYear());
  if (byId("concernReportYear")) byId("concernReportYear").value = currentYear;
  if (byId("concernReportMonth")) byId("concernReportMonth").value = "all";
  if (byId("concernBarangayFilter")) byId("concernBarangayFilter").value = "all";
  if (byId("concernTypeFilter")) byId("concernTypeFilter").value = "all";
  state.concernReportCategory = null;
  state.concernPage = 1;
  updateConcernFilterIndicator();
  renderConcerns();
});
document.addEventListener("click", (event) => {
  if (!byId("concernFilterPopover").hidden && !event.target.closest(".concern-filter-anchor")) setConcernFilterPopoverOpen(false);
});
document.addEventListener("keydown", (event) => {
  if (event.key === "Escape" && !byId("concernFilterPopover").hidden) {
    event.stopPropagation();
    setConcernFilterPopoverOpen(false, true);
  }
});

function renderPagination(totalPages) {
  const target = byId("concernPagination");
  if (totalPages <= 1) { target.innerHTML = ""; return; }
  target.innerHTML = Array.from({ length: totalPages }, (_, index) => `<button class="${state.concernPage === index + 1 ? "active" : ""}" type="button" onclick="setConcernPage(${index + 1})">${index + 1}</button>`).join("");
}
window.setConcernPage = (page) => { state.concernPage = page; renderConcerns(); };

function concernEvidenceUrls(item) {
  const candidates = [
    item.attachmentUrl,
    item.imageUrl,
    item.photoUrl,
    ...(Array.isArray(item.attachmentUrls) ? item.attachmentUrls : []),
    ...(Array.isArray(item.imageUrls) ? item.imageUrls : []),
    ...(Array.isArray(item.photos) ? item.photos.map((photo) => typeof photo === "string" ? photo : photo?.url || photo?.downloadUrl) : []),
    ...(Array.isArray(item.residentResponses) ? item.residentResponses.map((response) => response?.attachmentUrl) : [])
  ];
  return unique(candidates.map(trustedMediaUrl).filter(Boolean));
}

function concernResidentResponsesMarkup(item) {
  const responses = Array.isArray(item.residentResponses) ? item.residentResponses : [];
  if (!responses.length) return "";
  return `<section class="concern-full-description"><h4>Additional Information from Resident</h4>${responses.map((response) => `<p>${escapeHtml(response.message || "Additional evidence was provided.").replace(/\n/g, "<br>")}<br><small>${escapeHtml(formatDate(response.date))}</small></p>`).join("")}</section>`;
}

function currentOfficialName() {
  return state.currentProfile?.name
    || state.currentProfile?.fullName
    || state.currentProfile?.displayName
    || state.currentProfile?.positionTitle
    || (state.currentProfile?.role ? labelForRole(state.currentProfile.role) : "")
    || auth.currentUser?.displayName
    || auth.currentUser?.email?.split("@")[0]
    || "Barangay Official";
}

function currentOfficialId() {
  return auth.currentUser?.uid || state.currentProfile?.id || "admin";
}

function caseCurrentActionMarkup(item) {
  const status = concernStatus(item);
  const isOversight = isLguAdmin() || canonicalRole(state.currentProfile?.role) === "mayor";
  if (isOversight) {
    const barangayName = concernBarangay(item) || item.barangay || item.barangayName || "the responsible barangay";
    return `
      <div class="action-card action-card--oversight action-card--admin-oversight">
        <div class="action-card__info">
          <span class="material-symbols-rounded">admin_panel_settings</span>
          <div>
            <strong>Barangay ${escapeHtml(barangayName)} Jurisdiction · View-Only Record</strong>
            <p>This resident concern is currently <strong>${escapeHtml(statusLabel(status).toLowerCase())}</strong>. Direct actions, status updates, and summons are handled exclusively by <strong>Barangay ${escapeHtml(barangayName)}</strong> officials.</p>
            <p class="oversight-subtext">Municipal administration retains read-only access for municipal record-keeping and oversight across Barili.</p>
          </div>
        </div>
      </div>`;
  }
  const organizationView = canonicalRole(state.currentProfile?.role) === "organization";
  const autoRouted = Number(item.schemaVersion || 0) >= 4;
  if (autoRouted && item.leadOrganizationId
      && ((organizationView && item.leadOrganizationId !== currentOrganizationId())
        || (canManageBarangay(state.currentProfile?.role) && !organizationView))) {
    return `<div class="action-card action-card--waiting"><div class="action-card__info"><span class="material-symbols-rounded">verified</span><div><strong>Being handled by the lead organization</strong><p>Status updates are managed by the lead handler.</p></div></div>${organizationView && item.moderationFlagStatus !== "pending_review" ? `<div class="action-card__buttons"><button class="button button--secondary" type="button" onclick="openFlagConcernModal('${safeId(item.id)}')"><span class="material-symbols-rounded" aria-hidden="true">flag</span>Flag Concern</button></div>` : ""}</div>`;
  }
  let actionBoxHtml = "";
  const statusButton = `<button class="button button--primary concern-status-trigger" type="button" onclick="openConcernStatusModal('${safeId(item.id)}')"><span class="material-symbols-rounded" aria-hidden="true">published_with_changes</span>Change Status</button>`;
  const flagButton = item.moderationFlagStatus === "pending_review"
    ? '<span class="status-pill status-pill--needs_information">Flagged for review</span>'
    : `<button class="button button--secondary" type="button" onclick="openFlagConcernModal('${safeId(item.id)}')"><span class="material-symbols-rounded" aria-hidden="true">flag</span>Flag Concern</button>`;

  if (status === "new") {
    const duplicateIds = Array.isArray(item.possibleDuplicateIds) ? item.possibleDuplicateIds : [];
    actionBoxHtml = `
      <div class="action-card action-card--new">
        <div class="action-card__info">
          <span class="material-symbols-rounded">notifications_active</span>
          <div>
            <strong>Update Concern Status</strong>
            <p>Choose the next status for this report.</p>
          </div>
        </div>
        ${duplicateIds.length ? `<button class="possible-duplicate" type="button" onclick="openConcern('${safeId(duplicateIds[0])}')"><span class="material-symbols-rounded">content_copy</span><span><strong>Possible Duplicate</strong><small>Open similar concern ${escapeHtml(duplicateIds[0])}</small></span></button>` : ""}
        <div class="concern-review-decisions">
          ${statusButton}
          ${flagButton}
        </div>
        ${autoRouted && organizationView && !item.leadOrganizationId ? "" : `<div class="concern-review-secondary">
          <button type="button" onclick="openConcernOutcomeModal('${safeId(item.id)}','duplicate')">Duplicate Report</button>
          <button type="button" onclick="openConcernOutcomeModal('${safeId(item.id)}','outside_scope')">Outside E-SUGID Scope</button>
        </div>`}
      </div>`;
  } else if (status === "being_handled") {
    const handler = item.handledByName || item.assignedToName || currentOfficialName();
    const handlingNote = item.handlingNote
      || [...(item.statusHistory || [])].reverse().find((e) => e.status === "being_handled" && e.action === "handle")?.note
      || "";
    const hasSummons = Boolean(item.summons);
    const summons = item.summons || {};

    actionBoxHtml = `
      <div class="action-card action-card--handling">
        <div class="action-card__info">
          <span class="material-symbols-rounded">construction</span>
          <div>
            <strong>In Progress</strong>
            <p>Handled by: <strong>${escapeHtml(handler)}</strong></p>
          </div>
        </div>

        ${handlingNote ? `
          <div class="handling-note-display">
            <div class="handling-note-label">
              <span class="material-symbols-rounded">chat</span>
              <span>Action Note sent to Resident:</span>
            </div>
            <p class="handling-note-text">${escapeHtml(handlingNote)}</p>
          </div>
        ` : ""}

        ${hasSummons ? `
          <div class="summons-status-callout">
            <div class="summons-callout-header">
              <span class="material-symbols-rounded">gavel</span>
              <div>
                <strong>Official Barangay Summons Issued</strong>
                <small>Hearing set for <strong>${escapeHtml(summons.appearanceDate || "")}</strong> at <strong>${escapeHtml(summons.appearanceTime || "")}</strong> (${escapeHtml(summons.appearanceVenue || "Barangay Hall")})</small>
              </div>
            </div>
            <div class="summons-callout-meta">
              <span>Respondent: <strong>${escapeHtml(summons.respondentName || "Resident")}</strong></span>
              <span>Delivery: <strong>Personal service via Tanod</strong></span>
            </div>
          </div>
        ` : ""}

        <div class="action-card__buttons">
          ${statusButton}
          ${hasSummons ? `
            <button class="button button--secondary" type="button" onclick="printBarangaySummons('${safeId(item.id)}')">
              <span class="material-symbols-rounded">print</span>Print Summons
            </button>
          ` : ""}
          <button class="button button--secondary" type="button" onclick="openHandleConcernModal('${safeId(item.id)}')">
            <span class="material-symbols-rounded">edit_note</span>Update Progress Note
          </button>
          ${flagButton}
        </div>
      </div>`;
  } else if (status === "needs_information") {
    const message = item.requestedInfoMessage
      || [...(item.statusHistory || [])].reverse().find((e) => e.status === "needs_information" || e.status === "awaiting_resident")?.note
      || "Please provide additional clarification or evidence.";
    actionBoxHtml = `
      <div class="action-card action-card--waiting">
        <div class="action-card__info">
          <span class="material-symbols-rounded">hourglass_top</span>
          <div>
            <strong>Awaiting Information</strong>
            <p>A request has been sent to the resident in their mobile app.</p>
          </div>
        </div>
        <div class="requested-message-box">
          <span class="message-label">Message sent to resident:</span>
          <p class="message-text">${escapeHtml(message)}</p>
        </div>
        <small class="waiting-footnote">A resident reply returns this concern to In Progress.</small>
        <div class="action-card__buttons">${statusButton}${flagButton}</div>
      </div>`;
  } else if (status === "resolved") {
    const resolver = item.resolvedByName || item.resolvedBy || item.handledByName || item.assignedToName || "Barangay Official";
    const resolvedDate = formatDate(item.resolvedAt || item.updatedAt || item.date);
    const summary = item.resolutionSummary || "The concern has been handled.";
    actionBoxHtml = `
      <div class="action-card action-card--resolved">
        <div class="resolved-header">
          <span class="material-symbols-rounded">check_circle</span>
          <strong>✓ Resolved</strong>
        </div>
        <div class="resolved-facts-list">
          <div class="fact-item">
            <span class="fact-label">Resolution:</span>
            <div class="fact-text">${escapeHtml(summary).replace(/\n/g, "<br>")}</div>
          </div>
          <div class="fact-item">
            <span class="fact-label">Resolved by:</span>
            <span class="fact-text"><strong>${escapeHtml(resolver)}</strong></span>
          </div>
          <div class="fact-item">
            <span class="fact-label">Date:</span>
            <span class="fact-text">${escapeHtml(resolvedDate)}</span>
          </div>
        </div>
      </div>`;
  }

  return actionBoxHtml;
}

function simpleActivityHistoryMarkup(item, entries) {
  const submittedDate = formatDate(item.date || item.createdAt);
  const submittedEntry = {
    date: item.date || item.createdAt,
    dateStr: submittedDate,
    text: `Concern submitted by ${residentName(item)}`
  };

  const rawHistory = Array.isArray(entries) && entries.length ? entries : (item.statusHistory || []);
  const formattedEntries = [];

  rawHistory.forEach((entry) => {
    const dateStr = formatDate(entry.date || entry.createdAt);
    const actor = entry.actorName || entry.actorEmail || (entry.actorType === "resident" ? residentName(item) : "Barangay Official");
    let text = "";

    const s = normalize(entry.status || "").replaceAll(" ", "_");
    if (entry.action === "submitted" || (["new", "submitted"].includes(s) && entry.actorType === "resident")) {
      return;
    } else if (s === "being_handled" || s === "in_progress") {
      text = entry.note || `Started handling by ${actor}`;
    } else if (s === "needs_information" || s === "awaiting_resident") {
      text = `Requested additional information: "${entry.note || "Details needed"}"`;
    } else if (entry.actorType === "resident" || (entry.userId && entry.userId === item.userId)) {
      text = `Resident provided information: "${entry.note || entry.message || "Additional details submitted"}"`;
    } else if (s === "resolved") {
      text = `Concern resolved: "${entry.note || item.resolutionSummary || "Action completed"}"`;
    } else if (entry.note) {
      text = entry.note;
    } else if (s) {
      text = `Status updated to ${statusLabel(s)}`;
    }

    if (text) {
      formattedEntries.push({ date: entry.date || entry.createdAt, dateStr, text });
    }
  });

  const list = [
    submittedEntry,
    ...formattedEntries
  ].sort((a, b) => dateValue(a.date) - dateValue(b.date));

  return `
    <ol class="simple-history-list">
      ${list.map((hist, idx) => `
        <li class="simple-history-item ${idx === list.length - 1 ? 'is-latest' : ''}">
          <span class="history-bullet"></span>
          <div class="history-content">
            <div class="history-meta-row">
              <span class="material-symbols-rounded history-clock-icon">schedule</span>
              <time class="history-date">${escapeHtml(hist.dateStr)}</time>
            </div>
            <p class="history-text">${escapeHtml(hist.text)}</p>
          </div>
        </li>
      `).join("")}
    </ol>`;
}

function officialDocumentSheetMarkup(item) {
  const status = concernStatus(item);
  const barangayLogo = barangayLogoForCase(item);
  const dateObj = parseDate(item.date || item.dateSubmitted || item.createdAt);
  const dateLongStr = dateObj.valueOf()
    ? new Intl.DateTimeFormat("en-PH", { dateStyle: "long" }).format(dateObj)
    : formatDate(item.date || item.createdAt);
  const category = item.category || "General Concern";
  const title = item.title || item.category || "Resident concern";
  const description = item.description || (item.title && item.title !== item.category ? item.title : "No detailed description provided.");
  const evidence = concernEvidenceUrls(item);
  const latitude = Number(item.latitude ?? item.lat ?? item.coordinates?.latitude ?? item.locationData?.latitude);
  const longitude = Number(item.longitude ?? item.lng ?? item.coordinates?.longitude ?? item.locationData?.longitude);
  const hasCoordinates = Number.isFinite(latitude) && Number.isFinite(longitude);
  const now = new Date();
  const printDateStr = new Intl.DateTimeFormat("en-PH", { dateStyle: "medium", timeStyle: "short" }).format(now);
  const reporterCount = Number(item.reporterCount || (item.reporterIds ? item.reporterIds.length : 1));
  const isGrouped = reporterCount > 1;
  const firstReportedDate = dateLongStr;
  const latestReportedDate = formatDate(item.latestReportAt || item.date || item.createdAt);

  return `
    <section class="doc-sheet-paper">
      <!-- Faint Centered Municipal Seal Watermark -->
      <div class="doc-sheet-watermark" aria-hidden="true">
        <img src="assets/barili-logoo.png" alt="" class="doc-sheet-watermark-img" onerror="this.src='assets/barili-logo.png'">
      </div>

      <!-- Top Letterhead -->
      <header class="doc-sheet-letterhead">
        <div class="doc-sheet-seal-left">
          <img src="assets/barili-logoo.png" alt="Municipality of Barili Official Seal" class="doc-seal-img" onerror="this.src='assets/esugid-logo.png'">
        </div>

        <div class="doc-sheet-titles-center">
          <span class="doc-country-label">Republic of the Philippines</span>
          <h1 class="doc-lgu-title">MUNICIPALITY OF BARILI</h1>
          <span class="doc-province-label">Province of Cebu</span>
          <span class="doc-official-motto">Limpyo nga Barili para sa tanan.</span>
        </div>

        <div class="doc-sheet-seal-right">
          <img src="${escapeAttribute(barangayLogo || "assets/bagong-pilipinas.png")}" alt="${barangayLogo ? "Receiving barangay seal" : "Bagong Pilipinas Seal"}" class="doc-national-img" onerror="this.onerror=null;this.src='${MUNICIPALITY_SEAL}'">
        </div>
      </header>

      <!-- Solid Dark Green Rule -->
      <div class="doc-sheet-green-rule"></div>

      <!-- Report Heading & Reference Number -->
      <div class="doc-sheet-report-lead">
        <h2 class="doc-sheet-report-title">${isGrouped ? "GROUPED RESIDENT CONCERN RECORD" : "RESIDENT CONCERN REPORT"}</h2>
        <div class="doc-sheet-ref-line">REF: <strong>${escapeHtml(item.id)}</strong></div>
      </div>

      <!-- Aligned Metadata Definition List -->
      <div class="doc-sheet-meta-list">
        ${isGrouped ? `
        <div class="doc-meta-item">
          <span class="doc-meta-key">Category</span>
          <span class="doc-meta-colon">:</span>
          <strong class="doc-meta-val">${escapeHtml(category)}</strong>
        </div>
        <div class="doc-meta-item">
          <span class="doc-meta-key">Location</span>
          <span class="doc-meta-colon">:</span>
          <strong class="doc-meta-val">${escapeHtml(item.location || "Not specified")}, Barangay ${escapeHtml(concernBarangay(item) || "")}</strong>
        </div>
        <div class="doc-meta-item">
          <span class="doc-meta-key">First Reported</span>
          <span class="doc-meta-colon">:</span>
          <span class="doc-meta-val">${escapeHtml(firstReportedDate)}</span>
        </div>
        <div class="doc-meta-item">
          <span class="doc-meta-key">Latest Report</span>
          <span class="doc-meta-colon">:</span>
          <span class="doc-meta-val">${escapeHtml(latestReportedDate)}</span>
        </div>
        <div class="doc-meta-item">
          <span class="doc-meta-key">Resident Reports</span>
          <span class="doc-meta-colon">:</span>
          <span class="doc-meta-val">
            <span class="concern-reports-badge">
              <span class="material-symbols-rounded">people</span>
              <strong>${formatNumber(reporterCount)} reports</strong>
            </span>
          </span>
        </div>
        <div class="doc-meta-item">
          <span class="doc-meta-key">Status</span>
          <span class="doc-meta-colon">:</span>
          <span class="doc-meta-val">
            ${statusPill(status)}
          </span>
        </div>
        ` : `
        <div class="doc-meta-item">
          <span class="doc-meta-key">Resident Name</span>
          <span class="doc-meta-colon">:</span>
          <strong class="doc-meta-val">${escapeHtml(residentName(item))}</strong>
        </div>
        <div class="doc-meta-item">
          <span class="doc-meta-key">Barangay</span>
          <span class="doc-meta-colon">:</span>
          <strong class="doc-meta-val">${escapeHtml(concernBarangay(item) || "Not provided")}</strong>
        </div>
        <div class="doc-meta-item">
          <span class="doc-meta-key">Concern Category</span>
          <span class="doc-meta-colon">:</span>
          <span class="doc-meta-val">${escapeHtml(category)}</span>
        </div>
        <div class="doc-meta-item">
          <span class="doc-meta-key">Date Submitted</span>
          <span class="doc-meta-colon">:</span>
          <span class="doc-meta-val">${escapeHtml(dateLongStr)}</span>
        </div>
        <div class="doc-meta-item">
          <span class="doc-meta-key">Concern Type</span>
          <span class="doc-meta-colon">:</span>
          <span class="doc-meta-val">
            <span class="doc-concern-type-pill">${escapeHtml(category)}</span>
          </span>
        </div>
        <div class="doc-meta-item">
          <span class="doc-meta-key">Status</span>
          <span class="doc-meta-colon">:</span>
          <span class="doc-meta-val">
            ${statusPill(status)}
          </span>
        </div>
        `}
      </div>

      ${isGrouped ? `
      <!-- Group-Level Official Actions (applies once at group level) -->
      <div class="group-official-actions-banner">
        <div class="group-actions-lead">
          <div class="group-actions-title">
            <span class="material-symbols-rounded">group_work</span>
            <strong>Group-Level Official Action</strong>
            <span class="group-reports-count">${formatNumber(reporterCount)} reports</span>
          </div>
          <p class="group-actions-desc">Official actions happen ONCE at the group level and notify all ${formatNumber(reporterCount)} residents.</p>
        </div>
        <div class="group-actions-btns">
          <button class="button button--secondary" type="button" onclick="openAskInfoModal('${safeId(item.id)}')" ${status === "needs_information" || status === "resolved" ? "disabled title='Already Needs Information or Resolved'" : ""}>
            <span class="material-symbols-rounded">contact_support</span>Request Information
          </button>
          <button class="button button--primary" type="button" onclick="openResolveConcernModal('${safeId(item.id)}')" ${status === "resolved" ? "disabled title='Already Resolved'" : ""}>
            <span class="material-symbols-rounded">task_alt</span>Mark as Resolved
          </button>
          <button class="button button--secondary" type="button" onclick="startHandlingConcern('${safeId(item.id)}')" ${status === "being_handled" || status === "resolved" ? "disabled title='Already In Progress or Resolved'" : ""}>
            <span class="material-symbols-rounded">construction</span>In Progress
          </button>
        </div>
      </div>
      ` : ""}

      <!-- System-arranged Subject and Narrative -->
      <div class="doc-sheet-arranged-content">
        <div class="doc-sheet-thin-rule"></div>
        <h3 class="doc-sheet-arranged-headline">${escapeHtml(title)}</h3>
        <div class="doc-sheet-thin-rule subtle"></div>
        <div class="doc-sheet-arranged-body">${escapeHtml(description).replace(/\n/g, "<br>")}</div>
      </div>

      <!-- Location if present -->
      ${item.location ? `
      <div class="doc-sheet-location-callout">
        <span class="material-symbols-rounded">location_on</span>
        <div>
          <span><strong>Location:</strong> ${escapeHtml(item.location)}, Barangay ${escapeHtml(concernBarangay(item) || "")}</span>
          ${hasCoordinates ? `<a class="doc-map-btn" href="https://www.google.com/maps?q=${latitude},${longitude}" target="_blank" rel="noopener noreferrer"><span class="material-symbols-rounded">map</span>View Map</a>` : ""}
        </div>
      </div>` : ""}

      <!-- Supporting Evidence Photos -->
      ${evidence.length ? `
      <div class="doc-sheet-evidence-section">
        <h4 class="doc-sheet-section-title">Supporting Evidence</h4>
        <div class="doc-sheet-evidence-gallery">
          ${evidence.map((url, idx) => `
            <figure class="doc-sheet-photo-card">
              <button class="doc-photo-thumb-btn" type="button" onclick="openConcernEvidence('${safeId(item.id)}', ${idx})" title="Click to view full photo">
                <img src="${escapeAttribute(url)}" alt="Submitted evidence photo ${idx + 1}" loading="lazy">
                <span class="doc-photo-zoom-overlay"><span class="material-symbols-rounded">zoom_in</span>View</span>
              </button>
              <figcaption class="doc-photo-name">evidence${idx + 1}.jpg</figcaption>
            </figure>
          `).join("")}
        </div>
      </div>` : ""}

      ${isGrouped ? `
      <!-- All Individual Resident Submissions Below -->
      <section class="doc-sheet-grouped-submissions-section">
        <div class="doc-sheet-thin-rule"></div>
        <div class="grouped-submissions-heading">
          <div class="grouped-submissions-title-row">
            <span class="material-symbols-rounded" style="color: light-dark(#087454, var(--primaryGreen)); font-size: 22px;">people</span>
            <h4 class="doc-sheet-section-title" style="margin: 0;">Individual Resident Submissions (${formatNumber(reporterCount)})</h4>
          </div>
          <p style="font-size: 12px; color: light-dark(#557065, var(--textSecondary)); margin: 4px 0 12px;">All individual reports attached to this grouped concern with original descriptions, dates, and evidence.</p>
        </div>
        <div id="groupedSubmissionsContainer_${safeId(item.id)}" class="grouped-submissions-list">
          <div class="grouped-submissions-loading" style="padding: 16px; text-align: center; color: light-dark(#607a6e, var(--textSecondary));">
            <span class="material-symbols-rounded spin" style="vertical-align: middle;">progress_activity</span>
            <span style="margin-left: 8px;">Loading resident submissions...</span>
          </div>
        </div>
      </section>
      ` : ""}

      ${concernResidentResponsesMarkup(item)}

      <!-- Official Document Footer per request -->
      <footer class="doc-sheet-official-footer">
        <div class="doc-sheet-footer-line"></div>
        <div class="doc-sheet-footer-content">
          <div class="doc-footer-left">
            <span class="material-symbols-rounded doc-footer-verify-icon">verified</span>
            <div class="doc-footer-legal-copy">
              <strong>Municipality of Barili &bull; E-SUGID Platform</strong>
              <span>Official Electronic Resident Concern Record &bull; Province of Cebu</span>
              <span class="doc-footer-timestamp">System Record Verified on ${escapeHtml(printDateStr)}</span>
            </div>
          </div>
          <div class="doc-footer-right">
            <span class="doc-footer-barcode-art" aria-hidden="true">||| | || |||| | ||| | ||</span>
            <span class="doc-footer-tracking">DOC-${escapeHtml(item.id)}</span>
            <small class="doc-footer-certified">Certified Digital Copy</small>
          </div>
        </div>
      </footer>
    </section>`;
}

