function renderConcernDetailEmpty() {
  const detail = byId("concernDetailPane");
  if (detail) detail.innerHTML = '<div class="concern-detail-empty"><span class="material-symbols-rounded">find_in_page</span><h2>Select a concern</h2><p>Choose a resident concern from the records on the left.</p></div>';
}

async function loadGroupedConcernSubmissions(item) {
  const container = byId(`groupedSubmissionsContainer_${safeId(item.id)}`);
  if (!container) return;
  try {
    const snapshot = await getDocs(collection(db, "submissions", item.id, "reports"));
    const reports = snapshot.docs.map((docSnap) => ({ id: docSnap.id, ...docSnap.data() }))
      .sort((a, b) => dateValue(a.submittedAt) - dateValue(b.submittedAt));

    const displayReports = reports.length ? reports : [{
      reporterName: residentName(item),
      submittedAt: item.date || item.createdAt,
      location: item.location,
      description: item.description || item.title,
      attachmentUrl: item.attachmentUrl || item.imageUrl || item.photoUrl,
    }];

    container.innerHTML = displayReports.map((report, idx) => `
      <div class="grouped-submission-card">
        <div class="grouped-submission-top">
          <div class="grouped-submission-user">
            <span class="material-symbols-rounded">person</span>
            <strong>${escapeHtml(report.reporterName || "Resident #" + (idx + 1))}</strong>
            <span class="grouped-submission-tag">Report #${idx + 1}</span>
          </div>
          <time class="grouped-submission-time">
            <span class="material-symbols-rounded">schedule</span>
            ${escapeHtml(formatDate(report.submittedAt))}
          </time>
        </div>
        ${report.location ? `
          <div class="grouped-submission-loc">
            <span class="material-symbols-rounded">location_on</span>
            <span>${escapeHtml(report.location)}</span>
          </div>
        ` : ""}
        <div class="grouped-submission-text">
          ${escapeHtml(report.description || "No description provided.").replace(/\n/g, "<br>")}
        </div>
        ${report.attachmentUrl ? `
          <div class="grouped-submission-media">
            <a class="grouped-evidence-thumb" href="${escapeAttribute(report.attachmentUrl)}" target="_blank" rel="noopener noreferrer">
              <img src="${escapeAttribute(report.attachmentUrl)}" alt="Resident evidence #${idx + 1}" loading="lazy">
              <span><span class="material-symbols-rounded">open_in_new</span>View Photo</span>
            </a>
          </div>
        ` : ""}
      </div>
    `).join("");
  } catch (error) {
    console.error("Failed to load resident submissions", error);
    container.innerHTML = `<p class="concern-report-empty">Could not load individual submissions: ${escapeHtml(callableErrorMessage(error))}</p>`;
  }
}

let concernDetailRequest = 0;
window.openConcern = async (id, { preserveBrowserPosition = false, defaultView = "actions" } = {}) => {
  const item = findCase(id);
  if (!item) return;
  state.selectedConcernId = id;
  byId("page-concerns").classList.add("show-detail");
  byId("concernDocumentGrid")?.querySelectorAll(".concern-record-card").forEach((card) => {
    const selected = card.getAttribute("aria-label")?.includes(item.id);
    card.classList.toggle("selected", selected);
    card.setAttribute("aria-current", String(selected));
  });
  const detail = byId("concernDetailPane");
  detail.dataset.view = "workspace";
  detail.innerHTML = caseWorkspaceMarkup(item, item.statusHistory || [], defaultView);
  if (!preserveBrowserPosition) document.querySelector(".workspace")?.scrollTo({ top: 0, behavior: "auto" });
  loadGroupedConcernSubmissions(item);
  const request = ++concernDetailRequest;
  const entries = await concernTimelineEntries(item);
  if (request !== concernDetailRequest || state.selectedConcernId !== id || detail.dataset.view !== "workspace") return;
  // A resident report or history may have been opened while the timeline loaded.
  const currentView = byId("printableConcernRecord")?.hidden === false ? "report" : "actions";
  const historyOpen = byId("subpageHistoryView")?.hidden === false;
  detail.innerHTML = caseWorkspaceMarkup(item, entries, currentView);
  if (historyOpen) window.setActionHistorySubpage("history");
  loadGroupedConcernSubmissions(item);
};

window.setConcernWorkspaceView = (viewName) => {
  const reportContainer = byId("printableConcernRecord");
  const actionsContainer = byId("concernActionsHistoryContainer");
  const toggleBtn = document.querySelector(".concern-view-toggle-btn");

  if (!reportContainer || !actionsContainer) return;

  if (viewName === "report") {
    reportContainer.hidden = false;
    actionsContainer.hidden = true;
    if (toggleBtn) {
      toggleBtn.className = "button button--primary concern-view-toggle-btn";
      toggleBtn.setAttribute("onclick", "setConcernWorkspaceView('actions')");
      toggleBtn.innerHTML = '<span class="material-symbols-rounded">bolt</span>Action &amp; Report';
    }
  } else {
    reportContainer.hidden = true;
    actionsContainer.hidden = false;
    if (toggleBtn) {
      toggleBtn.className = "button button--secondary concern-view-toggle-btn";
      toggleBtn.setAttribute("onclick", "setConcernWorkspaceView('report')");
      toggleBtn.innerHTML = '<span class="material-symbols-rounded">description</span>View Official Report';
    }
  }
};

window.setConcernWorkspaceTab = window.setConcernWorkspaceView;

window.setActionHistorySubpage = (subpage) => {
  const actionsView = byId("subpageActionsView");
  const historyView = byId("subpageHistoryView");
  const btnActions = byId("subnavBtnActions");
  const btnHistory = byId("subnavBtnHistory");

  if (!actionsView || !historyView) return;

  if (subpage === "history") {
    actionsView.hidden = true;
    historyView.hidden = false;
    btnActions?.classList.remove("active");
    btnHistory?.classList.add("active");
  } else {
    actionsView.hidden = false;
    historyView.hidden = true;
    btnActions?.classList.add("active");
    btnHistory?.classList.remove("active");
  }
};

window.openConcernManagement = (id, options) => {
  return window.openConcern(id, options);
};

window.backToConcernBrowser = () => {
  byId("page-concerns").classList.remove("show-detail");
  delete byId("concernDetailPane")?.dataset.view;
  if (window.innerWidth < 1100) byId("concernBrowser")?.scrollIntoView({ behavior: "smooth", block: "start" });
};

window.printConcern = (id) => {
  if (state.selectedConcernId !== id) return;
  if (typeof window.setConcernWorkspaceView === "function") {
    window.setConcernWorkspaceView("report");
  }
  document.body.classList.add("printing-concern");
  window.print();
  window.setTimeout(() => document.body.classList.remove("printing-concern"), 250);
};
window.openConcernEvidence = (id, index) => {
  const item = findCase(id);
  const url = item ? concernEvidenceUrls(item)[index] : null;
  if (!url) return;
  openModal("Submitted evidence", item.id, `<div class="concern-evidence-lightbox"><img src="${escapeAttribute(url)}" alt="Submitted concern evidence"></div>`, '<button class="button button--primary" type="button" onclick="closeModal()">Close</button>');
};

window.openConcernReports = async (id) => {
  const item = findCase(id);
  if (!item) return;
  try {
    const snapshot = await getDocs(collection(db, "submissions", id, "reports"));
    const reports = snapshot.docs.map((document) => document.data())
      .sort((a, b) => dateValue(a.submittedAt) - dateValue(b.submittedAt));
    openModal("Resident reports", item.title || id,
      reports.map((report, index) => `<div class="detail-grid"><div class="detail-item full"><label>Report ${index + 1} · ${escapeHtml(formatDate(report.submittedAt))}</label><strong>${escapeHtml(report.reporterName || "Resident")}</strong></div><div class="detail-item full"><label>Location</label><p>${escapeHtml(report.location || "Not specified")}</p></div><div class="detail-item full"><label>Description</label><p>${escapeHtml(report.description || "")}</p></div>${report.attachmentUrl ? `<div class="detail-item full"><a href="${escapeAttribute(report.attachmentUrl)}" target="_blank" rel="noopener noreferrer">View evidence</a></div>` : ""}</div>`).join("") || "<p>No resident reports found.</p>",
      '<button class="button button--primary" type="button" onclick="closeModal()">Done</button>');
  } catch (error) { showToast(`Could not load reports: ${callableErrorMessage(error)}`, true); }
};

window.openFlagConcernModal = (id) => {
  const item = findCase(id);
  if (!item || item.moderationFlagStatus === "pending_review") return;
  const reasons = ["False / Fake Report", "Nonsense / Spam", "Inaccurate Information", "Duplicate / Misleading Report", "Other"];
  openModal("Concern moderation", "Flag Concern",
    `<p class="modal-lead">Flag ${escapeHtml(item.id)} for review. This does not restrict the resident.</p>
     <label class="field field--full"><span>Reason</span><select id="concernFlagReason" onchange="document.getElementById('concernFlagExplanationField').hidden=this.value!=='Other'">
       <option value="">Select a reason</option>${reasons.map((reason) => `<option value="${escapeAttribute(reason)}">${escapeHtml(reason)}</option>`).join("")}
     </select></label>
     <label id="concernFlagExplanationField" class="field field--full" hidden><span>Short explanation</span><textarea id="concernFlagExplanation" rows="3" maxlength="300" placeholder="Explain the concern flag"></textarea></label>`,
    `<button class="button button--secondary" type="button" onclick="closeModal()">Cancel</button><button class="button button--danger" type="button" onclick="submitConcernFlag('${safeId(id)}', this)">Flag Concern</button>`);
};

window.submitConcernFlag = async (id, button) => {
  if (button?.disabled) return;
  const reason = byId("concernFlagReason")?.value || "";
  const explanation = byId("concernFlagExplanation")?.value.trim() || "";
  if (!reason) { showModalFieldError("concernFlagReason", "Choose a reason."); return; }
  if (reason === "Other" && explanation.length < 3) {
    showModalFieldError("concernFlagExplanation", "Add a short explanation."); return;
  }
  setButtonBusy(button, true, "Flagging...");
  try {
    await flagConcernCall({ concernId: id, reason, explanation });
    closeModal();
    showToast("Concern flagged for review. The resident was not restricted.");
    openConcern(id);
  } catch (error) {
    showToast(callableErrorMessage(error), true);
    setButtonBusy(button, false);
  }
};

window.openConcernStatusModal = (id) => {
  const isOversight = (typeof isLguAdmin === "function" ? isLguAdmin() : canonicalRole(state.currentProfile?.role) === "super_admin") || canonicalRole(state.currentProfile?.role) === "mayor";
  if (isOversight) {
    showToast("Municipal administration has view-only access. Actions are managed by the responsible barangay.", true);
    return;
  }
  const item = findCase(id);
  if (!item) return;
  const status = concernStatus(item);
  const unclaimedOrganization = canonicalRole(state.currentProfile?.role) === "organization"
    && Number(item.schemaVersion || 0) >= 4 && !item.leadOrganizationId;
  const options = [
    { value: "handle", label: "In Progress", icon: "progress_activity", disabled: status === "being_handled" },
    { value: "request_information", label: "Awaiting Information", icon: "contact_support", disabled: status === "needs_information" || unclaimedOrganization },
    { value: "resolve", label: "Resolved", icon: "task_alt", disabled: unclaimedOrganization }
  ];
  openModal(
    "Concern Status",
    "Choose a new status",
    `<p class="concern-status-current">Current status: <strong>${escapeHtml(statusLabel(status))}</strong></p><div class="concern-status-choices" role="group" aria-label="Choose concern status">${options.map((option) => `
      <button class="concern-status-choice" type="button" data-status-action="${option.value}" onclick="chooseConcernStatus('${safeId(id)}', '${option.value}')" ${option.disabled ? "disabled" : ""}>
        <span class="material-symbols-rounded" aria-hidden="true">${option.icon}</span><span>${option.label}</span>
      </button>`).join("")}</div>`,
    '<button class="button button--secondary" type="button" onclick="closeModal()">Cancel</button>'
  );
};

window.chooseConcernStatus = (id, action) => {
  const isOversight = (typeof isLguAdmin === "function" && isLguAdmin())
    || (typeof canonicalRole === "function" && typeof state !== "undefined" && canonicalRole(state?.currentProfile?.role) === "mayor");
  if (isOversight) {
    showToast("Municipal administration has view-only access. Actions are managed by the responsible barangay.", true);
    return;
  }
  if (action === "handle") {
    window.startHandlingConcern(id);
  } else if (action === "request_information") {
    closeModal();
    window.openAskInfoModal(id);
  } else if (action === "resolve") {
    closeModal();
    window.openResolveConcernModal(id);
  }
};

window.startHandlingConcern = (id) => {
  window.openHandleConcernModal(id);
};

window.applyProgressNotePreset = (text) => {
  const el = byId("handleConcernNoteInput");
  if (el) {
    el.value = text;
    el.focus();
  }
};

window.openHandleConcernModal = (id) => {
  const item = findCase(id);
  if (!item) return;
  const refNo = `CON-${item.id.replace(/[^a-zA-Z0-9]/g, "").slice(-6).toUpperCase()}`;
  const title = item.title || item.category || "Concern";
  const existingNote = item.handlingNote
    || [...(item.statusHistory || [])].reverse().find((e) => e.status === "being_handled" && e.action === "handle")?.note
    || "";
  const isAlreadyHandling = concernStatus(item) === "being_handled";
  const modalTitle = isAlreadyHandling ? "Update Progress Note" : "Mark Concern In Progress";
  const submitBtnText = isAlreadyHandling ? "Save & Send Update" : "Set In Progress";

  openModal(
    "Concern Update",
    modalTitle,
    `<form id="handleConcernForm" onsubmit="event.preventDefault(); submitHandleConcern('${safeId(item.id)}')">
      <div class="concern-modal-ref-strip">
        <span class="concern-ref-badge">${escapeHtml(refNo)}</span>
        <span class="concern-modal-ref-title">${escapeHtml(title)}</span>
      </div>
      <label class="concern-modal-field">
        <span class="concern-modal-label">Progress Note for Resident</span>
        <textarea id="handleConcernNoteInput" class="concern-modal-textarea" rows="4" maxlength="800" placeholder="e.g. Site inspection is ongoing; our barangay team will resolve this shortly." required>${escapeHtml(existingNote)}</textarea>
      </label>
      <div class="progress-note-presets">
        <span class="preset-label">Quick suggestions:</span>
        <button type="button" class="preset-chip" onclick="applyProgressNotePreset('Site inspection is scheduled for this concern.')">Site inspection scheduled</button>
        <button type="button" class="preset-chip" onclick="applyProgressNotePreset('Our barangay team is currently coordinating action on site.')">Barangay team coordinating</button>
        <button type="button" class="preset-chip" onclick="applyProgressNotePreset('Work crew and materials have been deployed to address this report.')">Crew &amp; materials deployed</button>
        <button type="button" class="preset-chip" onclick="applyProgressNotePreset('Your concern is under active review and scheduled for resolution.')">Under active review</button>
      </div>
      <div class="progress-note-live-hint">
        <span class="material-symbols-rounded">notifications_active</span>
        <span>This note is immediately sent to the resident's mobile tracking screen and notification feed.</span>
      </div>
    </form>`,
    `<button class="button button--secondary" type="button" onclick="closeModal()">Cancel</button>
     <button class="button button--primary" type="button" onclick="submitHandleConcern('${safeId(item.id)}')">
       <span class="material-symbols-rounded">check</span>${submitBtnText}
     </button>`,
    "modal-card--case-update"
  );
  requestAnimationFrame(() => {
    const el = byId("handleConcernNoteInput");
    if (el) {
      el.focus();
      el.setSelectionRange(el.value.length, el.value.length);
    }
  });
};

window.submitHandleConcern = async (id) => {
  const item = findCase(id);
  if (!item) return;
  const note = byId("handleConcernNoteInput")?.value.trim() || "";
  if (note.length < 3) {
    showToast("Please enter a progress note for the resident.", true);
    byId("handleConcernNoteInput")?.focus();
    return;
  }
  const button = modal.querySelector(".button--primary");
  setButtonBusy(button, true, "Saving note...");

  const actorName = currentOfficialName() || "Barangay Official";
  const now = new Date();

  // The reviewConcern function saves the note on the concern and its public
  // timeline, and sends the residents' in-app notifications and pushes, in one
  // step. A failure is reported instead of claiming the note was sent.
  try {
    await reviewConcernCall({ submissionId: id, action: "handle", reason: note });
  } catch (error) {
    showToast(`Progress note was not sent: ${callableErrorMessage(error)}`, true);
    setButtonBusy(button, false);
    return;
  }

  // Update local in-memory concern and UI
  item.status = "being_handled";
  item.handlingNote = note;
  item.progressNote = note;
  item.handledByName = actorName;
  if (!Array.isArray(item.statusHistory)) item.statusHistory = [];
  item.statusHistory.push({
    status: "being_handled",
    action: "handle",
    note: note,
    reason: note,
    actorName,
    date: now.toISOString(),
    visibility: "public"
  });

  closeModal();
  showToast("Progress note saved and sent to resident!");
  renderConcerns();
  if (byId("page-concerns")?.classList.contains("show-detail") && state.selectedConcernId === id) {
    await openConcern(id, { defaultView: "actions" });
  }
};

function getStoredSummons(concernId) {
  try {
    const raw = localStorage.getItem(`esugid_summons_${concernId}`);
    return raw ? JSON.parse(raw) : null;
  } catch (e) {
    return null;
  }
}

function setStoredSummons(concernId, data) {
  try {
    localStorage.setItem(`esugid_summons_${concernId}`, JSON.stringify(data));
  } catch (e) {}
}

function getConcernSummons(item) {
  if (!item) return null;
  if (item.summons && (item.summons.appearanceDate || item.summons.respondentName)) {
    setStoredSummons(item.id, item.summons);
    return item.summons;
  }
  const cached = getStoredSummons(item.id);
  if (cached && (cached.appearanceDate || cached.respondentName)) {
    item.summons = cached;
    return cached;
  }
  if (Array.isArray(item.statusHistory)) {
    const entry = item.statusHistory.slice().reverse().find((h) => h.action === "summons_issued");
    if (entry) {
      let parsedDate = "";
      let parsedTime = "09:00 AM";
      if (entry.note) {
        const dateMatch = entry.note.match(/hearing on ([^ ]+(?: \d{1,2},? \d{4})?)/i);
        if (dateMatch) parsedDate = dateMatch[1];
        const timeMatch = entry.note.match(/at (\d{1,2}:\d{2}\s*(?:AM|PM)?)/i);
        if (timeMatch) parsedTime = timeMatch[1];
      }
      const recovered = {
        respondentName: item.respondentName || "Respondent",
        appearanceDate: item.appearanceDate || parsedDate || "",
        appearanceTime: item.appearanceTime || parsedTime || "09:00 AM",
        appearanceVenue: item.appearanceVenue || `Barangay Hall of ${concernBarangay(item) || "Barili"}`,
        remarks: entry.note || "",
        status: "issued",
        deliveryMethod: "Personal service via Barangay Tanod",
      };
      item.summons = recovered;
      setStoredSummons(item.id, recovered);
      return recovered;
    }
  }
  return null;
}

// ---------------------------------------------------------------------------
// Barangay complaints: disputes between residents (kind "complaint"). They
// share storage and actions with concerns, but get their own case board.
// ---------------------------------------------------------------------------

function isComplaintCase(item) {
  return String(item?.kind || "").toLowerCase() === "complaint";
}

/** A concern or complaint by ID, for actions shared by both pages. */
function findCase(id) {
  return state.concerns.find((item) => item.id === id)
    || (state.complaints || []).find((item) => item.id === id);
}

// Complaint UI delegates to the same pure tracking rules used by the callable.
function complaintDetails(item) { return item?.complaint || {}; }
function complaintRespondent(item) { return String(item?.complaint?.respondentName || item?.respondentName || "").trim(); }
function complaintWorkflowStatus(item) { return trackingRules.trackingStatus(item); }
function complaintStage(item) { return complaintBucket(item); }
function complaintStagePill(stage, item) { return getComplaintTracker().pill(item); }
let complaintTracker;
function applyComplaintTrackingResponse(id, result) {
  const item = findCase(id);
  if (!item || (item.workflowVersion || 0) > result.workflowVersion) return;
  const history = item.statusHistory || [];
  Object.assign(item, result.update);
  if (!history.some((event) => event.date === result.event.date && event.action === result.event.action)) history.push(result.event);
  item.statusHistory = history;
}
async function saveComplaintSummonsForm(item, form, action, payload) {
  const signature = JSON.stringify(payload);
  if (!form.dataset.operationId || form.dataset.signature !== signature) form.dataset.operationId = crypto.randomUUID();
  form.dataset.signature = signature;
  const response = await advanceComplaintWorkflowCall({ submissionId: item.id, action, ...payload,
    operationId: form.dataset.operationId, expectedVersion: Number(form.dataset.expectedVersion) });
  if (!response.data?.success) throw new Error("The update was not confirmed. Please retry.");
  applyComplaintTrackingResponse(item.id, response.data);
}
function getComplaintTracker() {
  return complaintTracker ||= createComplaintTracking({
    items: () => state.complaints || [], find: findCase, byId, escape: escapeHtml,
    openModal, closeModal, toast: showToast, call: advanceComplaintWorkflowCall,
    residentName, protectEdits: protectModalEdits,
    issueSummons: (id) => openIssueSummonsModal(id), viewSummons: (id) => openOfficialSummonsModal(id),
    notifySummons: (id) => openNotifyReporterModal(id),
    openCfa: (id) => openOfficialCfaModal(id),
    openKasunduan: (id) => openOfficialKasunduanModal(id),
    formatDate: (value) => {
      const date = parseDate(value);
      return date.valueOf() ? new Intl.DateTimeFormat("en-PH", { dateStyle: "medium", timeStyle: "short", timeZone: "Asia/Manila" }).format(date) : "Not recorded";
    },
    saved: applyComplaintTrackingResponse,
  });
}
function renderComplaints() { getComplaintTracker().render(); }
window.openComplaintCase = (id) => getComplaintTracker().open(id);

window.openIssueSummonsModal = (id) => {
  const item = findCase(id);
  if (!item) return;
  const complaint = isComplaintCase(item);
  const hearing = complaint ? trackingRules.activeHearing(item) : null;
  if (complaint && (trackingRules.TERMINAL.has(trackingRules.trackingStatus(item)) || trackingRules.requiresTrackingConfirmation(item))) {
    showToast("This complaint is already finished or requires confirmation.", true); return;
  }

  const defaultVenue = `Barangay Hall of ${escapeHtml(concernBarangay(item) || "Barili")}`;
  const suggestedPurpose = item.category === "Noise Disturbance" || (item.title && item.title.toLowerCase().includes("noise"))
    ? "Noise complaint mediation"
    : `Mediation regarding ${escapeHtml(item.complaint?.complaintType || item.category || item.type || "resident dispute")}`;

  const currentCount = item.summons?.summonsCount || (item.summonsHistory?.length ? item.summonsHistory.length : 0);
  const nextCount = hearing?.number || Math.min(3, currentCount + 1);

  const tomorrow = new Date();
  tomorrow.setDate(tomorrow.getDate() + 2);
  const yyyy = tomorrow.getFullYear();
  const mm = String(tomorrow.getMonth() + 1).padStart(2, "0");
  const dd = String(tomorrow.getDate()).padStart(2, "0");
  const defaultDate = `${yyyy}-${mm}-${dd}`;

  const hearingDateVal = hearing?.date || defaultDate;
  const hearingTimeVal = hearing?.time || "09:00";
  const hearingVenueVal = hearing?.venue || defaultVenue;
  const complainantNameVal = residentName(item);
  const respondentNameVal = item.respondentName || complaintRespondent(item) || item.complaint?.respondentName || "";
  const respondentAddressVal = formatCompleteLocation(item.respondentAddress || complaintDetails(item).respondentAddress || item.location || "", concernBarangay(item) || "Barili");

  openModal(
    "Issue Official Summons (Patawag)",
    `Case ${escapeHtml(item.id)}`,
    `<form id="issueSummonsForm" onsubmit="event.preventDefault(); submitIssueSummons('${safeId(item.id)}')">
      <div class="summons-simple-form">
        <div style="background: light-dark(#f8fafc, var(--surface)); border: 1px solid light-dark(#e2e8f0, var(--infoBorder)); border-radius: 10px; padding: 12px 16px; margin-bottom: 14px; display: grid; grid-template-columns: 1fr 1fr; gap: 12px;">
          <div>
            <span style="font-size: 11px; text-transform: uppercase; font-weight: 700; color: light-dark(#64748b, var(--textSecondary)); letter-spacing: 0.5px;">Complainant</span>
            <div style="font-size: 15px; font-weight: 700; color: light-dark(#0f172a, var(--textPrimary)); margin-top: 2px;">${escapeHtml(complainantNameVal)}</div>
          </div>
          <div>
            <span style="font-size: 11px; text-transform: uppercase; font-weight: 700; color: light-dark(#64748b, var(--textSecondary)); letter-spacing: 0.5px;">Respondent</span>
            <div style="font-size: 15px; font-weight: 700; color: light-dark(#0f172a, var(--textPrimary)); margin-top: 2px;">${escapeHtml(respondentNameVal || "Not specified")}</div>
          </div>
        </div>

        <div class="summons-split-row">
          <label class="field">
            <span>Person to Summon (Respondent)</span>
            <input type="text" id="summonsRespondentName" placeholder="Full name of respondent" maxlength="150" required value="${escapeAttribute(respondentNameVal)}">
          </label>
          <label class="field">
            <span>Respondent Address / Sitio</span>
            <input type="text" id="summonsRespondentAddress" placeholder="Sitio or address in barangay" maxlength="200" required value="${escapeAttribute(respondentAddressVal)}">
          </label>
        </div>

        <div class="summons-split-row">
          <label class="field">
            <span>Schedule of Hearing (Date)</span>
            <input type="date" id="summonsAppearanceDate" required value="${escapeAttribute(hearingDateVal)}">
          </label>
          <label class="field">
            <span>Schedule of Hearing (Time)</span>
            <input type="time" id="summonsAppearanceTime" required value="${escapeAttribute(hearingTimeVal)}">
          </label>
        </div>

        <div class="summons-split-row">
          <label class="field">
            <span>Venue of Hearing</span>
            <input type="text" id="summonsAppearanceVenue" required placeholder="e.g. Barangay Hall" value="${escapeAttribute(hearingVenueVal)}">
          </label>
          <label class="field">
            <span>Assigned Tanod (Server)</span>
            <input type="text" id="summonsTanodName" placeholder="Name of Tanod" maxlength="100" value="${escapeAttribute(item.summons?.assignedTanod || "Barangay Tanod on duty")}">
          </label>
        </div>

        <div class="summons-split-row">
          <label class="field">
            <span>Summons Stage</span>
            <select id="summonsCountSelect" required>
              <option value="1" ${nextCount === 1 ? "selected" : ""}>1st Summons (Unang Patawag)</option>
              <option value="2" ${nextCount === 2 ? "selected" : ""}>2nd Summons (Ikalawang Patawag)</option>
              <option value="3" ${nextCount === 3 ? "selected" : ""}>3rd Summons (Huling Patawag)</option>
            </select>
          </label>
          <label class="field">
            <span>Reason / Subject</span>
            <input type="text" id="summonsHearingPurpose" required value="${escapeAttribute(suggestedPurpose)}">
          </label>
        </div>
      </div>
    </form>`,
    `<button class="button button--secondary" type="button" onclick="closeModal()">Cancel</button>
     <button class="button button--primary" type="button" onclick="submitIssueSummons('${safeId(item.id)}')">
       <span class="material-symbols-rounded">gavel</span>Generate a Summon
     </button>`,
    "modal-card--announcement-preview"
  );

  const dateInput = byId("summonsAppearanceDate");
  if (dateInput) {
    dateInput.min = new Date().toISOString().slice(0, 10);
  }
  if (complaint) {
    byId("issueSummonsForm").dataset.expectedVersion = String(item.workflowVersion || 0);
    protectModalEdits();
  }
};

window.submitIssueSummons = async (id) => {
  const item = findCase(id);
  if (!item) return;
  const form = byId("issueSummonsForm");
  if (!form || form.dataset.saving === "true" || !form.reportValidity()) return;

  const summonsCount = parseInt(byId("summonsCountSelect")?.value || "1", 10);
  const assignedTanod = byId("summonsTanodName")?.value.trim() || "Barangay Tanod on duty";
  const respondentName = byId("summonsRespondentName")?.value.trim() || "";
  const respondentAddress = formatCompleteLocation(byId("summonsRespondentAddress")?.value.trim() || "", concernBarangay(item) || "Barili");
  const appearanceDate = byId("summonsAppearanceDate")?.value || "";
  const appearanceTime = byId("summonsAppearanceTime")?.value || "";
  const appearanceVenue = byId("summonsAppearanceVenue")?.value.trim() || "";
  const hearingPurpose = byId("summonsHearingPurpose")?.value.trim() || "";
  const stageName = summonsCount === 1 ? "1st Summons" : (summonsCount === 2 ? "2nd Summons" : "3rd Summons");
  const notifyResidentNote = `Official ${stageName} issued to ${respondentName || 'the respondent'}. Assigned to ${assignedTanod} for delivery. Hearing on ${appearanceDate} at ${appearanceTime}.`;

  if (!respondentName) {
    showToast("Please provide the person's name or description.", true);
    byId("summonsRespondentName")?.focus();
    return;
  }
  if (!respondentAddress) {
    showToast("Please provide the address or location.", true);
    byId("summonsRespondentAddress")?.focus();
    return;
  }
  if (!appearanceDate) {
    showToast("Please choose the hearing date.", true);
    byId("summonsAppearanceDate")?.focus();
    return;
  }
  if (!appearanceTime) {
    showToast("Please specify the hearing time.", true);
    byId("summonsAppearanceTime")?.focus();
    return;
  }

  const button = modal.querySelector(".button--primary");
  if (isComplaintCase(item)) {
    form.dataset.saving = "true";
    setButtonBusy(button, true, "Generating a Summon...");
    try {
      await saveComplaintSummonsForm(item, form, "issue_summons", { respondentName, respondentAddress,
        appearanceDate, appearanceTime, appearanceVenue, hearingPurpose, summonsCount, assignedTanod });
      closeModal(true); renderComplaints(); openOfficialSummonsModal(id);
      showToast("Official summons generated. You can now notify complainants.");
    } catch (error) {
      showToast(`Summons was not issued: ${callableErrorMessage(error)}`, true);
      form.dataset.saving = "false"; setButtonBusy(button, false);
    }
    return;
  }
  setButtonBusy(button, true, "Generating Summons...");

  const actorName = currentOfficialName() || "Barangay Official";
  const now = new Date();
  const summonsData = {
    issuedAt: now.toISOString(),
    issuedByName: actorName,
    barangay: concernBarangay(item) || "Barili",
    respondentName,
    respondentAddress,
    appearanceDate,
    appearanceTime,
    appearanceVenue,
    hearingPurpose,
    summonsCount,
    assignedTanod,
    deliveryStatus: "pending",
    remarks: notifyResidentNote,
    status: "issued",
    deliveryMethod: `Personal service via ${assignedTanod}`,
  };

  try {
    await issueConcernSummonsCall({ submissionId: id, respondentName, respondentAddress,
      appearanceDate, appearanceTime, appearanceVenue, hearingPurpose, remarks: notifyResidentNote });
  } catch (error) {
    showToast(`Summons was not issued: ${callableErrorMessage(error)}`, true);
    setButtonBusy(button, false);
    return;
  }

  setStoredSummons(id, summonsData);
  item.summons = summonsData;
  item.status = "summons_issued";
  if (!Array.isArray(item.summonsHistory)) item.summonsHistory = [];
  item.summonsHistory.push(summonsData);

  if (!Array.isArray(item.statusHistory)) item.statusHistory = [];
  item.statusHistory.push({
    status: "summons_issued",
    action: "summons_issued",
    note: notifyResidentNote,
    reason: hearingPurpose,
    actorName,
    date: now.toISOString(),
    visibility: "public"
  });


  closeModal();
  showToast(`Official ${stageName} issued for ${id}!`);
  renderConcerns();
  renderComplaints();

  if (byId("page-concerns")?.classList.contains("show-detail") && state.selectedConcernId === id) {
    await openConcern(id, { defaultView: "actions" });
  }

  openOfficialSummonsModal(id);
};

