async function concernTimelineEntries(item) {
  let internalNotes = [];
  if (canonicalRole(state.currentProfile?.role) !== "mayor") {
    try {
      const notesSnapshot = await getDocs(query(collection(db, "submissions", item.id, "internal_notes"), orderBy("createdAt", "asc")));
      internalNotes = notesSnapshot.docs.map((note) => ({ ...note.data(), date: note.data().createdAt, visibility: "internal" }));
    } catch (error) {
      console.warn("Internal notes could not be loaded:", error);
    }
  }
  const publicHistory = Array.isArray(item.statusHistory) ? item.statusHistory : [];
  const referredDestinations = new Set(publicHistory
    .filter((entry) => ["referred", "forwarded"].includes(entry.action))
    .map((entry) => String(entry.destination || entry.recipientId || "")));
  const routingHistory = (Array.isArray(item.routingHistory) ? item.routingHistory : [])
    .filter((entry) => ["referred", "forwarded"].includes(entry.action)
      && !referredDestinations.has(String(entry.recipientId || "")))
    .map((entry) => ({
      ...entry,
      status: item.status,
      visibility: "internal",
      note: ["forwarded", "referred"].includes(entry.action)
        ? `Referred to ${entry.recipientName || entry.recipientId || "destination"} by ${entry.actorName || "official"}`
        : `Submitted to ${entry.recipientName || entry.recipientId || "registered barangay"}`
    }));
  return [...publicHistory, ...routingHistory, ...internalNotes];
}

