async function imageToPngDataUrl(url) {
  return new Promise((resolve, reject) => {
    const image = new Image();
    image.crossOrigin = "anonymous";
    image.onload = () => {
      const canvas = document.createElement("canvas");
      canvas.width = image.naturalWidth || image.width;
      canvas.height = image.naturalHeight || image.height;
      const context = canvas.getContext("2d");
      if (!context) { reject(new Error("Image conversion is unavailable.")); return; }
      context.drawImage(image, 0, 0);
      resolve(canvas.toDataURL("image/png"));
    };
    image.onerror = () => reject(new Error(`Could not load ${url}`));
    image.src = url;
  });
}

window.downloadConcernPdf = async (id) => {
  const item = findCase(id);
  if (!item) return;
  const button = document.querySelector(".concern-detail-pane .concern-download-pdf")
    || [...modal.querySelectorAll("button")].find((candidate) => candidate.textContent.includes("Download PDF"));
  setButtonBusy(button, true, "Preparing PDF…");
  try {
    const pdf = new jsPDF({ unit: "mm", format: "a4", orientation: "portrait" });
    const green = [7, 92, 68];
    const muted = [91, 111, 103];
    const pageWidth = pdf.internal.pageSize.getWidth();
    const margin = 18;
    let y = 18;
    const [seal, receivingLogo] = await Promise.all([
      imageToPngDataUrl(MUNICIPALITY_SEAL).catch(() => null),
      imageToPngDataUrl(barangayLogoForCase(item) || "assets/bagong-pilipinas.png")
        .catch(() => imageToPngDataUrl(MUNICIPALITY_SEAL).catch(() => null))
    ]);
    if (seal) pdf.addImage(seal, "PNG", margin, y, 22, 22);
    if (receivingLogo) pdf.addImage(receivingLogo, "PNG", pageWidth - margin - 22, y, 22, 22);
    pdf.setTextColor(...muted); pdf.setFont("helvetica", "bold"); pdf.setFontSize(9);
    pdf.text("REPUBLIC OF THE PHILIPPINES", pageWidth / 2, y + 2, { align: "center" });
    pdf.setTextColor(...green); pdf.setFontSize(15); pdf.text("MUNICIPALITY OF BARILI", pageWidth / 2, y + 9, { align: "center" });
    pdf.setTextColor(...muted); pdf.setFontSize(9); pdf.text("PROVINCE OF CEBU", pageWidth / 2, y + 15, { align: "center" });
    pdf.setTextColor(...green); pdf.setFontSize(11); pdf.text("E-SUGID CITIZEN CONCERN FORM", pageWidth / 2, y + 22, { align: "center" });
    y += 31; pdf.setDrawColor(...green); pdf.setLineWidth(0.8); pdf.line(margin, y, pageWidth - margin, y); y += 10;

    const ensureSpace = (height) => { if (y + height > 278) { pdf.addPage(); y = 18; } };
    const drawField = (label, value, x, width, minHeight = 18) => {
      const lines = pdf.splitTextToSize(String(value || "Not provided"), width - 8);
      const height = Math.max(minHeight, 12 + lines.length * 5);
      ensureSpace(height + 4);
      pdf.setFillColor(248, 251, 249); pdf.setDrawColor(210, 225, 218); pdf.roundedRect(x, y, width, height, 2.5, 2.5, "FD");
      pdf.setTextColor(...muted); pdf.setFont("helvetica", "bold"); pdf.setFontSize(8); pdf.text(label.toUpperCase(), x + 4, y + 5.5);
      pdf.setTextColor(15, 43, 34); pdf.setFont("helvetica", "normal"); pdf.setFontSize(10.5); pdf.text(lines, x + 4, y + 11);
      return height;
    };
    const columnWidth = (pageWidth - (margin * 2) - 5) / 2;
    let height = Math.max(
      drawField("Resident", residentName(item), margin, columnWidth),
      drawField("Date submitted", formatDate(item.date || item.createdAt), margin + columnWidth + 5, columnWidth)
    );
    y += height + 5;
    height = Math.max(
      drawField("Barangay", concernBarangay(item), margin, columnWidth),
      drawField("Reference", item.id, margin + columnWidth + 5, columnWidth)
    );
    y += height + 5;
    y += drawField("Recipient office", item.department || "Barangay Office", margin, pageWidth - margin * 2) + 5;
    height = Math.max(
      drawField("Category", item.category || "General concern", margin, columnWidth),
      drawField("Location", item.location || "Not provided", margin + columnWidth + 5, columnWidth)
    );
    y += height + 5;
    y += drawField("Statement of concern", item.description || item.title || "No description provided.", margin, pageWidth - margin * 2, 30) + 5;
    if (item.incidentDate) y += drawField("Incident date", item.incidentDate, margin, pageWidth - margin * 2) + 5;
    y += drawField("Processing status", statusLabel(concernStatus(item)), margin, pageWidth - margin * 2) + 7;
    ensureSpace(22);
    pdf.setFillColor(235, 247, 241); pdf.setDrawColor(188, 218, 205); pdf.roundedRect(margin, y, pageWidth - margin * 2, 20, 2.5, 2.5, "FD");
    pdf.setTextColor(...green); pdf.setFont("helvetica", "bold"); pdf.setFontSize(9); pdf.text("OFFICIAL E-SUGID RECORD", margin + 5, y + 6);
    pdf.setTextColor(...muted); pdf.setFont("helvetica", "normal"); pdf.setFontSize(8.5);
    pdf.text(pdf.splitTextToSize("This concern was submitted through E-SUGID. Use the reference number above to verify and track this case.", pageWidth - margin * 2 - 10), margin + 5, y + 11);
    pdf.save(`E-Sugid-Concern-${String(item.id).replace(/[^a-z0-9-]/gi, "-")}.pdf`);
    showToast(`PDF for ${item.id} was downloaded.`);
  } catch (error) {
    showToast(`PDF could not be created: ${callableErrorMessage(error)}`, true);
  } finally {
    setButtonBusy(button, false);
  }
};

