        <div class="wizard-3d-input-wrap wizard-3d-select-wrap">
          <select id="wizardAccountType" onchange="updateStaffWizardAccountType(this.value)">${accountTypeOptions}</select>
          <span class="material-symbols-rounded wizard-select-caret">expand_more</span>
        </div>
