window.saveStaffPassword = async () => {
  const currentPassword = byId("currentStaffPassword")?.value || "";
  const newPassword = byId("newStaffPassword")?.value || "";
  const confirmation = byId("confirmStaffPassword")?.value || "";
  if (!currentPassword) { showToast("Enter your current password.", true); return; }
  if (!validStaffPassword(newPassword)) { showToast("Use at least 6 characters.", true); return; }
  if (newPassword !== confirmation) { showToast("The new passwords do not match.", true); return; }
  if (newPassword === currentPassword) { showToast("Choose a password different from your current one.", true); return; }
  const button = modal.querySelector(".button--primary");
  setButtonBusy(button, true, "Saving…");
  try {
    const credential = EmailAuthProvider.credential(auth.currentUser.email, currentPassword);
    await reauthenticateWithCredential(auth.currentUser, credential);
    await updatePassword(auth.currentUser, newPassword);
    closeModal();
    showToast("Password changed.");
  } catch (error) {
    showToast(error?.code === "auth/invalid-credential" ? "The current password is incorrect." : humanAuthError(error), true);
    setButtonBusy(button, false);
  }
};

