function invalidateVerificationDocumentLoad() {
  verificationDocumentLoadSequence += 1;
}

async function withVerificationDocumentTimeout(promise) {
  let timeoutId;
  try {
    return await Promise.race([
      promise,
      new Promise((_, reject) => {
        timeoutId = window.setTimeout(() => {
          const error = new Error("Verification document loading timed out.");
          error.code = "storage/document-load-timeout";
          reject(error);
        }, VERIFICATION_DOCUMENT_LOAD_TIMEOUT_MS);
      })
    ]);
  } finally {
    window.clearTimeout(timeoutId);
  }
}

async function secureVerificationDocumentUrl(userId, slot) {
  const result = await withVerificationDocumentTimeout(getVerificationDocumentUrlCall({ residentId: userId, slot }));
  return result.data || { url: "", contentType: "", size: 0, name: "" };
}

function formatVerificationFileSize(bytes) {
  const num = Number(bytes);
  if (!Number.isFinite(num) || num <= 0) return "";
  if (num < 1024) return `${num} B`;
  if (num < 1024 * 1024) return `${(num / 1024).toFixed(1)} KB`;
  return `${(num / (1024 * 1024)).toFixed(2)} MB`;
}

function getVerificationDisplayFileName(docPath, docUrl, docType, metadataName) {
  const candidates = [metadataName, docPath, docUrl];
  for (const item of candidates) {
    if (!item) continue;
    try {
      let str = String(item).trim();
      if (/^https?:\/\//i.test(str)) {
        const u = new URL(str);
        str = decodeURIComponent(u.pathname);
        const oIdx = str.indexOf("/o/");
        if (oIdx !== -1) str = str.substring(oIdx + 3);
      }
      str = str.split("?")[0].split("#")[0];
      const segments = str.split(/[\/\\]/).filter(Boolean);
      const last = segments[segments.length - 1];
      if (last && !/^verifications$/i.test(last) && last.length > 2) {
        return last;
      }
    } catch (_) {}
  }
  const safeDocType = String(docType || "verification_document").trim().toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "");
  return `${safeDocType || "document"}.png`;
}

function getVerificationFileExtension(fileName, contentType, isPdf) {
  if (isPdf) return "PDF";
  if (fileName && fileName.includes(".")) {
    const parts = fileName.split(".");
    const ext = parts[parts.length - 1].trim().toUpperCase();
    if (ext.length >= 2 && ext.length <= 4) return ext;
  }
  const ct = String(contentType || "").toLowerCase();
  if (ct.includes("png")) return "PNG";
  if (ct.includes("jpeg") || ct.includes("jpg")) return "JPG";
  if (ct.includes("webp")) return "WEBP";
  if (ct.includes("gif")) return "GIF";
  return "PHOTO";
}

function residentBirthDate(value) {
  const match = String(value || "").trim().match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) return null;
  const date = new Date(Number(match[1]), Number(match[2]) - 1, Number(match[3]));
  return Number.isNaN(date.getTime()) ? null : date;
}

function residentAge(value) {
  const birthDate = residentBirthDate(value);
  if (!birthDate) return "Not available";
  const today = new Date();
  let age = today.getFullYear() - birthDate.getFullYear();
  if (today.getMonth() < birthDate.getMonth()
      || (today.getMonth() === birthDate.getMonth() && today.getDate() < birthDate.getDate())) age -= 1;
  return String(age);
}

function residentBirthDateLabel(value) {
  const date = residentBirthDate(value);
  return date
    ? new Intl.DateTimeFormat("en-PH", { month: "short", day: "numeric", year: "numeric" }).format(date)
    : "Not provided";
}

function residentAccountForAction(id) {
  const user = state.residentVerifications.find((item) => item.id === id)
    || (isLguAdmin() ? state.users.find((item) => item.id === id) : null);
  if (!user || canonicalRole(user.role) !== "resident"
      || (!isLguAdmin() && !(isBarangayRole(state.currentProfile?.role) && canViewResidentVerification(user)))) {
    showToast("You can only manage resident accounts in your assigned barangay.", true);
    return null;
  }
  return user;
}

function closeResidentActionMenus() {
  document.querySelectorAll(".resident-row-actions[open]").forEach((details) => { details.open = false; });
}

window.positionResidentActionMenu = (details) => {
  const menu = details.querySelector(".people-action-menu");
  if (!menu || !details.open) {
    if (menu) menu.style.visibility = "hidden";
    return;
  }
  document.querySelectorAll(".resident-row-actions[open]").forEach((other) => {
    if (other !== details) other.open = false;
  });
  const anchor = details.querySelector("summary").getBoundingClientRect();
  const width = menu.offsetWidth;
  const height = menu.offsetHeight;
  menu.style.left = `${Math.max(8, Math.min(anchor.right - width, window.innerWidth - width - 8))}px`;
  menu.style.top = `${anchor.bottom + height + 8 <= window.innerHeight ? anchor.bottom + 8 : Math.max(8, anchor.top - height - 8)}px`;
  menu.style.visibility = "visible";
};

document.addEventListener("click", (event) => {
  if (!event.target.closest(".resident-row-actions")) closeResidentActionMenus();
});
document.addEventListener("scroll", closeResidentActionMenus, true);
window.addEventListener("resize", closeResidentActionMenus);

function residentRestrictionActive(user) {
  if (normalize(user?.restrictionStatus) === "active") {
    return !user.restrictionEndDate || dateValue(user.restrictionEndDate) > Date.now();
  }
  return !user?.restrictionStatus && normalize(user?.status) === "suspended";
}

window.openResidentFlagHistory = async (id) => {
  const user = residentAccountForAction(id);
  if (!user || !canVerifyLocalResidents(state.currentProfile?.role)) return;
  try {
    const flags = (await listResidentConcernFlagsCall({ residentId: id })).data.flags || [];
    const history = flags.length
      ? flags.map((flag) => `<div class="detail-item full"><strong>${escapeHtml(flag.reason)}</strong><p>${escapeHtml(flag.concernId)} · ${escapeHtml(formatDate(flag.flaggedAt))} · Flagged by ${escapeHtml(flag.flaggedByName || "Concern handler")}${flag.explanation ? `<br>${escapeHtml(flag.explanation)}` : ""}</p></div>`).join("")
      : '<div class="detail-item full"><p>No concern flags on record.</p></div>';
    openModal("Resident account", `${user.name || "Resident"} · Concern flags`,
      `<p class="modal-lead">A flag is a report for review; it does not automatically restrict this account.</p><div class="detail-grid">${history}</div>`,
      `<button class="button button--secondary" type="button" onclick="closeModal()">Close</button>${hasMunicipalOversight || (canManageLocalResidents && state.currentProfile?.canVerifyResidents === true) ? `<button class="button ${residentRestrictionActive(user) ? "button--primary" : "button--danger"}" type="button" onclick="openResidentRestriction('${safeId(id)}')">${residentRestrictionActive(user) ? "Remove Restriction" : "Restrict Account"}</button>` : ""}`);
  } catch (error) {
    showToast(`Flag history could not be loaded: ${callableErrorMessage(error)}`, true);
  }
};

window.openResidentRestriction = async (id) => {
  closeResidentActionMenus();
  const user = residentAccountForAction(id);
  if (!user) return;
  if (!isLguAdmin() && (!isBarangayRole(state.currentProfile?.role) || state.currentProfile?.canVerifyResidents !== true)) {
    showToast("Only the LGU IT administrator or an authorized official from the resident's verified barangay can restrict this account.", true);
    return;
  }
  const restricted = residentRestrictionActive(user);
  openModal("Resident account", restricted ? "Remove restriction" : "Restrict Account",
    `<div class="detail-grid"><div class="detail-item full"><label>Resident</label><strong>${escapeHtml(user.name || user.email || "Resident")}</strong></div>${restricted ? '<div class="detail-item full"><p>Removing the restriction restores the account\'s previous access level.</p></div>' : `<label class="field detail-item full"><span>Restriction reason</span><textarea id="residentRestrictionReason" rows="2" maxlength="500" required placeholder="Enter the reason for restricting this account"></textarea></label><label class="field detail-item full"><span>Restriction end date and time <small>Optional</small></span><input id="residentRestrictionEndAt" type="datetime-local"></label>`}</div>`,
    `<button class="button button--secondary" type="button" onclick="closeModal()">Cancel</button><button class="button ${restricted ? "button--primary" : "button--danger"}" type="button" onclick="submitResidentAction('${safeId(id)}', '${restricted ? "restore" : "restrict"}', this)">${restricted ? "Remove Restriction" : "Restrict Account"}</button>`);
};

window.openResidentEdit = (id) => {
  closeResidentActionMenus();
  const user = residentAccountForAction(id);
  if (!user) return;
  openModal("Resident account", "Edit account", `<div class="detail-grid account-edit-grid"><label class="field detail-item full"><span>Full name</span><input id="residentEditName" maxlength="120" value="${escapeAttribute(user.name || "")}"></label><label class="field detail-item full"><span>Login email</span><input id="residentEditEmail" type="email" maxlength="254" value="${escapeAttribute(user.email || "")}"></label><label class="field detail-item"><span>Contact number <small>Optional</small></span><input id="residentEditContact" inputmode="tel" maxlength="30" value="${escapeAttribute(user.contactNumber || "")}"></label><label class="field detail-item full"><span>Address <small>Optional</small></span><input id="residentEditAddress" maxlength="200" value="${escapeAttribute(user.address || "")}"></label><div class="detail-item full"><label>Barangay</label><strong>${escapeHtml(user.barangay || "Not provided")}</strong></div></div>`, `<button class="button button--secondary" type="button" onclick="closeModal()">Cancel</button><button class="button button--primary" type="button" onclick="submitResidentAction('${safeId(id)}', 'edit', this)">Save changes</button>`);
  protectModalEdits();
};

window.openResidentDelete = (id) => {
  closeResidentActionMenus();
  const user = residentAccountForAction(id);
  if (!user) return;
  openModal("Danger zone", "Delete resident account?", `<div class="account-delete-warning"><span class="material-symbols-rounded">warning</span><div><h3>${escapeHtml(user.name || "Resident")}</h3><p>The login and resident profile will be removed permanently. Existing concern reports and municipal audit records will remain.</p></div></div>`, `<button class="button button--secondary" type="button" onclick="closeModal()">Keep account</button><button class="button button--danger" type="button" onclick="submitResidentAction('${safeId(id)}', 'delete', this)">Delete account</button>`);
};

window.submitResidentAction = async (id, action, button) => {
  if (button?.disabled || !residentAccountForAction(id)) return;
  const payload = { userId: id, action };
  if (action === "restrict") {
    payload.reason = byId("residentRestrictionReason")?.value.trim() || "";
    if (!payload.reason) { showModalFieldError("residentRestrictionReason", "Enter a reason for restricting this account."); return; }
    const endAt = byId("residentRestrictionEndAt")?.value || "";
    if (endAt && (!Number.isFinite(Date.parse(endAt)) || Date.parse(endAt) <= Date.now())) {
      showModalFieldError("residentRestrictionEndAt", "Choose a future end date and time."); return;
    }
    payload.restrictionEndAt = endAt ? new Date(endAt).toISOString() : "";
  }
  if (action === "edit") {
    payload.name = byId("residentEditName")?.value.trim() || "";
    payload.email = byId("residentEditEmail")?.value.trim() || "";
    payload.contactNumber = byId("residentEditContact")?.value.trim() || "";
    payload.address = byId("residentEditAddress")?.value.trim() || "";
    if (!payload.name) { showModalFieldError("residentEditName", "Enter the resident's full name."); return; }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(payload.email)) { showModalFieldError("residentEditEmail", "Enter a valid login email."); return; }
    if (payload.contactNumber) {
      let digits = payload.contactNumber.replace(/\D/g, "");
      if (digits.startsWith("63") && digits.length === 12) digits = `0${digits.slice(2)}`;
      if (digits.length === 10 && digits.startsWith("9")) digits = `0${digits}`;
      if (!/^09\d{9}$/.test(digits)) { showModalFieldError("residentEditContact", "Enter a valid Philippine mobile number."); return; }
    }
  }
  setButtonBusy(button, true, action === "delete" ? "Deleting..." : "Saving...");
  try {
    await manageResidentAccountCall(payload);
    closeModal(true);
    showToast(action === "delete" ? "Resident account deleted." : action === "edit" ? "Resident account updated." : action === "restore" ? "Resident account restored." : "Resident account restricted.");
    await loadResidentVerifications({ quiet: true });
  } catch (error) {
    showToast(callableErrorMessage(error), true);
    setButtonBusy(button, false);
  }
};

window.openVerification = async (id) => {
  const user = state.residentVerifications.find((item) => item.id === id);
  if (!user) return;
  if (!canViewResidentVerification(user)) { showToast("You can only view resident verification records from your own barangay.", true); return; }
  const canDecide = canReviewResidentVerification(user)
    && normalize(user.accountStatus) !== "disabled"
    && normalize(user.status) !== "suspended";
  const verification = user.verificationData || {};
  invalidateVerificationDocumentLoad();
  const loadSequence = ++verificationDocumentLoadSequence;
  const documentPanel = (panelId, label, path, emptyMessage) => `<div id="${panelId}" class="detail-item full verification-document" data-verification-load="${loadSequence}"><label>${escapeHtml(label)}</label><div class="verification-document-state${path ? " is-loading" : ""}"><span class="material-symbols-rounded">${path ? "progress_activity" : "image_not_supported"}</span><p>${escapeHtml(path ? "Loading document…" : emptyMessage)}</p></div></div>`;
  const additionalDocumentPresent = Boolean(
    verification.additionalDocumentType
    || verification.additionalDocumentPath
    || verification.additionalDocumentUrl
  );
  openModal(
    "Resident Verification",
    user.name || "Resident request",
    `<div class="account-approval-review-summary resident-verification-review-summary"><span class="material-symbols-rounded">how_to_reg</span><div><small>Resident verification</small><strong>${escapeHtml(user.name || "Resident")}</strong><span>Barangay ${escapeHtml(user.barangay || "Not provided")}</span></div>${verificationStatusPill(verificationStatus(user))}</div><div class="verification-review-sections">
      <section class="verification-review-section"><h3>Resident Information</h3><div class="detail-grid">
        <div class="detail-item"><label>Full Name</label><strong>${escapeHtml(user.name || "Not provided")}</strong></div>
        <div class="detail-item"><label>Barangay</label><strong>${escapeHtml(user.barangay || "Not provided")}</strong></div>
        <div class="detail-item"><label>Contact Number</label><strong>${escapeHtml(user.contactNumber || "Not provided")}</strong></div>
        ${user.address ? `<div class="detail-item"><label>Purok / Sitio</label><strong>${escapeHtml(user.address)}</strong></div>` : ""}
        <div class="detail-item"><label>Birth Date</label><strong>${escapeHtml(residentBirthDateLabel(user.birthDate))}</strong></div>
        <div class="detail-item"><label>Age</label><strong>${escapeHtml(residentAge(user.birthDate))}</strong></div>
      </div></section>
      <section class="verification-review-section"><h3>Uploaded Proof</h3><div class="detail-grid">
      <div class="detail-item full"><label>Document Type</label><strong>${escapeHtml(verification.documentType === "Other Proof of Address" && verification.otherDocumentName ? `${verification.documentType} — ${verification.otherDocumentName}` : verification.documentType || "Not provided")}</strong></div>
      ${user.reviewReason ? `<div class="detail-item full"><label>Needs attention reason</label><p>${escapeHtml(user.reviewReason)}${user.reviewAdditionalNote ? ` — ${escapeHtml(user.reviewAdditionalNote)}` : ""}</p></div>` : ""}
      ${user.rejectionReason || user.reviewNote ? `<div class="detail-item full"><label>Review result</label><p>${escapeHtml(user.rejectionReason || user.reviewNote)}${user.rejectionNote ? ` — ${escapeHtml(user.rejectionNote)}` : ""}</p></div>` : ""}
      ${documentPanel("verificationPrimaryDocument", "Document Preview", verification.documentPath || verification.documentUrl, "No verification document was found for this request.")}
      ${additionalDocumentPresent ? documentPanel("verificationAdditionalDocument", "Replacement Document", verification.additionalDocumentPath || verification.additionalDocumentUrl, "No replacement document was found for this request.") : ""}
      </div></section>
      ${canVerifyLocalResidents(state.currentProfile?.role) && Number(user.concernFlagCount || 0) > 0 ? `<section class="verification-review-section"><h3>Concern flags</h3><p>${Number(user.concernFlagCount)} flagged concern${Number(user.concernFlagCount) === 1 ? "" : "s"} on record.</p><button class="button button--secondary" type="button" onclick="openResidentFlagHistory('${safeId(id)}')"><span class="material-symbols-rounded" aria-hidden="true">flag</span>View flag history</button></section>` : ""}
      ${canDecide ? `<div class="verification-review-instruction"><span class="material-symbols-rounded">verified_user</span><p>Confirm proof of residency for Barangay ${escapeHtml(user.barangay || "their registered barangay")}.</p></div>` : ""}
    </div><div id="verificationDecisionError" class="account-decision-error" role="alert" hidden></div>`,
    canDecide
      ? `<button class="button button--danger modal-btn-3d" type="button" onclick="openVerificationNeedsAttention('${safeId(id)}')"><span class="material-symbols-rounded">assignment_return</span>Needs Attention</button><button class="button button--primary modal-btn-3d primary-btn-3d" type="button" onclick="confirmVerificationApproval('${safeId(id)}')"><span class="material-symbols-rounded">verified</span>Verify Resident</button>`
      : '<button class="button button--secondary" type="button" onclick="closeModal()">Close</button>'
  );

  const loadDocument = async (path, storedUrl, label, slot) => {
    if (!path && !storedUrl) return { url: "", contentType: "", size: 0, name: "", error: null };
    try {
      return { ...(await secureVerificationDocumentUrl(user.id, slot)), error: null };
    } catch (error) {
      console.error(`${label} could not be opened`, { code: error?.code });
      return { url: "", contentType: "", size: 0, name: "", error };
    }
  };
  const [primaryDocument, additionalDocument] = await Promise.all([
    loadDocument(verification.documentPath, verification.documentUrl, "Verification document", "primary"),
    loadDocument(verification.additionalDocumentPath, verification.additionalDocumentUrl, "Additional verification document", "additional")
  ]);
  const primaryPanel = byId("verificationPrimaryDocument");
  if (!primaryPanel || primaryPanel.dataset.verificationLoad !== String(loadSequence)) {
    return;
  }
  const renderDocument = (panel, result, label, emptyMessage, docPath, docUrl, docType) => {
    if (!panel) return;
    const isPdf = result.contentType.toLowerCase() === "application/pdf" || /\.pdf(?:$|[?#])/i.test(result.url);
    const displayFileName = getVerificationDisplayFileName(docPath, docUrl, docType, result.name);
    const ext = getVerificationFileExtension(displayFileName, result.contentType, isPdf);
    const formattedSize = formatVerificationFileSize(result.size);
    const metaSubtitle = formattedSize ? `${ext} • ${formattedSize}` : `${ext} • ${isPdf ? "PDF Document" : "Verification Proof"}`;

    const content = result.url
      ? `<div class="verification-document-dropzone">
          <div class="media-zone-filled-state">
            <a class="preview-media-thumb-box" href="${escapeAttribute(result.url)}" target="_blank" rel="noopener noreferrer" title="View full document">
              ${isPdf
                ? `<span class="material-symbols-rounded preview-pdf-icon">picture_as_pdf</span>`
                : `<img class="preview-media-thumb" src="${escapeAttribute(result.url)}" alt="${escapeAttribute(label)}">`
              }
            </a>
            <div class="preview-card-body">
              <div class="preview-card-header-row">
                <span class="preview-status-badge${isPdf ? " is-pdf" : ""}">${isPdf ? "PDF Document" : "Selected Photo"}</span>
              </div>
              <div class="preview-name-row">
                <strong class="preview-file-name" title="${escapeAttribute(displayFileName)}">${escapeHtml(displayFileName)}</strong>
                <small class="preview-file-size">${escapeHtml(metaSubtitle)}</small>
              </div>
              <div class="preview-actions-cluster">
                <a class="preview-action-btn preview-change-btn" href="${escapeAttribute(result.url)}" target="_blank" rel="noopener noreferrer" title="Open full document in new tab">
                  <span class="material-symbols-rounded">${isPdf ? "open_in_new" : "visibility"}</span>
                  <span>View Document</span>
                </a>
              </div>
            </div>
          </div>
        </div>`
      : `<div class="verification-document-state${result.error ? " is-error" : ""}">
          <span class="material-symbols-rounded">${result.error ? "broken_image" : "image_not_supported"}</span>
          <p>${escapeHtml(result.error ? "Unable to load verification document." : emptyMessage)}</p>
          ${result.error ? `<button class="text-button" type="button" onclick="openVerification('${safeId(id)}')">Retry</button>` : ""}
        </div>`;

    panel.innerHTML = `<label>${escapeHtml(label)}</label>${content}`;
    const image = panel.querySelector("img");
    image?.addEventListener("error", () => {
      const thumbBox = panel.querySelector(".preview-media-thumb-box");
      if (thumbBox) {
        thumbBox.innerHTML = '<span class="material-symbols-rounded" style="font-size: 38px; color: light-dark(#64748b, var(--textSecondary));">broken_image</span>';
      }
    }, { once: true });
  };
  renderDocument(
    primaryPanel,
    primaryDocument,
    "Document Preview",
    "No verification document was uploaded.",
    verification.documentPath,
    verification.documentUrl,
    verification.documentType
  );
  if (additionalDocumentPresent) {
    renderDocument(
      byId("verificationAdditionalDocument"),
      additionalDocument,
      "Replacement Document",
      "No replacement document was uploaded.",
      verification.additionalDocumentPath,
      verification.additionalDocumentUrl,
      verification.additionalDocumentType || verification.documentType
    );
  }
};

async function submitVerificationDecision(id, decision, rejectionReason = "", rejectionNote = "") {
  const user = state.residentVerifications.find((item) => item.id === id);
  if (!user || !canReviewResidentVerification(user)) { showToast("This verification is outside your authorized barangay.", true); return; }
  const button = modal.querySelector(".button--primary, .button--danger");
  setButtonBusy(button, true, decision === "approved" ? "Approvingâ€¦" : "Saving decisionâ€¦");
  try {
    setButtonBusy(button, true, decision === "approved" ? "Verifying..." : "Updating...");
    await reviewResidentVerificationCall({
      residentId: id,
      decision,
      rejectionReason,
      rejectionNote
    });
    const reviewedAt = new Date();
    user.verificationStatus = decision === "approved" ? "verified" : "additional_document_required";
    user.reviewedAt = reviewedAt;
    user.reviewedBy = auth.currentUser?.uid || "";
    user.reviewedByName = state.currentProfile?.name || state.currentProfile?.email || "Barangay reviewer";
    user.reviewReason = rejectionReason;
    user.reviewAdditionalNote = rejectionNote;
    if (decision === "approved") {
      user.verifiedAt = reviewedAt;
      user.verifiedBy = user.reviewedBy;
      user.verifiedByRole = canonicalRole(state.currentProfile?.role);
      user.verifiedByName = user.reviewedByName;
    }
    state.verificationCounts.pending = Math.max(0, state.verificationCounts.pending - 1);
    if (decision === "approved") state.verificationCounts.verified += 1;
    else state.verificationCounts.needsResubmission += 1;
    closeModal();
    renderUsersAndVerifications();
    renderDashboard();
    showToast(decision === "approved"
      ? "Resident account verified."
      : "The resident was notified that verification needs attention.");
    void loadResidentVerifications({ quiet: true });
  } catch (error) {
    setButtonBusy(button, false);
    const errorCode = String(error?.code || "");
    const errorMessage = callableErrorMessage(error);
    if (errorCode.includes("failed-precondition") && /already been reviewed|already reviewed/i.test(errorMessage)) {
      await loadResidentVerifications({ quiet: true });
      window.openVerification(id);
      showToast("This verification request has already been reviewed.", true);
      return;
    }
    const message = decision === "approved"
      ? "Unable to verify this resident. Please try again."
      : "Unable to update this verification. Please try again.";
    const target = byId("verificationDecisionError");
    if (target) { target.textContent = message; target.hidden = false; }
    showToast(message, true);
  }
}

