window.setVerificationPermission = async (userId, enabled, checkbox) => {
  checkbox.disabled = true;
  try {
    await setResidentVerificationPermissionCall({ userId, canVerifyResidents: enabled });
    const reviewer = state.verificationReviewers.find((item) => item.id === userId);
    if (reviewer) reviewer.canVerifyResidents = enabled;
    const label = checkbox.closest(".verification-reviewer-control")?.querySelector("em");
    if (label) label.textContent = enabled ? "Authorized" : "No access";
    showToast(enabled ? "Resident verification access granted." : "Resident verification access removed.");
  } catch (error) {
    checkbox.checked = !enabled;
    showToast(callableErrorMessage(error), true);
  } finally {
    checkbox.disabled = false;
  }
};

