  openModal("User account", user.name || "User", `<div class="detail-grid"><div class="detail-item"><label>Email</label><strong>${escapeHtml(user.email || "—")}</strong></div><div class="detail-item"><label>Role</label><strong>${escapeHtml(labelForRole(user.role))}</strong></div><div class="detail-item"><label>Barangay</label><strong>${escapeHtml(user.barangay || "—")}</strong></div><div class="detail-item"><label>Status</label>${statusPill(normalize(user.status || "active"))}</div><div class="detail-item full"><label>Organization</label><strong>${escapeHtml(user.organizationName || "Not applicable")}</strong></div><label class="field detail-item full"><span>Account status</span><select id="userAccountStatus"><option value="approved">Approved / active</option><option value="suspended">Suspended</option><option value="rejected">Rejected</option></select></label><label class="field detail-item full"><span>Administrative reason</span><textarea id="userStatusReason" rows="2" maxlength="500"></textarea></label></div>`, `<button class="button button--secondary" type="button" onclick="closeModal()">Cancel</button><button class="button button--primary" type="button" onclick="saveUserStatus('${safeId(id)}', this)">Save status</button>`);
  byId("userAccountStatus").value = ["approved", "suspended", "rejected"].includes(normalize(user.status)) ? normalize(user.status) : "approved";
