window.openRestrictUser = async (id) => {
  const user = state.users.find((item) => item.id === id);
  if (!user || !canManageDirectoryAccount(user) || user.id === auth.currentUser?.uid) {
    showToast("You cannot restrict this account.", true);
    return;
  }
  if (canonicalRole(user.role) === "resident") {
    if (!state.residentVerifications.some((resident) => resident.id === id)) await loadResidentVerifications({ quiet: true });
    await window.openResidentRestriction(id);
    return;
  }
  if (normalize(user.restrictionStatus) === "active" && (!user.restrictionEndDate || dateValue(user.restrictionEndDate) > Date.now())) {
    showToast("This account is already restricted. Use Edit Account to change its status.", true);
    return;
  }
  openModal("Account access", "Restrict account", `<div class="detail-grid"><div class="detail-item"><label>Account holder</label><strong>${escapeHtml(user.name || user.email || "Unnamed account")}</strong></div><div class="detail-item"><label>Account type</label><strong>${escapeHtml(labelForRole(user.role))}</strong></div><div class="detail-item full"><p>This staff account will lose access until the restriction is removed or expires. Its previous account state will be restored.</p></div><label class="field detail-item full"><span>Reason for restriction</span><textarea id="userStatusReason" rows="3" maxlength="500" required placeholder="Enter a clear reason"></textarea></label><label class="field detail-item full"><span>Restriction end date and time <small>Optional</small></span><input id="userRestrictionEndAt" type="datetime-local"></label><select id="userAccountStatus" hidden><option value="suspended" selected>Suspended</option></select></div>`, `<button class="button button--secondary" type="button" onclick="closeModal()">Cancel</button><button class="button button--danger" type="button" onclick="saveUserStatus('${safeId(id)}', this)"><span class="material-symbols-rounded">lock_person</span>Restrict account</button>`);
};

window.saveUserStatus = async (id, button) => {
  if (button?.disabled) return;
  const target = state.users.find((item) => item.id === id);
  if (!target || canonicalRole(target.role) === "resident" || !canManageDirectoryAccount(target)) { showToast("You do not have permission to change this account.", true); return; }
  const status = byId("userAccountStatus").value;
  const reason = byId("userStatusReason").value.trim();
  if (!["approved", "suspended", "rejected"].includes(status)) { showToast("Choose a valid account status.", true); return; }
  if (status !== "approved" && !reason) { showModalFieldError("userStatusReason", "Add a reason for restricting this account."); return; }
  if (id === auth.currentUser?.uid && status !== "approved") { showToast("You cannot restrict your own administrator account.", true); return; }
  if (canonicalRole(target?.role) === "super_admin" && canonicalRole(state.currentProfile?.role) !== "super_admin") { showToast("Only an LGU IT administrator can change this account.", true); return; }
  const activeItAdmins = state.users.filter((item) => canonicalRole(item.role) === "super_admin" && peopleAccountStatus(item) === "active");
  if (canonicalRole(target.role) === "super_admin" && peopleAccountStatus(target) === "active" && status !== "approved" && activeItAdmins.length <= 1) { showToast("At least one active LGU IT administrator must remain.", true); return; }
  const approvedAdmins = state.users.filter((item) => isMunicipalRole(item.role) && peopleAccountStatus(item) === "active");
  if (isMunicipalRole(target?.role) && peopleAccountStatus(target) === "active" && status !== "approved" && approvedAdmins.length <= 1) { showToast("At least one active municipal administrator must remain.", true); return; }
  const isRestrictionForm = Boolean(byId("userRestrictionEndAt"));
  const endAt = byId("userRestrictionEndAt")?.value || "";
  if (endAt && (!Number.isFinite(Date.parse(endAt)) || Date.parse(endAt) <= Date.now())) {
    showModalFieldError("userRestrictionEndAt", "Choose a future end date and time."); return;
  }
  setButtonBusy(button, true, "Saving...");
  try {
    const batch = writeBatch(db);
    batch.update(doc(db, "users", id), {
      status,
      accountStatus: status === "approved" ? "active" : "disabled",
      approvalRequired: false,
      statusReason: reason,
      ...(isRestrictionForm ? {
        restrictionStatus: "active", restrictionReason: reason,
        restrictionEndDate: endAt ? new Date(endAt) : null,
        restrictionPreviousStatus: target.status || "approved",
        restrictionPreviousAccountStatus: target.accountStatus || "active",
        restrictedBy: auth.currentUser.uid, restrictedAt: serverTimestamp(),
      } : status === "approved" && normalize(target.restrictionStatus) === "active" ? {
        restrictionStatus: "removed", unrestrictedBy: auth.currentUser.uid,
        unrestrictedAt: serverTimestamp(),
      } : {}),
      updatedAt: serverTimestamp(),
      updatedBy: auth.currentUser.uid
    });
    batch.set(doc(collection(db, "notifications")), { userId: id, type: "account_update", title: isRestrictionForm ? "Account restricted" : "Account status updated", message: reason || "Your account is active.", read: false, createdAt: serverTimestamp() });
    addAuditToBatch(batch, isRestrictionForm ? "staff_account_restricted" : "user_status_updated", "user", id, { status, reason, restrictionEndAt: endAt ? new Date(endAt).toISOString() : "" });
    await batch.commit(); closeModal(true); showToast("User status updated.");
  } catch (error) { showToast(`User update failed: ${callableErrorMessage(error)}`, true); }
  finally { setButtonBusy(button, false); }
};

