function isAnnouncementExpired(item) {
  if (!item) return false;
  const status = normalize(item.status || item.approvalStatus);
  // Drafts can retain an earlier event date while staff prepare a repost.
  if (status === "draft") return false;
  if (status === "expired" || status === "archived") return true;
  const now = new Date();
  if (item.expiresAt) {
    const exp = dateValue(item.expiresAt);
    if (exp && now > exp) return true;
  }
  if (item.eventEndAt) {
    const end = dateValue(item.eventEndAt);
    if (end && now > end) return true;
  } else if (item.eventStartAt || item.eventDate) {
    const start = dateValue(item.eventStartAt || item.eventDate);
    if (start) {
      const endOfDay = new Date(start);
      endOfDay.setHours(23, 59, 59, 999);
      if (now > endOfDay) return true;
    }
  }
  return false;
}

function announcementUiStatus(item) {
  const status = postStatus(item);
  if (isAnnouncementExpired(item)) return "archived";
  if (["approved", "published"].includes(status)) return "published";
  if (status === "expired") return "archived";
  if (status === "scheduled" && item?.publishAt) {
    const pubDate = dateValue(item.publishAt);
    if (pubDate && pubDate <= new Date()) {
      return "published";
    }
  }
  return status;
}

async function checkScheduledAnnouncementsAutoPublish() {
  const now = new Date();
  const due = (state.posts || []).filter((p) => p.status === "scheduled" && p.publishAt && dateValue(p.publishAt) <= now);
  if (!due.length) return;
  for (const post of due) {
    try {
      if (canManageAnnouncement(post)) {
        await updateDoc(doc(db, "posts", post.id), {
          status: "approved",
          publishedAt: serverTimestamp(),
          updatedAt: serverTimestamp()
        });
      }
    } catch (_) {}
  }
}

function announcementPostType(item) {
  const type = normalize(item?.announcementType);
  if (["event", "scheduled_activity"].includes(type)) return "event";
  if (type === "advisory") return "advisory";
  if (type === "general") return "general";

  // Keep older records useful when they predate the post-type field.
  const category = normalize(item?.category);
  if (/advisory|warning|alert/.test(category)) return "advisory";
  if (/event|activity|deadline|schedule/.test(category)) return "event";
  return "general";
}

function announcementDisplayCategory(item) {
  return String(item?.customCategory || item?.category || "General Information").trim();
}

function findAnnouncementById(id) {
  if (!id) return null;
  const matchId = (post) => post.id === id || safeId(post.id) === id;
  return announcementPagePosts().find(matchId)
    || (state.posts || []).find(matchId)
    || (state.announcementBarangayPosts || []).find(matchId)
    || (state.announcementMunicipalFeed || []).find(matchId)
    || (state.announcementBarangayFeed || []).find(matchId)
    || null;
}

function canManageAnnouncement(item) {
  if (!item || !auth.currentUser) return false;
  const uid = auth.currentUser.uid;
  const isAuthor = Boolean(
    (item.authorId && item.authorId === uid) ||
    (item.createdBy && item.createdBy === uid) ||
    (item.userId && item.userId === uid)
  );
  if (isAuthor) return true;

  if (!can("announcements")) return false;
  const role = canonicalRole(state.currentProfile?.role);
  if (role === "super_admin") return true;
  if (isBarangayRole(role)) return isOwnBarangayAnnouncement(item);
  if (role === "lgu") {
    const deptId = currentDepartmentId();
    const userDept = normalize(state.currentProfile?.department);
    return Boolean(
      (deptId && item.departmentId === deptId) ||
      (userDept && normalize(item.department) === userDept) ||
      (userDept && normalize(item.publisherEntityName).includes(userDept))
    );
  }
  if (role === "mayor") {
    return Boolean(
      canonicalRole(item.authorRole) === "mayor" ||
      item.publisherEntityType === "mayor"
    );
  }
  if (role === "organization") {
    const orgId = currentOrganizationId();
    const userOrg = normalize(state.currentProfile?.organizationName);
    return Boolean(
      (orgId && item.publisherEntityId === orgId) ||
      (userOrg && normalize(item.authorOrganizationName) === userOrg) ||
      (userOrg && normalize(item.publisherEntityName) === userOrg)
    );
  }
  return false;
}

function isOwnBarangayAnnouncement(item) {
  if (!item || !auth.currentUser) return false;
  const uid = auth.currentUser.uid;
  if ((item.authorId && item.authorId === uid) || (item.createdBy && item.createdBy === uid) || (item.userId && item.userId === uid)) {
    return true;
  }
  const staffBarangay = currentStaffBarangay();
  const staffBgyId = currentStaffBarangayId();
  if (staffBgyId && item.barangayId === staffBgyId) return true;
  if (staffBarangay) {
    if (canonicalBarangay(item.targetBarangay) === staffBarangay) return true;
    if (canonicalBarangay(item.authorBarangay) === staffBarangay) return true;
    if (Array.isArray(item.targetBarangays) && item.targetBarangays.some((name) => canonicalBarangay(name) === staffBarangay)) return true;
  }
  return false;
}

function barangayAnnouncementSource(item) {
  if (isOwnBarangayAnnouncement(item)) return "barangay";
  const role = canonicalRole(item?.authorRole);
  if (role === "organization") return "organization";
  if (role === "mayor" || isMunicipalRole(role)) return "lgu";
  return "";
}

function announcementPagePosts() {
  if (canonicalRole(state.currentProfile?.role) === "organization") return state.posts.filter(organizationAnnouncementMatches);
  if (!isBarangayRole(state.currentProfile?.role)) return state.posts;
  const posts = new Map([
    ...state.announcementMunicipalFeed,
    ...state.announcementBarangayFeed,
    ...state.announcementBarangayPosts,
    ...state.posts,
  ].map((item) => [item.id, item]));
  const barangay = currentStaffBarangay();
  const uid = auth.currentUser?.uid;
  return [...posts.values()].filter((item) => {
    if (isOwnBarangayAnnouncement(item)) return true;
    if (uid && (item.authorId === uid || item.createdBy === uid)) return true;
    if (announcementUiStatus(item) !== "published") return false;
    if (!["lgu", "organization"].includes(barangayAnnouncementSource(item))) return false;
    return normalize(item.visibility) === "public"
      || item.targetBarangay === "All Barangays"
      || (Array.isArray(item.targetBarangays) && item.targetBarangays.some((name) => canonicalBarangay(name) === barangay))
      || (Array.isArray(item.audienceKeys) && item.audienceKeys.includes(`barangay:${barangay}`));
  });
}

function announcementListIcon(item) {
  const value = normalize([item.title, announcementDisplayCategory(item)].join(" "));
  if (/power|electric|cebeco|interruption/.test(value)) return "bolt";
  if (/tree|plant|environment|garden/.test(value)) return "park";
  if (/clean|waste|garbage/.test(value)) return "cleaning_services";
  if (/health|medical|vaccine/.test(value)) return "health_and_safety";
  if (/event|activity|festival|meeting/.test(value)) return "event";
  if (/water|rain|weather|flood/.test(value)) return "water_drop";
  return "campaign";
}

function announcementThemeClass(icon) {
  if (icon === "bolt" || icon === "water_drop") return "theme-utility";
  if (icon === "park" || icon === "cleaning_services") return "theme-eco";
  if (icon === "health_and_safety") return "theme-health";
  if (icon === "event") return "theme-event";
  return "theme-broadcast";
}

function announcementEmptyRow() {
  const barangayManagement = isBarangayRole(state.currentProfile?.role)
    || canonicalRole(state.currentProfile?.role) === "organization";
  const filter = barangayManagement && state.announcementArchiveView ? "archived" : state.announcementTypeFilter;
  const search = byId("announcementSearch")?.value?.trim() || "";
  const publisher = byId("announcementPublisherFilter")?.value || "all";
  const source = byId("announcementSourceFilter")?.value || "all";
  const priority = byId("announcementPriorityFilter")?.value || "all";
  const hasFilter = filter !== "all" || search !== "" || publisher !== "all" || source !== "all" || priority !== "all";

  let icon = "campaign";
  let title = "No announcements found";
  let desc = "There are no official broadcasts or announcements in this record.";
  let badgeLabel = "Official Broadcast";

  const tab = state.announcementTab || "all";
  if (search) {
    icon = "search_off";
    title = "No matching announcements";
    desc = `No posts matched "${search}". Check for spelling errors or try resetting your filters.`;
    badgeLabel = "Search Result";
  } else if (tab === "draft") {
    icon = "edit_note";
    title = "No draft announcements";
    desc = "Drafts you save while composing will be safely stored here for editing and publishing.";
    badgeLabel = "Drafts";
  } else if (tab === "scheduled") {
    icon = "event_upcoming";
    title = "No scheduled announcements";
    desc = "Announcements scheduled for later will appear here until their publish time arrives.";
    badgeLabel = "Scheduled";
  } else if (tab === "archived" || filter === "archived") {
    icon = "inventory_2";
    title = "No archived posts found";
    desc = "Concluded events and archived announcements will be safely stored here.";
    badgeLabel = "Past & Archived";
  } else if (filter === "event") {
    icon = "calendar_month";
    title = "No events or activities found";
    desc = "There are currently no community events, public schedules, or activities posted.";
    badgeLabel = "Events & Activities";
  } else if (filter === "advisory") {
    icon = "notifications_off";
    title = "No public advisories found";
    desc = "There are currently no urgent public notices, service advisories, or alerts.";
    badgeLabel = "Public Advisories";
  } else if (filter === "general") {
    icon = "article";
    title = "No community notices found";
    desc = "There are currently no general barangay notices or advisories published.";
    badgeLabel = "Community Notices";
  }

  const resetBtn = hasFilter
    ? `<button type="button" class="announcement-empty-btn announcement-empty-btn--secondary" onclick="window.clearAllAnnouncementFilters()"><span class="material-symbols-rounded">filter_alt_off</span><span>Clear search and filters</span></button>`
    : "";
  const createBtn = `<button type="button" class="announcement-empty-btn announcement-empty-btn--primary" onclick="window.openAnnouncementComposer()"><span class="material-symbols-rounded">add_circle</span><span>New Announcement</span></button>`;

  return `<tr><td colspan="6" class="announcement-table-empty">
    <div class="announcement-empty-state">
      <div class="announcement-empty-icon-box announcement-empty-icon-box--${escapeAttribute(filter)}">
        <span class="material-symbols-rounded">${icon}</span>
      </div>
      <span class="announcement-empty-badge">${escapeHtml(badgeLabel)}</span>
      <strong class="announcement-empty-title">${escapeHtml(title)}</strong>
      <p class="announcement-empty-desc">${escapeHtml(desc)}</p>
      <div class="announcement-empty-actions">
        ${resetBtn}
        ${createBtn}
      </div>
    </div>
  </td></tr>`;
}

window.clearAllAnnouncementFilters = () => {
  if (byId("announcementSearch")) byId("announcementSearch").value = "";
  if (byId("announcementPublisherFilter")) byId("announcementPublisherFilter").value = "all";
  if (byId("announcementSourceFilter")) byId("announcementSourceFilter").value = "all";
  if (byId("announcementPriorityFilter")) byId("announcementPriorityFilter").value = "all";
  if (byId("announcementSort")) byId("announcementSort").value = "newest";
  state.announcementTypeFilter = "all";
  state.announcementArchiveView = false;
  renderAnnouncements();
};

function renderAnnouncements() {
  if (!byId("announcementTable")) return;
  void checkScheduledAnnouncementsAutoPublish();
  const barangayManagement = isBarangayRole(state.currentProfile?.role);
  const isArchiveView = state.announcementArchiveView === true;
  const pagePosts = announcementPagePosts();
  const published = pagePosts.filter((item) => announcementUiStatus(item) === "published");
  const scheduled = pagePosts.filter((item) => announcementUiStatus(item) === "scheduled");
  const drafts = pagePosts.filter((item) => announcementUiStatus(item) === "draft");
  const archived = pagePosts.filter((item) => announcementUiStatus(item) === "archived");
  const activePosts = pagePosts.filter((item) => announcementUiStatus(item) !== "archived");
  const postTypeCounts = activePosts.reduce((counts, item) => {
    counts[announcementPostType(item)] += 1;
    return counts;
  }, { general: 0, event: 0, advisory: 0 });

  byId("announcementGeneralCount").textContent = formatNumber(postTypeCounts.general);
  byId("announcementEventCount").textContent = formatNumber(postTypeCounts.event);
  byId("announcementAdvisoryCount").textContent = formatNumber(postTypeCounts.advisory);
  byId("announcementTotalCount").textContent = formatNumber(activePosts.length);
  byId("announcementAllSummary").hidden = true;
  byId("barangayAnnouncementScope").hidden = true;
  byId("announcementSummaryPanel").classList.add("is-barangay-management");
  byId("announcementStatusFilters").hidden = false;
  byId("announcementPublisherFilterField").hidden = barangayManagement;
  byId("announcementSourceFilterField").hidden = !barangayManagement;
  byId("announcementAllImportanceOption").textContent = "All Importance";
  byId("clearAnnouncementFilters").textContent = "Clear Filter";
  byId("announcementSortNewestOption").textContent = "Newest First";
  byId("announcementSortOldestOption").textContent = "Oldest First";
  const updateAnnouncementBadge = (id, count) => {
    const el = byId(id);
    if (!el) return;
    el.textContent = formatNumber(count);
    const isZero = count === 0;
    el.hidden = isZero;
    el.classList.toggle("is-zero", isZero);
    el.style.display = isZero ? "none" : "";
  };
  updateAnnouncementBadge("tabBadgeAll", pagePosts.length);
  updateAnnouncementBadge("tabBadgeCurrent", published.length);
  updateAnnouncementBadge("tabBadgeScheduled", scheduled.length);
  updateAnnouncementBadge("tabBadgeDraft", drafts.length);
  updateAnnouncementBadge("tabBadgeArchive", archived.length);
  renderAnnouncementAudience();

  const search = normalize(byId("announcementSearch").value || globalSearch.value);
  const publisher = barangayManagement ? "all" : byId("announcementPublisherFilter").value;
  const source = barangayManagement ? byId("announcementSourceFilter").value : "all";
  const priority = byId("announcementPriorityFilter").value;
  const selectedTab = state.announcementTab || "current";
  let items = pagePosts
    .filter((item) => {
      const uiStatus = announcementUiStatus(item);
      if (selectedTab === "current") return uiStatus === "published";
      if (selectedTab === "scheduled") return uiStatus === "scheduled";
      if (selectedTab === "draft") return uiStatus === "draft";
      if (selectedTab === "archived") return uiStatus === "archived";
      return true; // "all"
    })
    .filter((item) => {
      if (state.announcementTypeFilter === "all") return true;
      return announcementPostType(item) === state.announcementTypeFilter;
    })
    .filter((item) => publisher === "all" || publisherGroup(item.authorRole) === publisher)
    .filter((item) => source === "all" || barangayAnnouncementSource(item) === source)
    .filter((item) => priority === "all" || normalize(item.priority) === priority)
    .filter((item) => !search || normalize([item.title, item.content, postPublisher(item), announcementDisplayCategory(item), coverageLabel(item)].join(" ")).includes(search));
  const sort = byId("announcementSort").value;
  const announcementDate = (item) => dateValue(item.publishAt || item.publishedAt || item.timestamp || item.createdAt);
  items = [...items].sort((a, b) => sort === "oldest" ? announcementDate(a) - announcementDate(b) : announcementDate(b) - announcementDate(a));

  if (byId("announcementSortControl")) byId("announcementSortControl").hidden = true;
  document.querySelectorAll("[data-announcement-summary]").forEach((button) => {
    const key = button.dataset.announcementSummary;
    const selected = key === state.announcementTypeFilter && !isArchiveView;
    button.classList.toggle("is-selected", selected);
    button.setAttribute("aria-pressed", String(selected));
  });
  byId("announcementTabs")?.querySelectorAll("[data-announcement-tab]").forEach((button) => {
    const isSelected = button.dataset.announcementTab === selectedTab;
    button.classList.toggle("active", isSelected);
    button.setAttribute("aria-selected", String(isSelected));
  });
  byId("barangayAnnouncementScope").querySelectorAll("[data-announcement-scope]").forEach((button) => {
    const selected = button.dataset.announcementScope === (isArchiveView ? "archived" : "active");
    button.classList.toggle("active", selected);
    button.setAttribute("aria-pressed", String(selected));
  });
  let filterCount = 0;
  if (priority !== "all") filterCount++;
  if (!barangayManagement && publisher !== "all") filterCount++;
  if (barangayManagement && source !== "all") filterCount++;
  if (state.announcementTypeFilter !== "all") filterCount++;
  if (byId("announcementSort") && byId("announcementSort").value !== "newest") filterCount++;

  const filterCountEl = byId("announcementFilterCount");
  if (filterCountEl) {
    filterCountEl.textContent = formatNumber(filterCount);
    filterCountEl.hidden = filterCount === 0;
    filterCountEl.style.display = filterCount === 0 ? "none" : "";
  }
  byId("announcementFilterButton")?.classList.toggle("has-filters", filterCount > 0);
  byId("announcementSearchClear").hidden = !byId("announcementSearch").value;
  const resultType = isArchiveView ? "archived" : state.announcementTypeFilter;
  const typeLabel = ({ general: "community notice", event: "event or activity", advisory: "public advisory", archived: "archived post" })[resultType] || "post";
  const pluralTypeLabel = ({ general: "community notices", event: "events or activities", advisory: "public advisories", archived: "archived posts" })[resultType] || "posts";
  byId("announcementResultSummary").textContent = `${formatNumber(items.length)} ${items.length === 1 ? typeLabel : pluralTypeLabel}`;
  byId("announcementLibraryPanel").classList.toggle("has-empty-results", items.length === 0);

  byId("announcementTable").innerHTML = items.length ? items.map((item) => {
    const status = announcementUiStatus(item);
    const expired = isAnnouncementExpired(item);
    const manageable = canManageAnnouncement(item);
    const canEdit = manageable && (["draft", "scheduled", "published"].includes(status) || expired);
    const menuItems = [
      canEdit ? `<button type="button" class="people-action-item" onclick="closeAnnouncementMenus();editAnnouncement('${safeId(item.id)}')"><span class="material-symbols-rounded action-icon action-icon--edit">edit_square</span><span class="action-label">${expired ? "Edit / Extend" : "Edit"}</span></button>` : "",
      manageable && status === "draft" ? `<button type="button" class="people-action-item" onclick="closeAnnouncementMenus();publishDraftNow('${safeId(item.id)}')"><span class="material-symbols-rounded action-icon action-icon--view">send</span><span class="action-label">Publish now</span></button>` : "",
      manageable && status === "scheduled" ? `<button type="button" class="people-action-item" onclick="closeAnnouncementMenus();publishDraftNow('${safeId(item.id)}')"><span class="material-symbols-rounded action-icon action-icon--view">send</span><span class="action-label">Publish immediately</span></button>` : "",
      manageable ? `<button type="button" class="people-action-item" onclick="closeAnnouncementMenus();duplicateAnnouncement('${safeId(item.id)}')"><span class="material-symbols-rounded action-icon action-icon--view">content_copy</span><span class="action-label">Duplicate / Repost</span></button>` : "",
      manageable ? `<button type="button" class="people-action-item people-action-item--danger" onclick="closeAnnouncementMenus();requestDeleteAnnouncement('${safeId(item.id)}')"><span class="material-symbols-rounded action-icon action-icon--delete">delete_forever</span><span class="action-label">Delete</span></button>` : "",
      manageable && status !== "archived" && !expired ? `<button type="button" class="people-action-item" onclick="closeAnnouncementMenus();archiveAnnouncement('${safeId(item.id)}')"><span class="material-symbols-rounded action-icon action-icon--restrict">inventory_2</span><span class="action-label">Archive</span></button>` : "",
      manageable && (status === "archived" || expired) ? `<button type="button" class="people-action-item" onclick="closeAnnouncementMenus();restoreAnnouncement('${safeId(item.id)}')"><span class="material-symbols-rounded action-icon action-icon--view">restore</span><span class="action-label">Restore as draft</span></button>` : "",
    ].filter(Boolean).join("");
    const title = item.title || "Untitled announcement";
    const icon = announcementListIcon(item);
    const themeClass = announcementThemeClass(icon);
    const actions = menuItems
      ? `<button class="people-row-action" type="button" aria-label="Actions for ${escapeAttribute(title)}" aria-haspopup="menu" onclick="toggleBarangayAnnouncementMenu(event,this)"><span class="material-symbols-rounded">more_horiz</span></button><template>${menuItems}</template>`
      : `<button class="table-action announcement-open-btn primary-btn-3d" type="button" onclick="openAnnouncement('${safeId(item.id)}')"><span class="material-symbols-rounded">visibility</span><span>View</span></button>`;
    const statusHtml = expired
      ? `<span class="status-pill status-pill--archived" style="display:inline-flex;align-items:center;gap:3px;" title="Event has concluded"><span class="material-symbols-rounded" style="font-size:14px;">event_available</span>Concluded</span>`
      : statusPill(status);
    return `<tr class="announcement-record-row" tabindex="0" role="button" aria-label="View full announcement: ${escapeAttribute(title)}" onclick="if (!event.target.closest('button, summary, details')) openAnnouncement('${safeId(item.id)}')" onkeydown="if ((event.key === 'Enter' || event.key === ' ') && !event.target.closest('button, summary, details')) { event.preventDefault(); openAnnouncement('${safeId(item.id)}'); }"><td><span class="announcement-table-title"><span class="announcement-table-title__icon ${themeClass} material-symbols-rounded">${icon}</span><span class="announcement-title-text">${escapeHtml(title)}</span></span></td><td><span class="announcement-recipient"><span class="material-symbols-rounded">${normalize(item.visibility) === "public" ? "public" : "groups"}</span>${escapeHtml(coverageLabel(item))}</span></td><td><span class="cell-title announcement-date">${formatDate(item.publishAt || item.publishedAt || item.timestamp || item.createdAt)}</span></td><td><span class="cell-title">${escapeHtml(postPublisher(item))}</span><span class="cell-subtitle">${escapeHtml(labelForRole(item.authorRole))}</span></td><td>${statusHtml}</td><td><div class="announcement-row-actions">${actions}</div></td></tr>`;
  }).join("") : announcementEmptyRow();
}

byId("announcementTabs").addEventListener("click", (event) => {
  const button = event.target.closest("[data-announcement-tab]");
  if (!button) return;
  state.announcementTab = button.dataset.announcementTab;
  renderAnnouncements();
});
document.querySelectorAll("[data-announcement-summary]").forEach((button) => button.addEventListener("click", () => {
  state.announcementArchiveView = false;
  state.announcementTypeFilter = button.dataset.announcementSummary;
  renderAnnouncements();
  byId("announcementLibraryPanel").scrollIntoView({ behavior: "smooth", block: "start" });
}));
byId("barangayAnnouncementScope").addEventListener("click", (event) => {
  const button = event.target.closest("[data-announcement-scope]");
  if (!button) return;
  state.announcementArchiveView = button.dataset.announcementScope === "archived";
  state.announcementTypeFilter = "all";
  renderAnnouncements();
});
const renderAnnouncementSearch = debounce(renderAnnouncements, 180);
["announcementSearch", "announcementPublisherFilter", "announcementSourceFilter", "announcementPriorityFilter", "announcementSort"].forEach((id) => byId(id).addEventListener(id === "announcementSearch" ? "input" : "change", id === "announcementSearch" ? renderAnnouncementSearch : renderAnnouncements));
byId("announcementSearchClear").addEventListener("click", () => {
  byId("announcementSearch").value = "";
  renderAnnouncements();
  byId("announcementSearch").focus();
});
byId("announcementFilterButton").addEventListener("click", () => {
  const menu = byId("announcementFilterMenu");
  menu.hidden = !menu.hidden;
  byId("announcementFilterButton").setAttribute("aria-expanded", String(!menu.hidden));
});
byId("clearAnnouncementFilters").addEventListener("click", () => {
  if (byId("announcementPublisherFilter")) byId("announcementPublisherFilter").value = "all";
  if (byId("announcementSourceFilter")) byId("announcementSourceFilter").value = "all";
  if (byId("announcementPriorityFilter")) byId("announcementPriorityFilter").value = "all";
  if (byId("announcementSort")) byId("announcementSort").value = "newest";
  state.announcementTypeFilter = "all";
  renderAnnouncements();
});
let activeBarangayAnnouncementMenu = null;
function closeBarangayAnnouncementMenus() {
  if (!activeBarangayAnnouncementMenu) return;
  activeBarangayAnnouncementMenu.button.setAttribute("aria-expanded", "false");
  activeBarangayAnnouncementMenu.menu.remove();
  activeBarangayAnnouncementMenu = null;
}

window.toggleBarangayAnnouncementMenu = (event, button) => {
  event.stopPropagation();
  event.preventDefault();
  if (activeBarangayAnnouncementMenu?.button === button) {
    closeBarangayAnnouncementMenus();
    return;
  }
  closeBarangayAnnouncementMenus();
  const template = button.nextElementSibling;
  if (!template?.content) return;
  const menu = document.createElement("div");
  menu.className = "people-action-menu announcement-floating-menu";
  menu.setAttribute("role", "menu");
  menu.append(template.content.cloneNode(true));
  document.body.append(menu);
  const anchor = button.getBoundingClientRect();
  const width = menu.offsetWidth || 160;
  const height = menu.offsetHeight || 120;
  menu.style.position = "fixed";
  menu.style.zIndex = "9999";
  menu.style.left = `${Math.max(8, Math.min(anchor.right - width, window.innerWidth - width - 8))}px`;
  menu.style.top = `${anchor.bottom + height + 8 <= window.innerHeight ? anchor.bottom + 6 : Math.max(8, anchor.top - height - 6)}px`;
  button.setAttribute("aria-expanded", "true");
  activeBarangayAnnouncementMenu = { menu, button, openedAt: Date.now() };
};

document.addEventListener("scroll", (event) => {
  if (!activeBarangayAnnouncementMenu) return;
  if (Date.now() - (activeBarangayAnnouncementMenu.openedAt || 0) < 300) return;
  closeBarangayAnnouncementMenus();
}, true);
window.addEventListener("resize", closeBarangayAnnouncementMenus);
document.addEventListener("click", (event) => {
  if (activeBarangayAnnouncementMenu) {
    const isToggleButton = event.target === activeBarangayAnnouncementMenu.button || activeBarangayAnnouncementMenu.button.contains(event.target);
    const isInsideMenu = activeBarangayAnnouncementMenu.menu.contains(event.target);
    if (!isToggleButton && (!isInsideMenu || event.target.closest("button, a"))) {
      closeBarangayAnnouncementMenus();
    }
  }
  if (event.target.closest(".announcement-filter-wrap")) return;
  const menu = byId("announcementFilterMenu");
  if (menu && !menu.hidden) {
    menu.hidden = true;
    byId("announcementFilterButton").setAttribute("aria-expanded", "false");
  }
  document.querySelectorAll(".announcement-row-actions details[open]").forEach((details) => {
    if (!details.contains(event.target)) details.removeAttribute("open");
  });
});

function localDateTimeValue(value) {
  const timestamp = dateValue(value);
  if (!timestamp) return "";
  const date = new Date(timestamp - new Date(timestamp).getTimezoneOffset() * 60000);
  return date.toISOString().slice(0, 16);
}

window.openAnnouncement = (id) => {
  const item = findAnnouncementById(id);
  if (!item) return;
  const status = announcementUiStatus(item);
  const expired = isAnnouncementExpired(item);
  const imageUrl = trustedMediaUrl(item.imageUrl);
  const role = canonicalRole(item.authorRole || "lgu");
  const isBarangay = isBarangayRole(role) || canonicalRole(item.authorRole) === "barangay";
  const publisherName = postPublisher(item);
  const authorRoleLabel = labelForRole(item.authorRole);
  const postDate = formatDate(item.publishAt || item.publishedAt || item.timestamp || item.createdAt);

  // Status indicator
  let statusPillHtml = "";
  if (expired) {
    statusPillHtml = `<span class="preview-status-indicator scheduled"><span class="material-symbols-rounded">event_available</span>Concluded</span>`;
  } else if (status === "published") {
    statusPillHtml = `<span class="preview-status-indicator live"><span class="pulse-ring"></span>Published</span>`;
  } else if (status === "scheduled") {
    statusPillHtml = `<span class="preview-status-indicator scheduled"><span class="material-symbols-rounded">schedule</span>Scheduled: ${formatDate(item.publishAt)}</span>`;
  } else if (status === "draft") {
    statusPillHtml = `<span class="preview-status-indicator scheduled"><span class="material-symbols-rounded">edit_note</span>Draft</span>`;
  } else if (status === "archived") {
    statusPillHtml = `<span class="preview-status-indicator scheduled"><span class="material-symbols-rounded">inventory_2</span>Archived</span>`;
  } else {
    statusPillHtml = statusPill(status);
  }

  // Priority badge (only if urgent or important)
  let priorityBadge = "";
  if (item.priority === "urgent") {
    priorityBadge = `<span class="preview-badge-3d preview-badge-3d--urgent"><span class="material-symbols-rounded">emergency</span>Urgent</span>`;
  } else if (item.priority === "important") {
    priorityBadge = `<span class="preview-badge-3d preview-badge-3d--important"><span class="material-symbols-rounded">priority_high</span>Important</span>`;
  }

  // Attached image thumbnail: neat contained frame matching upload thumbnail
  const bannerHtml = imageUrl
    ? `<div class="modal-photo-display">
         <div class="modal-photo-frame" title="Click to view full image" onclick="window.open('${escapeAttribute(imageUrl)}', '_blank')">
           <img src="${escapeAttribute(imageUrl)}" alt="${escapeAttribute(item.title || "Announcement")}" class="modal-photo-thumb">
         </div>
       </div>`
    : "";

  // Calendar block (if event)
  let calendarHtml = "";
  const eventStart = item.eventStartAt || item.eventDate ? dateValue(item.eventStartAt || item.eventDate) : null;
  if (item.addToCalendar !== false && eventStart) {
    const startDate = new Date(eventStart);
    const monthNames = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    const calMonth = monthNames[startDate.getMonth()] || "Event";
    const calDay = startDate.getDate() || "";
    const eventTimeStr = item.eventAllDay !== false
      ? "All-day event"
      : `${formatDate(startDate)}${item.eventEndAt ? ` - ${formatDate(item.eventEndAt)}` : ""}`;
    calendarHtml = `
      <div class="preview-calendar-tile">
        <div class="preview-cal-sheet">
          <div class="preview-cal-header">${calMonth}</div>
          <div class="preview-cal-num">${calDay}</div>
        </div>
        <div class="preview-cal-details">
          <div class="preview-cal-title">${escapeHtml(item.title || "Event")}</div>
          <div class="preview-cal-meta">
            <span><span class="material-symbols-rounded">schedule</span>${escapeHtml(eventTimeStr)}</span>
            ${item.eventLocation ? `<span><span class="material-symbols-rounded">place</span>${escapeHtml(item.eventLocation)}</span>` : ""}
          </div>
        </div>
      </div>
    `;
  }

  // Action link if CTA exists
  let ctaHtml = "";
  if (item.cta?.url) {
    ctaHtml = `
      <div class="preview-cta-row">
        <a href="${escapeAttribute(item.cta.url)}" target="_blank" rel="noopener noreferrer" class="preview-cta-button">
          <span>${escapeHtml(item.cta.label || "Learn more")}</span>
          <span class="material-symbols-rounded">arrow_forward</span>
        </a>
      </div>
    `;
  }

  // Concluded event notice banner
  const eventBanner = expired
    ? `<div class="alert-box alert-box--info" style="margin-bottom:14px;display:flex;align-items:center;gap:10px;padding:10px 14px;border-radius:10px;background:light-dark(rgba(7,56,38,0.06), color-mix(in srgb, var(--brandStrong) 6%, transparent));border:1px solid light-dark(rgba(7,56,38,0.15), color-mix(in srgb, var(--successBorder) 15%, transparent));"><span class="material-symbols-rounded" style="color:light-dark(#073826, var(--textPrimary));">event_available</span><span style="font-size:13px;color:light-dark(#073826, var(--textPrimary));"><strong>Concluded Event:</strong> This event concluded on ${formatDate(item.eventEndAt || item.eventStartAt || item.eventDate)}. It is preserved here in Past & Archived records.</span></div>`
    : "";

  const moderatorNote = status === "pending_review"
    ? `<label class="field detail-item full" style="margin-top:14px;"><span>Moderator note / rejection reason</span><textarea id="postReviewReason" rows="3" maxlength="600"></textarea></label>`
    : "";

  const body = `
    ${eventBanner}
    <div class="preview-feed-container">
      <article class="preview-feed-card">
        <!-- Authority Header -->
        <header class="preview-card-authority">
          <div class="preview-author-group">
            <div class="preview-author-crest">
              <span class="material-symbols-rounded">${role === "super_admin" ? "computer" : isBarangay ? "location_city" : "account_balance"}</span>
            </div>
            <div class="preview-author-text">
              <div class="preview-author-name">
                <span>${escapeHtml(publisherName)}</span>
                <span class="material-symbols-rounded preview-verified-icon" title="Verified Publisher">verified</span>
              </div>
              <div class="preview-author-sub">
                <span>${escapeHtml(authorRoleLabel)}</span>
                <span>•</span>
                <span>${escapeHtml(postDate)}</span>
              </div>
            </div>
          </div>
          ${statusPillHtml}
        </header>

        <!-- Banner Image (if any) -->
        ${bannerHtml}

        <!-- Tags Row -->
        <div class="preview-tags-row">
          ${priorityBadge}
          <span class="preview-badge-3d preview-badge-3d--category">
            <span class="material-symbols-rounded">category</span>
            ${escapeHtml(announcementDisplayCategory(item))}
          </span>
          <span class="preview-badge-3d preview-badge-3d--audience">
            <span class="material-symbols-rounded">${normalize(item.visibility) === "public" ? "public" : "pin_drop"}</span>
            ${escapeHtml(coverageLabel(item))}
          </span>
        </div>

        <!-- Content Body -->
        <div class="preview-card-body">
          <h3 class="preview-headline">${escapeHtml(item.title || "Untitled announcement")}</h3>
          <div class="preview-description">${escapeHtml(item.content || "No message content provided.").replace(/\n/g, "<br>")}</div>
          ${calendarHtml}
          ${ctaHtml}
        </div>
      </article>
      ${moderatorNote}
    </div>
  `;

  let actions = "";
  if (status === "pending_review" && isLguAdmin()) {
    actions = `
      <div class="preview-action-left">
        <span class="preview-notice"><span class="material-symbols-rounded">campaign</span> Official announcement</span>
      </div>
      <div class="preview-action-buttons">
        <button class="button button--secondary" type="button" onclick="reviewPost('${safeId(id)}','rejected')">Reject</button>
        <button class="button button--primary" type="button" onclick="reviewPost('${safeId(id)}','approved')">Approve & publish</button>
      </div>
    `;
  }

  openModal("Announcement Details", item.title || "Untitled announcement", body, actions, "modal-card--announcement-preview");
  modal.querySelector(".modal-card")?.classList.add("modal-card--announcement-preview");
};

window.editAnnouncement = (id) => {
  const item = findAnnouncementById(id);
  if (!item || !canManageAnnouncement(item)) { showToast("You can only edit announcements managed by your account.", true); return; }
  closeModal();
  closeBarangayAnnouncementMenus();
  byId("announcementComposerPanel").hidden = false;
  byId("announcementLibraryPanel").hidden = true;
  byId("announcementCommandBar").hidden = true;
  byId("announcementSummaryPanel").hidden = true;
  setAnnouncementStep(1);
  state.editingAnnouncementId = id;
  byId("announcementImage").value = "";
  byId("announcementComposerTitle").textContent = "Edit announcement";
  byId("announcementDeliveryStep").textContent = "When to Publish";
  byId("cancelAnnouncementEdit").hidden = false;
  byId("cancelAnnouncementEdit").innerHTML = '<span class="material-symbols-rounded">close</span>Cancel editing';
  byId("announcementTitle").value = item.title || "";
  byId("announcementMessage").value = item.content || "";
  byId("announcementMessageCount").textContent = String((item.content || "").length);
  if (byId("announcementCtaLabel")) byId("announcementCtaLabel").value = item.cta?.label || "";
  if (byId("announcementCtaUrl")) byId("announcementCtaUrl").value = item.cta?.url || "";
  byId("announcementExpiresAt").value = localDateTimeValue(item.expiresAt || item.priorityExpiresAt);
  byId("announcementNotify").checked = announcementUiStatus(item) !== "published" && item.notificationRequested === true;
  byId("announcementAddToCalendar").checked = item.addToCalendar !== false && !!item.eventStartAt;
  byId("announcementType").value = item.announcementType === "scheduled_activity" ? "event" : item.announcementType || "general";
  updateAnnouncementCategories(item.category);
  byId("announcementCustomCategory").value = item.customCategory || "";
  updateAnnouncementCustomCategoryField();
  byId("announcementEventAllDay").checked = item.eventAllDay === true || (!item.eventEndAt && !!item.eventStartAt);
  updateAnnouncementScheduleFields();
  byId("announcementEventStartAt").value = byId("announcementEventAllDay").checked ? localDateTimeValue(item.eventStartAt).slice(0, 10) : localDateTimeValue(item.eventStartAt);
  byId("announcementEventEndAt").value = localDateTimeValue(item.eventEndAt);
  byId("announcementEventLocation").value = item.eventLocation || "";
  const role = canonicalRole(state.currentProfile?.role || "lgu");
  const isBarangay = isBarangayRole(role) || isBarangayRole(item.authorRole) || canonicalRole(item.authorRole) === "barangay";
  const userBarangay = isBarangayRole(role) ? state.currentProfile?.barangay || ""
    : canonicalBarangay(item.targetBarangays?.[0] || item.targetBarangay || item.authorBarangay);
  if (isBarangay) {
    state.selectedAnnouncementBarangays = new Set([userBarangay].filter(Boolean));
    state.announcementAudience = "targeted";
    byId("announcementAudienceChoices").hidden = true;
    byId("barangayPicker").hidden = true;
    if (byId("barangayAudienceNotice")) {
      byId("barangayAudienceNotice").hidden = false;
      byId("barangayAudienceNotice").querySelector(".aud-notice-desc").textContent = isBarangayRole(role)
        ? "Only residents in your registered barangay will receive this announcement."
        : "This announcement remains limited to its original barangay.";
      if (byId("barangayAudienceTitle")) {
        byId("barangayAudienceTitle").textContent = userBarangay ? `Barangay ${userBarangay}` : "Assigned Barangay";
      }
    }
  } else {
    state.selectedAnnouncementBarangays = new Set((item.targetBarangays || []).map(canonicalBarangay).filter(Boolean));
    setAnnouncementAudience(normalize(item.visibility) === "public" || item.targetBarangay === "All Barangays" ? "municipality" : "targeted");
    byId("announcementAudienceChoices").hidden = false;
    byId("audienceAll").hidden = !organizationCanPublishMunicipalityWide();
    byId("audienceTargeted").disabled = false;
    if (byId("barangayAudienceNotice")) {
      byId("barangayAudienceNotice").hidden = true;
    }
  }
  renderAnnouncementAudience();
  setAnnouncementPriority(["regular", "important", "urgent"].includes(normalize(item.priority)) ? normalize(item.priority) : "regular");
  const itemStatus = announcementUiStatus(item);
  const scheduled = itemStatus === "scheduled";
  setAnnouncementDelivery(scheduled ? "scheduled" : "now");
  byId("announcementWhenToPublish").hidden = itemStatus === "published";
  byId("scheduleAnnouncement").hidden = false;
  if (byId("publishAnnouncement")) {
    byId("publishAnnouncement").innerHTML = '<span class="material-symbols-rounded" aria-hidden="true">save</span>Save changes';
    byId("publishAnnouncement").setAttribute("aria-label", "Save changes");
  }
  if (byId("saveAnnouncementDraft")) {
    if (itemStatus === "draft") {
      byId("saveAnnouncementDraft").hidden = false;
      byId("saveAnnouncementDraft").innerHTML = '<span class="material-symbols-rounded">send</span>Publish now';
    } else {
      byId("saveAnnouncementDraft").hidden = true;
    }
  }
  byId("announcementPublishAt").value = scheduled ? localDateTimeValue(item.publishAt) : "";
  item._removeImage = false;
  if (item.imageUrl) {
    setAnnouncementImagePreview(item.imageUrl, "Current announcement banner", "Existing banner will be kept unless replaced");
  } else {
    clearAnnouncementImage();
  }
  syncDateTimeDisplays();
  byId("announcementForm").scrollIntoView({ behavior: "smooth", block: "start" });
};

window.duplicateAnnouncement = (id) => {
  const item = findAnnouncementById(id) || state.posts.find((post) => post.id === id);
  if (!item || !canManageAnnouncement(item)) { showToast("You can only duplicate announcements managed by your account.", true); return; }
  window.editAnnouncement(id);
  if (state.editingAnnouncementId !== id) return;
  state.editingAnnouncementId = null;
  byId("announcementComposerTitle").textContent = "Duplicate announcement";
  byId("announcementDeliveryStep").textContent = "When to Publish";
  byId("announcementWhenToPublish").hidden = false;
  setAnnouncementDelivery("now");
  byId("announcementTitle").value = `Copy of ${item.title || "Untitled announcement"}`.slice(0, 120);
  byId("cancelAnnouncementEdit").hidden = true;
  byId("saveAnnouncementDraft").hidden = false;
  byId("saveAnnouncementDraft").innerHTML = '<span class="material-symbols-rounded">bookmark</span>Save draft';
  byId("publishAnnouncement").innerHTML = '<span class="material-symbols-rounded">send</span>Send announcement';
  byId("publishAnnouncement").setAttribute("aria-label", "Send announcement");
  clearAnnouncementImage();
  showToast("A copy is ready. Review it before saving or sending.");
};

window.publishAnnouncementNow = async (id) => {
  const item = findAnnouncementById(id) || state.posts.find((post) => post.id === id);
  if (!item) return;
  if (!canManageAnnouncement(item)) {
    showToast("You can only publish announcements managed by your account.", true);
    return;
  }
  try {
    if (!["draft", "scheduled"].includes(announcementUiStatus(item))) {
      throw new Error("Only draft or scheduled announcements can be published now.");
    }
    if (!String(item.title || "").trim() || !String(item.content || "").trim()) {
      throw new Error("Add a title and message before publishing this announcement.");
    }
    if (["event", "scheduled_activity"].includes(String(item.announcementType || "").toLowerCase()) && !item.eventStartAt) {
      throw new Error("Add the event date before publishing this announcement.");
    }
    if (isAnnouncementExpired({ ...item, status: "approved" })) {
      throw new Error("Update the expired event dates before publishing this announcement.");
    }
    const postRef = doc(db, "posts", id);
    const updatePayload = { status: "approved", publishAt: null, notificationRequested: true, revision: Number(item.revision || 0) + 1, updatedAt: serverTimestamp() };
    const role = canonicalRole(state.currentProfile?.role);
    if (item.authorId === auth.currentUser?.uid || ["super_admin", "lgu"].includes(role)) {
      updatePayload.publishedAt = serverTimestamp();
    } else {
      // Shared barangay/organization edits permit publishAt, but not publishedAt.
      updatePayload.publishAt = serverTimestamp();
    }
    try {
      const batch = writeBatch(db);
      batch.update(postRef, updatePayload);
      addAuditToBatch(batch, "announcement_published", "post", id, { sourceStatus: announcementUiStatus(item) });
      await batch.commit();
    } catch (batchErr) {
      await updateDoc(postRef, updatePayload);
    }
    closeModal();
    state.announcementTab = "current";
    state.announcementArchiveView = false;
    renderAnnouncements();
    showToast("Announcement published.");
  } catch (error) { showToast(`Announcement could not be published: ${callableErrorMessage(error)}`, true); }
};
window.publishDraftNow = window.publishAnnouncementNow;

