window.deleteAnnouncement = async (id, button) => {
  if (button?.disabled) return;
  const item = findAnnouncementById(id);
  if (!item || !canManageAnnouncement(item)) {
    showToast("You can only delete announcements managed by your account.", true);
    return;
  }
  setButtonBusy(button, true, "Deleting...");
  try {
    const postRef = doc(db, "posts", id);
    try {
      const batch = writeBatch(db);
      batch.delete(postRef);
      addAuditToBatch(batch, "announcement_deleted", "post", id, { publisherRole: canonicalRole(state.currentProfile?.role) });
      await batch.commit();
    } catch (batchErr) {
      await deleteDoc(postRef);
    }
    closeModal();
    showToast("Announcement deleted.");
  } catch (error) {
    showToast(`Announcement could not be deleted: ${callableErrorMessage(error)}`, true);
    setButtonBusy(button, false);
  }
};

