  const organizations = mergeById(derived, state.organizations);
  byId("organizationList").innerHTML = organizations.length ? organizations.map((item) => `<article class="list-card"><div class="priority-meta">${statusPill(normalize(item.status || "pending"))}</div><h3>${escapeHtml(item.name || "Unnamed organization")}</h3><p>${formatNumber(state.posts.filter((post) => post.publisherEntityId === item.id || post.authorId === item.primaryAdminId).length)} published posts</p></article>`).join("") : '<div class="empty-state">No organizations.</div>';
