function renderDashboardAnalytics() {
  if (state.page !== "dashboard") return;
  const role = canonicalRole(state.currentProfile?.role);
  const barangayDashboard = isBarangayRole(role) || Boolean(state.currentProfile?.barangay && String(role).includes("barangay"));
  const municipalOverview = byId("municipalDashboardOverview");
  const barangayAnalytics = byId("barangayDashboardAnalytics");
  const analyticsGrid = document.querySelector(".dashboard-analytics-grid");
  const orgAnalytics = byId("organizationDashboardAnalytics");
  if (orgAnalytics) orgAnalytics.hidden = true;

  if (municipalOverview) municipalOverview.hidden = barangayDashboard;
  if (barangayAnalytics) barangayAnalytics.hidden = !barangayDashboard;
  analyticsGrid?.classList.toggle("is-barangay", barangayDashboard);

  // Dynamic overview title based on department / role
  const titleEl = byId("overviewAnalyticsTitle");
  if (titleEl) {
    if (role === "lgu") {
      const deptName = currentStaffDepartmentName();
      titleEl.textContent = `${deptName} Analytics`;
    } else if (role === "organization") {
      const orgName = state.currentProfile?.organizationName || "Organization";
      titleEl.textContent = `${orgName} Analytics`;
    } else {
      titleEl.textContent = "BARILI ANALYTICS";
    }
  }

  if (barangayDashboard) {
    renderBarangayAnalyticsChart();
    return;
  }
  renderCommunityActivityChart();
  renderOverviewAnalyticsChart();
}

function barangayAnalyticsBuckets(mode) {
  const today = philippineDateParts(new Date());
  if (!today) return [];
  const anchor = Date.UTC(today.year, today.month - 1, today.day);
  const dailyCount = mode === "30d" ? 30 : mode === "7d" ? 7 : 0;
  if (dailyCount) {
    return Array.from({ length: dailyCount }, (_, index) => {
      const date = new Date(anchor - (dailyCount - index - 1) * 86400000);
      const key = `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, "0")}-${String(date.getUTCDate()).padStart(2, "0")}`;
      const label = new Intl.DateTimeFormat("en-PH", {
        timeZone: "UTC",
        ...(mode === "7d" ? { weekday: "short" } : { month: "short", day: "numeric" })
      }).format(date);
      return { key, label };
    });
  }

  const monthCount = mode === "12m" ? 12 : 6;
  return Array.from({ length: monthCount }, (_, index) => {
    const offset = monthCount - index - 1;
    const date = new Date(Date.UTC(today.year, today.month - 1 - offset, 1));
    return {
      key: `${date.getUTCFullYear()}-${String(date.getUTCMonth() + 1).padStart(2, "0")}`,
      label: new Intl.DateTimeFormat("en-PH", { timeZone: "UTC", month: "short" }).format(date)
    };
  });
}

function concernResolvedDate(item) {
  if (item.resolvedAt) return item.resolvedAt;
  const history = Array.isArray(item.statusHistory) ? [...item.statusHistory].reverse() : [];
  const resolution = history.find((entry) => concernStatus(entry) === "resolved");
  if (resolution) return resolution.date || resolution.createdAt || resolution.updatedAt;
  return concernStatus(item) === "resolved" ? item.updatedAt : null;
}

function isComplaintResolved(item) {
  return item.closureOutcome === "settled" || (!item.closureOutcome && ["resolved", "settled"].includes(complaintWorkflowStatus(item)));
}

function complaintResolvedDate(item) {
  if (item.settledAt) return item.settledAt;
  if (item.resolvedAt) return item.resolvedAt;
  if (item.closedAt) return item.closedAt;
  if (item.unsettledAt) return item.unsettledAt;
  const history = Array.isArray(item.statusHistory) ? [...item.statusHistory].reverse() : [];
  const resolution = history.find((entry) => {
    const st = String(entry.status || entry.action || "").toLowerCase();
    return st === "resolved" || st === "closed" || st === "settled" || st === "unsettled" || st === "referred";
  });
  if (resolution) return resolution.date || resolution.createdAt || resolution.updatedAt;
  if (isComplaintResolved(item)) return item.updatedAt || item.date || item.createdAt;
  return null;
}

function countBarangayAnalyticsSeries(items, dateForItem, buckets, mode) {
  const indexes = new Map(buckets.map((bucket, index) => [bucket.key, index]));
  const values = new Array(buckets.length).fill(0);
  items.forEach((item) => {
    const value = dateForItem(item);
    const key = mode === "7d" || mode === "30d" ? philippineDateKey(value) : philippineMonthKey(value);
    const index = indexes.get(key);
    if (index !== undefined) values[index] += 1;
  });
  return values;
}

function barangayAnalyticsGroups(tab, barangayId) {
  const exactScope = (item) => String(item?.barangayId || "").trim() === barangayId;
  if (tab === "complaints" || tab === "complaint") {
    const complaints = (state.complaints || []).filter((item) => exactScope(item) || (!item.barangayId && isItemInMyBarangay(item)));
    return [
      { label: "Received", color: "#087454", items: complaints, date: (item) => item.createdAt || item.date || item.filedAt },
      { label: "Resolved", color: "#e29a18", items: complaints.filter(isComplaintResolved), date: complaintResolvedDate }
    ];
  }
  if (tab === "residents") {
    const residents = state.residentVerifications.filter(exactScope);
    return [
      { label: "Verification Requests", color: "#087454", items: residents, date: (item) => item.submittedAt || item.verificationData?.submittedAt },
      { label: "Verified Residents", color: "#2f80c4", items: residents.filter((item) => verificationStatus(item) === "verified"), date: (item) => item.verifiedAt || item.reviewedAt }
    ];
  }
  if (tab === "announcements") {
    const announcements = state.barangayAnalyticsPosts.filter((item) => exactScope(item) && announcementUiStatus(item) === "published");
    return [
      { label: "Published Announcements", color: "#0a8a68", items: announcements, date: (item) => item.publishedAt || item.timestamp || item.createdAt }
    ];
  }
  if (tab === "emergencies") {
    return [
      { label: "Alerts Issued", color: "#d55252", items: state.barangayAnalyticsAlerts.filter(exactScope), date: (item) => item.publishedAt || item.createdAt }
    ];
  }
  const concerns = state.concerns.filter(exactScope);
  return [
    { label: "Received", color: "#087454", items: concerns, date: (item) => item.createdAt || item.date },
    { label: "Resolved", color: "#e29a18", items: concerns.filter((item) => concernStatus(item) === "resolved"), date: concernResolvedDate }
  ];
}

function renderBarangayAnalyticsLegend(chartId, datasets) {
  const legend = byId("barangayAnalyticsLegend");
  if (!legend) return;
  legend.innerHTML = datasets.map((dataset, index) => `<button class="legend-item 3d-legend-btn" type="button" data-barangay-series="${index}" aria-pressed="true"><i class="dot 3d-dot" style="background:${themeSeriesCssColor(dataset.color)}; box-shadow: 0 2px 6px ${dataset.color}55;"></i><span>${escapeHtml(dataset.label)}</span></button>`).join("");
  legend.querySelectorAll("[data-barangay-series]").forEach((button) => {
    button.addEventListener("click", () => {
      const chart = state.charts[chartId];
      const index = Number(button.dataset.barangaySeries);
      if (!chart || !Number.isInteger(index)) return;
      chart.setDatasetVisibility(index, !chart.isDatasetVisible(index));
      button.classList.toggle("hidden", !chart.isDatasetVisible(index));
      button.setAttribute("aria-pressed", String(chart.isDatasetVisible(index)));
      chart.update();
    });
  });
}

function adjustColor(hex, amount) {
  if (!hex || typeof hex !== "string" || !hex.startsWith("#")) return hex;
  let col = hex.replace("#", "");
  if (col.length === 3) col = col.split("").map((c) => c + c).join("");
  const num = parseInt(col, 16);
  if (Number.isNaN(num)) return hex;
  let r = (num >> 16) + amount;
  let g = ((num >> 8) & 0x00ff) + amount;
  let b = (num & 0x0000ff) + amount;
  r = Math.min(255, Math.max(0, r));
  g = Math.min(255, Math.max(0, g));
  b = Math.min(255, Math.max(0, b));
  return `rgb(${r}, ${g}, ${b})`;
}

function hexToRgba(hex, alpha = 1) {
  if (!hex || typeof hex !== "string" || !hex.startsWith("#")) return hex;
  let col = hex.replace("#", "");
  if (col.length === 3) col = col.split("").map((c) => c + c).join("");
  const num = parseInt(col, 16);
  if (Number.isNaN(num)) return hex;
  const r = (num >> 16) & 255;
  const g = (num >> 8) & 255;
  const b = num & 255;
  return `rgba(${r}, ${g}, ${b}, ${alpha})`;
}

function renderBarangayAnalyticsChart() {
  const chartId = "barangayAnalyticsChart";
  const canvas = byId(chartId);
  if (!window.Chart || !canvas) return;
  const barangayId = String(state.currentProfile?.barangayId || "").trim();
  const mode = byId("barangayAnalyticsRange")?.value || "7d";
  const tab = state.barangayAnalyticsTab || "concerns";
  document.querySelectorAll("[data-barangay-analytics-tab]").forEach((item) => {
    const active = item.dataset.barangayAnalyticsTab === tab || (tab === "complaint" && item.dataset.barangayAnalyticsTab === "complaints");
    item.classList.toggle("active", active);
    item.setAttribute("aria-selected", String(active));
  });
  const chartType = state.barangayAnalyticsChartType || "wave";
  const buckets = barangayAnalyticsBuckets(mode);
  const groups = barangayAnalyticsGroups(tab, barangayId);
  const datasets = groups.map((group) => ({
    label: group.label,
    color: group.color,
    data: barangayId ? countBarangayAnalyticsSeries(group.items, group.date, buckets, mode) : new Array(buckets.length).fill(0)
  }));
  const hasActivity = datasets.some((dataset) => dataset.data.some((value) => value > 0));
  const empty = byId("barangayAnalyticsEmpty");
  if (empty) empty.hidden = hasActivity;
  canvas.setAttribute("aria-label", `${titleCase(tab)} activity for ${currentStaffBarangay() || "the assigned barangay"}, ${mode}`);
  renderBarangayAnalyticsLegend(chartId, datasets);

  state.charts[chartId]?.destroy();

  const ctx = canvas.getContext("2d");
  const isWave = chartType === "wave";

  const chartDatasets = datasets.map((dataset) => {
    const baseColor = dataset.color || "#059669";
    if (isWave) {
      // 3D Volumetric Wave Fill Gradient
      const waveGradient = ctx.createLinearGradient(0, 0, 0, 310);
      waveGradient.addColorStop(0, hexToRgba(baseColor, 0.52));
      waveGradient.addColorStop(0.28, hexToRgba(baseColor, 0.25));
      waveGradient.addColorStop(0.70, hexToRgba(baseColor, 0.07));
      waveGradient.addColorStop(1, "rgba(255, 255, 255, 0)");

      return {
        type: "line",
        label: dataset.label,
        data: dataset.data,
        borderColor: baseColor,
        backgroundColor: waveGradient,
        fill: true,
        tension: 0.44,
        borderWidth: 3.5,
        pointRadius: 5,
        pointHoverRadius: 8,
        pointBackgroundColor: "#ffffff",
        pointBorderColor: baseColor,
        pointBorderWidth: 3,
        pointHoverBorderWidth: 4
      };
    }

    // 3D Volumetric Pillars Gradient with illuminated top cap and deep ground contour
    const pillarGradient = ctx.createLinearGradient(0, 0, 0, 290);
    pillarGradient.addColorStop(0, adjustColor(baseColor, 36));
    pillarGradient.addColorStop(0.16, adjustColor(baseColor, 18));
    pillarGradient.addColorStop(0.60, baseColor);
    pillarGradient.addColorStop(1, adjustColor(baseColor, -28));

    return {
      type: "bar",
      label: dataset.label,
      data: dataset.data,
      backgroundColor: pillarGradient,
      borderColor: adjustColor(baseColor, -20),
      borderWidth: 0,
      borderRadius: 14,
      borderSkipped: false,
      maxBarThickness: 34,
      categoryPercentage: datasets.length > 1 ? 0.72 : 0.58,
      barPercentage: 0.84
    };
  });

  state.charts[chartId] = new Chart(ctx, {
    type: isWave ? "line" : "bar",
    data: {
      labels: buckets.map((bucket) => bucket.label),
      datasets: chartDatasets
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      interaction: { mode: "index", intersect: false },
      animation: {
        duration: 550,
        easing: "easeOutQuart"
      },
      plugins: {
        legend: { display: false },
        tooltip: {
          backgroundColor: "rgba(7, 36, 27, 0.94)",
          borderColor: "rgba(255, 255, 255, 0.18)",
          borderWidth: 1,
          padding: 13,
          cornerRadius: 13,
          titleFont: { family: "'Outfit', 'Manrope', sans-serif", size: 13.5, weight: "700" },
          bodyFont: { family: "'Manrope', sans-serif", size: 12.5, weight: "600" },
          boxPadding: 6,
          usePointStyle: true,
          callbacks: {
            labelPointStyle: () => ({ pointStyle: "circle", rotation: 0 })
          }
        }
      },
      scales: {
        y: {
          beginAtZero: true,
          grid: {
            color: "rgba(205, 226, 217, 0.45)",
            drawTicks: false
          },
          border: { display: false, dash: [4, 4] },
          ticks: {
            precision: 0,
            stepSize: 1,
            font: { family: "'Outfit', 'Manrope', sans-serif", size: 11, weight: "700" },
            color: "#687d74",
            padding: 8
          }
        },
        x: {
          grid: { display: false },
          border: { display: false },
          ticks: {
            autoSkip: true,
            maxTicksLimit: mode === "30d" ? 10 : 12,
            maxRotation: 0,
            font: { family: "'Outfit', 'Manrope', sans-serif", size: 11.5, weight: "700" },
            color: "#687d74",
            padding: 8
          }
        }
      }
    }
  });
}


function matchesAdminAnalyticsBarangay(item, targetBarangay) {
  if (!targetBarangay || targetBarangay === "all") return true;
  const itemBgy = String(item?.barangay || item?.targetBarangay || concernBarangay(item) || "").trim();
  if (itemBgy.toLowerCase() === targetBarangay.toLowerCase()) return true;
  const targetId = barangayIdFor(targetBarangay);
  if (String(item?.barangayId || "").trim() === targetId) return true;
  if (Array.isArray(item?.targetBarangays) && item.targetBarangays.some((b) => String(b).toLowerCase() === targetBarangay.toLowerCase() || String(b) === targetId)) {
    return true;
  }
  return false;
}

function adminAnalyticsDateCutoff(mode) {
  const now = Date.now();
  if (mode === "7d") return now - 7 * 86400000;
  if (mode === "30d") return now - 30 * 86400000;
  if (mode === "12m") return now - 365 * 86400000;
  return now - 180 * 86400000; // default 6m
}

function renderAdminAnalyticsLegend(chartId, datasets) {
  const legend = byId("adminAnalyticsLegend");
  if (!legend) return;
  legend.innerHTML = datasets.map((ds, index) => `
    <button class="legend-item 3d-legend-btn" type="button" data-admin-series="${index}" aria-pressed="true">
      <i class="dot 3d-dot" style="background:${themeSeriesCssColor(ds.color)}; box-shadow: 0 2px 6px ${ds.color}55;"></i>
      <span>${escapeHtml(ds.label)}</span>
    </button>
  `).join("");
  legend.querySelectorAll("[data-admin-series]").forEach((button) => {
    button.addEventListener("click", () => {
      const chart = state.charts[chartId];
      const index = Number(button.dataset.adminSeries);
      if (!chart || !Number.isInteger(index)) return;
      chart.setDatasetVisibility(index, !chart.isDatasetVisible(index));
      button.classList.toggle("hidden", !chart.isDatasetVisible(index));
      button.setAttribute("aria-pressed", String(chart.isDatasetVisible(index)));
      chart.update();
    });
  });
}

function setAdminAnalyticsViewMode(mode) {
  state.adminAnalyticsViewMode = mode;
  const toggle = byId("adminAnalyticsViewToggle");
  toggle?.querySelectorAll(".view-mode-btn").forEach((btn) => {
    const isTarget = btn.dataset.analyticsView === mode;
    btn.classList.toggle("active", isTarget);
    btn.setAttribute("aria-selected", String(isTarget));
  });

  const waveContainer = byId("adminWaveViewContainer");
  const compContainer = byId("adminComparisonViewContainer");
  const bgyControl = byId("adminBarangayControlItem");

  if (waveContainer) waveContainer.hidden = mode !== "wave";
  if (compContainer) compContainer.hidden = mode !== "comparison";

  if (bgyControl) {
    bgyControl.style.opacity = mode === "comparison" ? "0.45" : "1";
    bgyControl.style.pointerEvents = mode === "comparison" ? "none" : "auto";
  }

  requestAnimationFrame(() => {
    renderOverviewAnalyticsChart();
  });
}

function renderOverviewAnalyticsChart() {
  if (!window.Chart) return;
  const targetBarangay = byId("adminAnalyticsBarangay")?.value || state.adminAnalyticsBarangay || "all";
  const mode = byId("adminAnalyticsRange")?.value || state.adminAnalyticsRange || "6m";
  const category = state.adminAnalyticsCategory || "concerns";
  const viewMode = state.adminAnalyticsViewMode || "wave";

  state.adminAnalyticsBarangay = targetBarangay;
  state.adminAnalyticsRange = mode;
  state.adminAnalyticsCategory = category;
  state.adminAnalyticsViewMode = viewMode;

  if (viewMode === "wave") {
    renderAdminHistoricalChart(category, targetBarangay, mode);
  } else {
    renderAdminBarangayComparison(category, mode);
  }
}

function renderAdminHistoricalChart(category, targetBarangay, mode) {
  const chartId = "overviewAnalyticsChart";
  const canvas = byId(chartId);
  if (!canvas) return;

  const buckets = barangayAnalyticsBuckets(mode);
  let groups = [];
  let subtitleText = "";

  const barangayLabel = targetBarangay === "all" ? "all 42 barangays" : targetBarangay;

  if (category === "residents") {
    subtitleText = `Resident verification activity over time (${barangayLabel})`;
    const residents = state.residentVerifications.filter((v) => matchesAdminAnalyticsBarangay(v, targetBarangay));
    groups = [
      {
        label: "Verification Requests",
        color: "#059669",
        items: residents,
        date: (item) => item.submittedAt || item.verificationData?.submittedAt || item.createdAt
      },
      {
        label: "Residents Verified",
        color: "#2563eb",
        items: residents.filter((item) => verificationStatus(item) === "verified"),
        date: (item) => item.verifiedAt || item.reviewedAt || item.updatedAt
      }
    ];
  } else if (category === "announcements") {
    subtitleText = `Announcements published over time (${barangayLabel})`;
    const announcements = state.posts.filter((p) => matchesAdminAnalyticsBarangay(p, targetBarangay) && (p.status === "published" || announcementUiStatus(p) === "published"));
    groups = [
      {
        label: "Announcements Published",
        color: "#059669",
        items: announcements,
        date: (item) => item.publishedAt || item.createdAt || item.timestamp
      }
    ];
  } else if (category === "emergencies") {
    subtitleText = `Emergency alerts issued over time (${barangayLabel})`;
    const emergencies = (state.emergencies || []).concat(state.alerts || []).filter((e) => matchesAdminAnalyticsBarangay(e, targetBarangay));
    groups = [
      {
        label: "Emergency Alerts Issued",
        color: "#dc2626",
        items: emergencies,
        date: (item) => item.createdAt || item.startAt || item.timestamp
      }
    ];
  } else if (category === "complaints" || category === "complaint") {
    subtitleText = `Complaints received vs. resolved over time (${barangayLabel})`;
    const complaints = (state.complaints || []).filter((c) => matchesAdminAnalyticsBarangay(c, targetBarangay));
    groups = [
      {
        label: "Received",
        color: "#059669",
        items: complaints,
        date: (item) => item.createdAt || item.date || item.filedAt
      },
      {
        label: "Resolved",
        color: "#e29a18",
        items: complaints.filter(isComplaintResolved),
        date: complaintResolvedDate
      }
    ];
  } else {
    // Default: concerns
    subtitleText = `Concerns received vs. resolved over time (${barangayLabel})`;
    const concerns = state.concerns.filter((c) => matchesAdminAnalyticsBarangay(c, targetBarangay));
    groups = [
      {
        label: "Received",
        color: "#059669",
        items: concerns,
        date: (item) => item.createdAt || item.date
      },
      {
        label: "Resolved",
        color: "#e29a18",
        items: concerns.filter((item) => concernStatus(item) === "resolved"),
        date: concernResolvedDate
      }
    ];
  }

  const subEl = byId("historicalActivitySubtitle");
  if (subEl) subEl.textContent = subtitleText;

  const datasets = groups.map((g) => ({
    label: g.label,
    color: g.color,
    data: countBarangayAnalyticsSeries(g.items, g.date, buckets, mode)
  }));

  const hasActivity = datasets.some((ds) => ds.data.some((v) => v > 0));
  const emptyEl = byId("adminAnalyticsEmpty");
  if (emptyEl) emptyEl.hidden = hasActivity;

  renderAdminAnalyticsLegend(chartId, datasets);

  state.charts[chartId]?.destroy();
  const ctx = canvas.getContext("2d");

  const chartDatasets = datasets.map((ds) => {
    const baseColor = ds.color || "#059669";
    const gradient = ctx.createLinearGradient(0, 0, 0, 270);
    gradient.addColorStop(0, hexToRgba(baseColor, 0.52));
    gradient.addColorStop(0.25, hexToRgba(baseColor, 0.26));
    gradient.addColorStop(0.65, hexToRgba(baseColor, 0.07));
    gradient.addColorStop(0.95, hexToRgba(baseColor, 0.01));
    gradient.addColorStop(1, "rgba(255, 255, 255, 0)");

    return {
      type: "line",
      label: ds.label,
      data: ds.data,
      borderColor: baseColor,
      backgroundColor: gradient,
      fill: true,
      tension: 0.42,
      borderWidth: 3.5,
      pointRadius: 5,
      pointHoverRadius: 8,
      pointBackgroundColor: "#ffffff",
      pointBorderColor: baseColor,
      pointBorderWidth: 3,
      pointHoverBorderWidth: 4
    };
  });

  state.charts[chartId] = new Chart(ctx, {
    type: "line",
    data: {
      labels: buckets.map((b) => b.label),
      datasets: chartDatasets
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      interaction: {
        mode: "index",
        intersect: false
      },
      animation: {
        duration: 550,
        easing: "easeOutQuart"
      },
      plugins: {
        legend: { display: false },
        tooltip: {
          backgroundColor: "rgba(6, 44, 32, 0.95)",
          borderColor: "rgba(255, 255, 255, 0.2)",
          borderWidth: 1,
          padding: 12,
          cornerRadius: 14,
          titleFont: { family: "'Outfit', 'Manrope', sans-serif", size: 13, weight: "800" },
          bodyFont: { family: "'Outfit', 'Manrope', sans-serif", size: 12.5, weight: "600" },
          usePointStyle: true,
          boxPadding: 6,
          callbacks: {
            label: (ctx) => ` ${ctx.dataset.label}: ${formatNumber(ctx.parsed.y)}`
          }
        }
      },
      scales: {
        y: {
          beginAtZero: true,
          ticks: {
            precision: 0,
            stepSize: 1,
            color: "#526b62",
            font: { family: "'Outfit', 'Manrope', sans-serif", size: 11, weight: "700" },
            padding: 8
          },
          grid: { color: "rgba(205, 226, 217, 0.4)", drawBorder: false },
          border: { display: false }
        },
        x: {
          ticks: {
            color: "#526b62",
            font: { family: "'Outfit', 'Manrope', sans-serif", size: 11, weight: "700" },
            padding: 8
          },
          grid: { display: false },
          border: { display: false }
        }
      }
    }
  });
}

function renderAdminBarangayComparison(category, mode) {
  const chartId = "barangayComparisonChart";
  const canvas = byId(chartId);
  if (!canvas) return;

  const cutoff = adminAnalyticsDateCutoff(mode);

  // Group items by each of the 42 barangays
  const ranking = BARANGAYS.map((bgyName) => {
    let count = 0;
    if (category === "residents") {
      count = state.residentVerifications.filter((v) => {
        const d = dateValue(v.submittedAt || v.verificationData?.submittedAt || v.createdAt);
        return d >= cutoff && matchesAdminAnalyticsBarangay(v, bgyName);
      }).length;
    } else if (category === "announcements") {
      count = state.posts.filter((p) => {
        const d = dateValue(p.publishedAt || p.createdAt || p.timestamp);
        return d >= cutoff && (p.status === "published" || announcementUiStatus(p) === "published") && matchesAdminAnalyticsBarangay(p, bgyName);
      }).length;
    } else if (category === "emergencies") {
      const em = (state.emergencies || []).concat(state.alerts || []);
      count = em.filter((e) => {
        const d = dateValue(e.createdAt || e.startAt || e.timestamp);
        return d >= cutoff && matchesAdminAnalyticsBarangay(e, bgyName);
      }).length;
    } else if (category === "complaints" || category === "complaint") {
      count = (state.complaints || []).filter((c) => {
        const d = dateValue(c.createdAt || c.date || c.filedAt);
        return d >= cutoff && matchesAdminAnalyticsBarangay(c, bgyName);
      }).length;
    } else {
      // concerns received
      count = state.concerns.filter((c) => {
        const d = dateValue(c.createdAt || c.date);
        return d >= cutoff && matchesAdminAnalyticsBarangay(c, bgyName);
      }).length;
    }
    return { name: bgyName, count };
  });

  ranking.sort((a, b) => b.count - a.count || a.name.localeCompare(b.name));
  state.adminComparisonRanking = ranking;
  state.adminComparisonCategory = category;

  const top5 = ranking.slice(0, 5);
  const hasComparisonActivity = top5.some((b) => b.count > 0);
  const emptyEl = byId("adminComparisonEmpty");
  if (emptyEl) emptyEl.hidden = hasComparisonActivity;

  state.charts[chartId]?.destroy();
  const ctx = canvas.getContext("2d");

  const barGrad1 = ctx.createLinearGradient(0, 0, 320, 0);
  barGrad1.addColorStop(0, "#059669");
  barGrad1.addColorStop(1, "#10b981");

  const barGrad2 = ctx.createLinearGradient(0, 0, 320, 0);
  barGrad2.addColorStop(0, "#0d9488");
  barGrad2.addColorStop(1, "#14b8a6");

  const barGrad3 = ctx.createLinearGradient(0, 0, 320, 0);
  barGrad3.addColorStop(0, "#0284c7");
  barGrad3.addColorStop(1, "#38bdf8");

  const barGradients = [barGrad1, barGrad2, barGrad3, "#34d399", "#6ee7b7"];

  state.charts[chartId] = new Chart(ctx, {
    type: "bar",
    data: {
      labels: top5.map((b) => b.name),
      datasets: [
        {
          label: "Activity",
          data: top5.map((b) => b.count),
          backgroundColor: barGradients.slice(0, top5.length),
          borderRadius: 8,
          borderSkipped: false,
          maxBarThickness: 22,
          barPercentage: 0.7
        }
      ]
    },
    options: {
      indexAxis: "y",
      responsive: true,
      maintainAspectRatio: false,
      animation: {
        duration: 650,
        easing: "easeOutQuart"
      },
      plugins: {
        legend: { display: false },
        tooltip: {
          backgroundColor: "rgba(6, 44, 32, 0.95)",
          borderColor: "rgba(255, 255, 255, 0.18)",
          borderWidth: 1,
          padding: 11,
          cornerRadius: 12,
          titleFont: { family: "'Outfit', 'Manrope', sans-serif", size: 12.5, weight: "800" },
          callbacks: {
            label: (ctx) => ` ${ctx.parsed.x} ${category}`
          }
        }
      },
      scales: {
        x: {
          beginAtZero: true,
          ticks: {
            precision: 0,
            stepSize: 1,
            color: "#526b62",
            font: { family: "'Outfit', 'Manrope', sans-serif", size: 11, weight: "700" }
          },
          grid: { color: "rgba(205, 226, 217, 0.4)", drawBorder: false },
          border: { display: false }
        },
        y: {
          ticks: {
            color: "#0f372a",
            font: { family: "'Outfit', 'Manrope', sans-serif", size: 12, weight: "750" }
          },
          grid: { display: false },
          border: { display: false }
        }
      }
    }
  });
}

window.openAllBarangaysModal = () => {
  const modal = byId("allBarangaysModal");
  if (!modal) return;
  modal.hidden = false;
  const category = state.adminComparisonCategory || "concerns";
  const sub = byId("allBarangaysSubtitle");
  if (sub) sub.textContent = `All 42 barangays ranked by ${category} in the selected period`;
  renderAllBarangaysList();
};

window.closeAllBarangaysModal = () => {
  const modal = byId("allBarangaysModal");
  if (modal) modal.hidden = true;
};

window.filterAllBarangaysList = () => {
  const query = (byId("allBarangaysSearch")?.value || "").trim().toLowerCase();
  renderAllBarangaysList(query);
};

function renderAllBarangaysList(filterQuery = "") {
  const listEl = byId("allBarangaysList");
  if (!listEl) return;
  const ranking = state.adminComparisonRanking || [];
  const maxCount = Math.max(1, ...(ranking.map((b) => b.count)));
  const category = state.adminComparisonCategory || "concerns";

  const filtered = filterQuery ? ranking.filter((b) => b.name.toLowerCase().includes(filterQuery)) : ranking;

  if (!filtered.length) {
    listEl.innerHTML = '<div class="empty-state"><strong>No matching barangay found.</strong></div>';
    return;
  }

  listEl.innerHTML = filtered.map((b, i) => {
    const origIndex = ranking.indexOf(b) + 1;
    const pct = Math.round((b.count / maxCount) * 100);
    const isTop = origIndex <= 3;
    return `
      <div class="all-barangays-row ${isTop ? "top-rank" : ""}">
        <div class="all-barangays-info">
          <span class="all-barangays-rank-badge">#${origIndex}</span>
          <span class="all-barangays-name">${escapeHtml(b.name)}</span>
        </div>
        <div class="all-barangays-bar-wrap">
          <div class="all-barangays-progress-track">
            <div class="all-barangays-progress-fill" style="width: ${pct}%;"></div>
          </div>
          <span class="all-barangays-count">${formatNumber(b.count)}</span>
        </div>
      </div>
    `;
  }).join("");
}

function renderCommunityActivityChart() {
  const days = Array.from({ length: 7 }, (_, index) => { const date = new Date(); date.setHours(0, 0, 0, 0); date.setDate(date.getDate() - (6 - index)); return date; });
  const requests = [...state.documentRequests, ...state.helpdeskTickets];
  const verificationRequests = state.users.filter((user) => user.verificationData?.submittedAt);
  const series = [
    { label: "Concerns", color: "#0a8a68", items: state.concerns, date: (item) => item.date || item.createdAt },
    { label: "Emergencies", color: "#d55252", items: state.emergencies, date: (item) => item.createdAt || item.date || item.reportedAt },
    { label: "Requests", color: "#e29a18", items: requests, date: (item) => item.dateSubmitted || item.createdAt || item.updatedAt },
    { label: "Announcements", color: "#2878bd", items: state.posts, date: (item) => item.createdAt || item.timestamp },
    { label: "Verifications", color: "#7658bd", items: verificationRequests, date: (item) => item.verificationData?.submittedAt }
  ].map((group) => ({
    label: group.label,
    color: group.color,
    values: days.map((day) => group.items.filter((item) => sameDay(parseDate(group.date(item)), day)).length)
  }));
  drawCommunityActivityChart(
    "communityActivityChart",
    days.map((day) => new Intl.DateTimeFormat("en-PH", { weekday: "short" }).format(day)),
    series
  );
}

function drawCommunityActivityChart(id, labels, series) {
  if (!window.Chart || !byId(id)) return;
  const canvas = byId(id);
  const ctx = canvas.getContext("2d");
  state.charts[id]?.destroy();
  state.charts[id] = new Chart(ctx, {
    type: "line",
    data: {
      labels,
      datasets: series.map((item) => {
        const gradient = ctx.createLinearGradient(0, 0, 0, 300);
        gradient.addColorStop(0, item.color + "38");
        gradient.addColorStop(1, item.color + "00");
        return {
          label: item.label,
          data: item.values,
          borderColor: item.color,
          backgroundColor: gradient,
          borderWidth: 2.8,
          pointRadius: 3.5,
          pointHoverRadius: 6,
          pointBackgroundColor: "#ffffff",
          pointBorderColor: item.color,
          pointBorderWidth: 2,
          tension: .4,
          fill: true
        };
      })
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      interaction: { mode: "index", intersect: false },
      plugins: {
        legend: { display: false },
        tooltip: {
          backgroundColor: "rgba(10, 39, 31, 0.94)",
          padding: 12,
          cornerRadius: 12,
          titleFont: { family: "Manrope", size: 13, weight: "800" },
          bodyFont: { family: "Manrope", size: 12 },
          usePointStyle: true
        }
      },
      scales: {
        y: {
          beginAtZero: true,
          grid: { color: "rgba(215, 229, 222, 0.55)" },
          ticks: { precision: 0, font: { family: "Manrope", size: 11, weight: "600" }, color: "#62766e" }
        },
        x: {
          grid: { display: false },
          ticks: { font: { family: "Manrope", size: 11, weight: "600" }, color: "#62766e" }
        }
      }
    },
    plugins: [{
      id: "communityActivityLegend",
      afterUpdate(chart) {
        const legendContainer = byId(id + "Legend");
        if (!legendContainer) return;
        legendContainer.replaceChildren();
        chart.options.plugins.legend.labels.generateLabels(chart).forEach((item) => {
          const legendItem = document.createElement("button");
          legendItem.type = "button";
          legendItem.className = `legend-item${item.hidden ? " hidden" : ""}`;
          legendItem.setAttribute("aria-pressed", String(!item.hidden));
          legendItem.onclick = () => {
            chart.setDatasetVisibility(item.datasetIndex, !chart.isDatasetVisible(item.datasetIndex));
            chart.update();
          };
          const marker = document.createElement("span");
          marker.className = "legend-color";
          marker.style.background = item.strokeStyle;
          const label = document.createElement("span");
          label.className = "legend-label";
          label.textContent = item.text;
          legendItem.append(marker, label);
          legendContainer.appendChild(legendItem);
        });
      }
    }]
  });
}

byId("settingsForm").addEventListener("submit", async (event) => {
  event.preventDefault();
  const button = event.currentTarget.querySelector("button[type='submit']");
  setButtonBusy(button, true, "Saving…");
  try {
    const settings = { municipalityName: byId("mun-name").value.trim(), supportEmail: byId("mun-email").value.trim(), emergencyPhone: byId("mun-phone").value.trim(), concernSlaHours: Number(byId("concern-sla").value) || 72, helpdeskSlaHours: Number(byId("helpdesk-sla").value) || 24, documentProcessingDays: Number(byId("document-processing-days").value) || 5, defaultAlertExpiryHours: Number(byId("alert-expiry-hours").value) || 24, defaultAnnouncementNotify: byId("default-announcement-notify").checked, updatedAt: serverTimestamp(), updatedBy: auth.currentUser.uid };
    const batch = writeBatch(db);
    batch.set(doc(db, "system", "settings"), settings, { merge: true });
    addAuditToBatch(batch, "settings_updated", "system", "settings", {});
    await batch.commit(); showToast("System settings saved.");
  } catch (error) { showToast(`Settings could not be saved: ${callableErrorMessage(error)}`, true); }
  finally { setButtonBusy(button, false); }
});

function activeStructureMembers(predicate) {
  return state.users.filter((user) => predicate(user)
    && ["active", "approved"].includes(normalize(user.accountStatus || user.status))
    && peopleAccountStatus(user) === "active").length;
}

async function loadStructureResidentCounts() {
  if (state.structureResidentCountsLoading || !can("structure")
      || Date.now() - state.structureResidentCountsFetchedAt < 60000) return;
  const requesterId = auth.currentUser?.uid;
  if (!requesterId) return;
  state.structureResidentCountsLoading = true;
  let failed = false;
  try {
    for (let start = 0; start < BARANGAYS.length; start += 7) {
      const barangays = BARANGAYS.slice(start, start + 7);
      const results = await Promise.allSettled(barangays.map((barangay) =>
        getCountFromServer(query(collection(db, "users"),
          where("role", "==", "resident"), where("barangayId", "==", barangayIdFor(barangay))))));
      if (auth.currentUser?.uid !== requesterId) return;
      results.forEach((result, index) => {
        state.structureResidentCounts.set(barangayIdFor(barangays[index]),
          result.status === "fulfilled" ? result.value.data().count : null);
        if (result.status === "rejected") failed = true;
      });
      if (state.page === "structure" && state.structureTab === "barangays") renderStructure();
    }
    state.structureResidentCountsFetchedAt = Date.now();
    if (failed) showToast("Some resident counts could not be loaded. Please try again later.", true);
  } finally {
    state.structureResidentCountsLoading = false;
  }
}

function renderStructure() {
  if (!can("structure")) return;
  document.querySelectorAll("[data-structure-tab]").forEach((button) => {
    const selected = button.dataset.structureTab === state.structureTab;
    button.classList.toggle("is-active", selected);
    button.setAttribute("aria-selected", String(selected));
  });
  renderDepartmentManagement();
  byId("organizationManagementPanel").hidden = state.structureTab !== "organizations";
  byId("barangayManagementPanel").hidden = state.structureTab !== "barangays";
  if (state.structureTab === "organizations") {
    const target = byId("organizationManagementList");
    target.innerHTML = state.organizations.length ? [...state.organizations]
      .sort((a, b) => String(a.name || "").localeCompare(String(b.name || "")))
      .map((organization) => {
        const active = ["verified", "active"].includes(normalize(organization.status));
        const count = activeStructureMembers((user) => canonicalRole(user.role) === "organization" && user.organizationId === organization.id);
        const category = concernCategories.find((item) => item.id === (organization.organizationTypeId || organization.categoryId));
        const sector = organization.organizationSector || category?.sector || "public";
        return `<article class="department-management__item"><div><strong>${escapeHtml(organization.name || organization.id)}</strong><small>${sector === "private" ? "Private Organization" : "Public Organization"} · ${escapeHtml(category?.name || "Type required for new concerns")} · ${count} active account${count === 1 ? "" : "s"}</small></div><span class="status-pill status-pill--${active ? "active" : "deactivated"}">${active ? "Active" : "Inactive"}</span><div class="department-management__actions"><button class="table-action" type="button" onclick="openEntityAccess('organization','${safeId(organization.id)}')"><span class="material-symbols-rounded">admin_panel_settings</span>Access</button><button class="table-action" type="button" onclick="openOrganizationEditor('${safeId(organization.id)}')"><span class="material-symbols-rounded">edit</span>Edit</button><button class="table-action ${active ? "table-action--danger" : ""}" type="button" onclick="setOrganizationStatus('${safeId(organization.id)}','${active ? "deactivate" : "reactivate"}',this)">${active ? "Deactivate" : "Reactivate"}</button></div></article>`;
      }).join("") : '<p class="empty-state">No organizations yet. Add one before creating organization accounts.</p>';
  }
  if (state.structureTab === "barangays") {
    void loadStructureResidentCounts();
    byId("barangayManagementList").innerHTML = BARANGAYS.map((barangay) => {
      const id = barangayIdFor(barangay);
      const count = activeStructureMembers((user) => isBarangayRole(user.role) && (user.barangayId === id || canonicalBarangay(user.barangay) === barangay));
      const residents = state.structureResidentCounts.get(id);
      const residentLabel = residents === undefined ? "Loading residents…"
        : residents === null ? "Resident count unavailable"
          : `${formatNumber(residents)} registered resident${residents === 1 ? "" : "s"}`;
      return `<article class="department-management__item"><div><strong>Barangay ${escapeHtml(barangay)}</strong><small>${count} active official${count === 1 ? "" : "s"} · ${residentLabel}</small></div><div class="department-management__actions"><button class="table-action" type="button" onclick="openEntityAccess('barangay','${safeId(id)}')"><span class="material-symbols-rounded">admin_panel_settings</span>Access</button></div></article>`;
    }).join("");
  }
}

const ENTITY_ACCESS_OPTIONS = [
  ["concerns", "Concerns", "View and handle concerns within the existing assignment."],
  ["announcements", "Announcements", "Publish and manage posts within the existing audience."],
  ["staff:request", "Request member accounts", "New accounts still require IT approval."],
  ["alerts:publish", "Public emergency alerts", "Broadcasts can notify residents. This is separate from private dispatch."],
  ["verifications:local", "Resident verification", "Review sensitive proof and decide requests only in assigned barangays."],
  ["emergencies:direct:send", "Send private emergencies", "Send an incident to another organization without broadcasting it."],
  ["emergencies:direct:receive", "Receive private emergencies", "Acknowledge and respond to requests addressed to this organization."],
];

window.openEntityAccess = (type, id) => {
  if (!isLguAdmin() || (type === "department" && id === "it-department")) return;
  const entity = type === "department" ? state.lguDepartments.find((item) => item.id === id)
    : type === "organization" ? state.organizations.find((item) => item.id === id)
      : BARANGAYS.find((name) => barangayIdFor(name) === id);
  if (!entity) return;
  const name = typeof entity === "string" ? `Barangay ${entity}` : entity.name || entity.publicName || id;
  const policy = state.accessPolicies.get(`${type}_${id}`) || {};
  const choice = (permission) => policy.denied?.includes(permission) ? "deny"
    : policy.granted?.includes(permission) ? "grant" : "default";
  const rows = ENTITY_ACCESS_OPTIONS.filter(([permission]) => type === "organization"
    || !permission.startsWith("emergencies:direct:")).map(([permission, label, explanation]) => `
    <label class="entity-access-row"><span><strong>${escapeHtml(label)}</strong><small>${escapeHtml(explanation)}</small></span>
      <select data-access-permission="${escapeAttribute(permission)}" aria-label="${escapeAttribute(label)} access"
        ${permission === "verifications:local" ? 'onchange="updateEntityVerificationScope()"' : ""}>
        <option value="default" ${choice(permission) === "default" ? "selected" : ""}>Role default</option>
        <option value="grant" ${choice(permission) === "grant" ? "selected" : ""}>Allow</option>
        <option value="deny" ${choice(permission) === "deny" ? "selected" : ""}>Deny</option>
      </select></label>`).join("");
  const scope = type === "barangay" ? "" : `<div id="entityVerificationScope" class="entity-access-scope" hidden>
    <strong>Barangays this office may verify</strong><p>Choose only areas explicitly approved by IT. No barangays means no access.</p>
    <div class="entity-access-barangays">${BARANGAYS.map((barangay) => `<label><input type="checkbox" value="${escapeAttribute(barangayIdFor(barangay))}" ${policy.verificationBarangayIds?.includes(barangayIdFor(barangay)) ? "checked" : ""}>${escapeHtml(barangay)}</label>`).join("")}</div></div>`;
  openModal("Access control", name,
    `<p class="modal-lead">IT overrides apply to current and future members of this ${escapeHtml(type)}. Role default keeps their existing access. IT administration cannot be delegated.</p><div class="entity-access-list">${rows}</div>${scope}`,
    `<button class="button button--secondary" type="button" onclick="closeModal()">Cancel</button><button class="button button--primary" type="button" onclick="saveEntityAccess('${safeId(type)}','${safeId(id)}',this)">Save access</button>`);
  window.updateEntityVerificationScope();
  protectModalEdits();
};

window.updateEntityVerificationScope = () => {
  const scope = byId("entityVerificationScope");
  if (scope) scope.hidden = document.querySelector('[data-access-permission="verifications:local"]')?.value !== "grant";
};

window.saveEntityAccess = async (type, id, button) => {
  const decisions = Object.fromEntries([...document.querySelectorAll("[data-access-permission]")]
    .map((field) => [field.dataset.accessPermission, field.value]));
  for (const permission of ["emergencies:direct:send", "emergencies:direct:receive"]) {
    if (!(permission in decisions)) decisions[permission] = "default";
  }
  const verificationBarangayIds = [...document.querySelectorAll("#entityVerificationScope input:checked")]
    .map((input) => input.value);
  if (type !== "barangay" && decisions["verifications:local"] === "grant" && !verificationBarangayIds.length) {
    showToast("Choose at least one barangay for resident verification.", true);
    return;
  }
  setButtonBusy(button, true, "Saving...");
  try {
    await setEntityAccessPolicyCall({ type, id, decisions, verificationBarangayIds });
    closeModal(true);
    showToast("Access updated for all members of this office.");
  } catch (error) {
    showToast(callableErrorMessage(error), true);
    setButtonBusy(button, false);
  }
};

document.querySelectorAll("[data-structure-tab]").forEach((button) => button.addEventListener("click", () => {
  state.structureTab = button.dataset.structureTab;
  renderStructure();
}));

window.openOrganizationEditor = async (organizationId = "", returnRequestId = "") => {
  if (!can("organizations:manage")) return;
  try { await ensureConcernCategories(); } catch (error) { showToast(callableErrorMessage(error), true); return; }
  const organization = state.organizations.find((item) => item.id === organizationId);
  const selectedType = concernCategories.find((item) => item.id === (organization?.organizationTypeId || organization?.categoryId));
  const sector = organization?.organizationSector || selectedType?.sector || "";
  openModal("Partner directory", organization ? "Edit organization" : "Add organization",
    `<div class="detail-grid"><label class="field detail-item full"><span>Organization Name</span><input id="managedOrganizationName" maxlength="140" value="${escapeAttribute(organization?.name || "")}" placeholder="Example: CEBECO"></label><label class="field detail-item full"><span>Organization Sector</span><select id="managedOrganizationSector" onchange="updateManagedOrganizationTypes(this.value)"><option value="">Select sector</option><option value="public" ${sector === "public" ? "selected" : ""}>Public Organization</option><option value="private" ${sector === "private" ? "selected" : ""}>Private Organization</option></select></label><label class="field detail-item full"><span>Organization Type</span><select id="managedOrganizationType">${organizationTypeOptions(sector, selectedType?.id || "")}</select></label></div>`,
    `<button class="button button--secondary" type="button" onclick="${returnRequestId ? `openStaffRequest('${safeId(returnRequestId)}')` : "closeModal()"}">Cancel</button><button class="button button--primary" type="button" onclick="saveManagedOrganization('${safeId(organizationId)}',this,'${safeId(returnRequestId)}')">Save organization</button>`);
  protectModalEdits();
};
window.updateManagedOrganizationTypes = (sector) => {
  const field = byId("managedOrganizationType");
  if (field) field.innerHTML = organizationTypeOptions(sector);
};

window.saveManagedOrganization = async (organizationId, button, returnRequestId = "") => {
  const name = byId("managedOrganizationName")?.value.trim() || "";
  const organizationSector = byId("managedOrganizationSector")?.value || "";
  const organizationTypeId = byId("managedOrganizationType")?.value || "";
  if (name.length < 2) { showModalFieldError("managedOrganizationName", "Enter the official organization name."); return; }
  if (!organizationSector) { showModalFieldError("managedOrganizationSector", "Select an organization sector."); return; }
  if (!concernCategories.some((category) => category.id === organizationTypeId && category.sector === organizationSector)) { showModalFieldError("managedOrganizationType", "Select an organization type."); return; }
  setButtonBusy(button, true, "Saving...");
  try {
    await manageOrganizationCall({ action: "save", organizationId, name, organizationSector, organizationTypeId });
    const cached = state.organizations.find((item) => item.id === organizationId);
    if (cached) { cached.categoryId = organizationTypeId; cached.organizationTypeId = organizationTypeId; cached.organizationSector = organizationSector; }
    closeModal(true);
    showToast("Organization saved.");
    if (returnRequestId) window.openStaffRequest(returnRequestId);
  } catch (error) { showToast(callableErrorMessage(error), true); setButtonBusy(button, false); }
};

window.setOrganizationStatus = async (organizationId, action, button) => {
  const organization = state.organizations.find((item) => item.id === organizationId);
  if (!organization) return;
  const deactivating = action === "deactivate";
  if (deactivating && activeStructureMembers((user) => canonicalRole(user.role) === "organization" && user.organizationId === organizationId)) {
    showToast("Move or disable active organization accounts before deactivating this organization.", true);
    return;
  }
  const confirmed = await confirmAction({
    title: `${deactivating ? "Deactivate" : "Reactivate"} organization?`,
    message: `${organization.name || "This organization"} will be marked ${deactivating ? "inactive and unavailable" : "active and available"} for new account assignments. Existing records are retained.`,
    confirmLabel: deactivating ? "Deactivate organization" : "Reactivate organization",
    danger: deactivating,
  });
  if (!confirmed) return;
  setButtonBusy(button, true, action === "deactivate" ? "Deactivating..." : "Reactivating...");
  try {
    await manageOrganizationCall({ action, organizationId });
    showToast(action === "deactivate" ? "Organization deactivated." : "Organization reactivated.");
  } catch (error) { showToast(callableErrorMessage(error), true); setButtonBusy(button, false); }
};

