function orgProfileSessionKey() {
  const profile = state.currentProfile || {};
  return JSON.stringify([state.sessionGeneration, auth.currentUser?.uid, profile.id,
    canonicalRole(profile.role), profile.organizationId, profile.barangayId, profile.departmentId]);
}

function getOrgPhotoUrl() {
  const isOrg = canonicalRole(state.currentProfile?.role) === "organization";
  if (isOrg) {
    const org = currentOrganization() || {};
    return org.logoUrl || org.photoUrl || org.profilePhotoUrl || org.profilePicture || state.currentProfile?.profilePhotoUrl || state.currentProfile?.photoUrl || "";
  }
  return state.currentProfile?.profilePhotoUrl || state.currentProfile?.photoUrl || "";
}

function updateOrgPhotoUI() {
  const previewImg = byId("orgAvatarPreview");
  const fallbackDiv = byId("orgAvatarFallback");
  const removeBtn = byId("orgRemovePhotoBtn");
  if (!previewImg || !fallbackDiv) return;

  const isOrg = canonicalRole(state.currentProfile?.role) === "organization";
  fallbackDiv.innerHTML = isOrg
    ? '<span class="material-symbols-rounded">corporate_fare</span>'
    : '<span class="material-symbols-rounded">account_circle</span>';

  if (orgPendingPhotoFile) {
    previewImg.hidden = false;
    fallbackDiv.hidden = true;
    if (removeBtn) removeBtn.hidden = false;
    return;
  }

  if (orgPendingRemovePhoto) {
    previewImg.hidden = true;
    previewImg.src = "";
    fallbackDiv.hidden = false;
    if (removeBtn) removeBtn.hidden = true;
    return;
  }

  const savedUrl = getOrgPhotoUrl();
  if (savedUrl) {
    previewImg.src = savedUrl;
    previewImg.hidden = false;
    fallbackDiv.hidden = true;
    if (removeBtn) removeBtn.hidden = false;
  } else {
    previewImg.hidden = true;
    previewImg.src = "";
    fallbackDiv.hidden = false;
    if (removeBtn) removeBtn.hidden = true;
  }
}

function setOrgProfileEditing(isEditing) {
  state.isEditingOrgProfile = Boolean(isEditing);
  orgEditingSessionKey = isEditing ? orgProfileSessionKey() : null;
  const form = byId("organizationProfileForm");
  if (form) form.classList.toggle("is-editing", isEditing);

  const editToggleBtn = byId("orgEditProfileBtn");
  if (editToggleBtn) editToggleBtn.hidden = isEditing;

  const footerReadonly = byId("orgFooterReadonly");
  if (footerReadonly) footerReadonly.hidden = isEditing;

  const footerEditing = byId("orgFooterEditing");
  if (footerEditing) footerEditing.hidden = !isEditing;

  const editModeBadge = byId("orgEditModeBadge");
  if (editModeBadge) editModeBadge.hidden = !isEditing;

  const stars = form ? form.querySelectorAll(".req-star") : [];
  stars.forEach((star) => { star.hidden = !isEditing; });

  const editableFields = [
    byId("organizationProfileContactPerson"),
    byId("organizationProfileContactNumber"),
    byId("organizationProfileEmail"),
    byId("organizationProfileAddress")
  ];

  editableFields.forEach((field) => {
    if (!field) return;
    field.readOnly = !isEditing;
    if (isEditing) {
      field.removeAttribute("aria-readonly");
    } else {
      field.setAttribute("aria-readonly", "true");
    }
  });

  const nameField = byId("organizationProfileName");
  if (nameField) {
    nameField.readOnly = true;
    nameField.setAttribute("aria-readonly", "true");
  }
  const typeField = byId("organizationProfileType");
  if (typeField) {
    typeField.readOnly = true;
    typeField.setAttribute("aria-readonly", "true");
  }

  // Handle Account Credentials / Password fields
  const currPw = byId("orgCurrentPassword");
  const newPw = byId("orgNewPassword");
  const confirmPw = byId("orgConfirmPassword");
  const currPwHint = byId("orgCurrentPasswordHint");
  const pwHint = byId("orgPasswordHint");
  const confirmPwHint = byId("orgConfirmPasswordHint");

  if (currPw) {
    currPw.readOnly = !isEditing;
    currPw.value = "";
    if (isEditing) {
      currPw.removeAttribute("aria-readonly");
      currPw.placeholder = "Enter your old/current password";
    } else {
      currPw.setAttribute("aria-readonly", "true");
      currPw.placeholder = "••••••••";
      currPw.type = "password";
    }
  }

  if (newPw) {
    newPw.readOnly = !isEditing;
    newPw.value = "";
    if (isEditing) {
      newPw.removeAttribute("aria-readonly");
      newPw.placeholder = "Enter new password (optional)";
    } else {
      newPw.setAttribute("aria-readonly", "true");
      newPw.placeholder = "••••••••";
      newPw.type = "password";
    }
  }

  if (confirmPw) {
    confirmPw.readOnly = !isEditing;
    confirmPw.value = "";
    if (isEditing) {
      confirmPw.removeAttribute("aria-readonly");
      confirmPw.placeholder = "Confirm new password";
    } else {
      confirmPw.setAttribute("aria-readonly", "true");
      confirmPw.placeholder = "••••••••";
      confirmPw.type = "password";
    }
  }

  if (currPwHint) currPwHint.hidden = !isEditing;
  if (pwHint) pwHint.hidden = !isEditing;
  if (confirmPwHint) confirmPwHint.hidden = !isEditing;

  if (isEditing) {
    orgOriginalValues = {
      contactPerson: byId("organizationProfileContactPerson")?.value || "",
      contactNumber: byId("organizationProfileContactNumber")?.value || "",
      email: byId("organizationProfileEmail")?.value || "",
      address: byId("organizationProfileAddress")?.value || "",
      photoUrl: getOrgPhotoUrl()
    };
    byId("organizationProfileContactPerson")?.focus();
  }
}

function cancelOrgProfileEditing() {
  if (orgOriginalValues) {
    const cp = byId("organizationProfileContactPerson");
    if (cp) cp.value = orgOriginalValues.contactPerson;
    const cn = byId("organizationProfileContactNumber");
    if (cn) cn.value = orgOriginalValues.contactNumber;
    const em = byId("organizationProfileEmail");
    if (em) em.value = orgOriginalValues.email;
    const ad = byId("organizationProfileAddress");
    if (ad) ad.value = orgOriginalValues.address;
  }
  const currPw = byId("orgCurrentPassword");
  if (currPw) {
    currPw.value = "";
    currPw.type = "password";
    currPw.placeholder = "••••••••";
  }
  const newPw = byId("orgNewPassword");
  if (newPw) {
    newPw.value = "";
    newPw.type = "password";
    newPw.placeholder = "••••••••";
  }
  const confirmPw = byId("orgConfirmPassword");
  if (confirmPw) {
    confirmPw.value = "";
    confirmPw.type = "password";
    confirmPw.placeholder = "••••••••";
  }
  document.querySelectorAll("[data-toggle-password]").forEach((btn) => {
    const icon = btn.querySelector(".material-symbols-rounded");
    if (icon) icon.textContent = "visibility";
    btn.setAttribute("aria-label", "Show password");
  });
  orgPendingPhotoFile = null;
  orgPendingRemovePhoto = false;
  const photoInput = byId("orgProfilePhotoInput");
  if (photoInput) photoInput.value = "";
  updateOrgPhotoUI();
  setOrgProfileEditing(false);
}

function updateHeaderAccountCard(user = auth.currentUser) {
  const email = byId("admin-email");
  const avatar = byId("adminInitials");
  const roleLabel = document.querySelector(".admin-chip small");
  const scope = byId("accountScope");
  const role = canonicalRole(state.currentProfile?.role);
  const isOrganization = role === "organization";

  if (isOrganization) {
    const org = currentOrganization() || {};
    const orgName = org.name || state.currentProfile?.organizationName || state.currentProfile?.name || user?.email || "Organization User";
    if (email) {
      email.textContent = orgName;
      email.title = orgName;
    }
    if (roleLabel) {
      roleLabel.textContent = "Organization Staff";
    }
    const photoUrl = org.logoUrl || org.photoUrl || org.profilePhotoUrl || org.profilePicture || state.currentProfile?.profilePhotoUrl || "";
    if (avatar) {
      if (photoUrl) {
        avatar.innerHTML = `<img src="${escapeAttribute(photoUrl)}" alt="Avatar" class="header-avatar-img">`;
        avatar.classList.add("has-photo");
      } else {
        avatar.textContent = initials(orgName);
        avatar.classList.remove("has-photo");
      }
    }
    if (scope) {
      scope.textContent = orgName;
    }
    return;
  }

  if (email) {
    email.textContent = state.currentProfile?.username || user?.email || "Administrator";
    email.title = email.textContent;
  }
  if (avatar) {
    const photoUrl = state.currentProfile?.profilePhotoUrl || state.currentProfile?.photoUrl || "";
    if (photoUrl) {
      avatar.innerHTML = `<img src="${escapeAttribute(photoUrl)}" alt="Avatar" class="header-avatar-img">`;
      avatar.classList.add("has-photo");
    } else {
      avatar.textContent = initials(state.currentProfile?.name || state.currentProfile?.username || user?.email || "Admin User");
      avatar.classList.remove("has-photo");
    }
  }
  if (roleLabel) {
    roleLabel.textContent = labelForRole(state.currentProfile?.role);
  }
  if (scope) {
    scope.textContent = state.currentProfile?.organizationName
      || state.currentProfile?.barangay
      || (isMunicipalRole(state.currentProfile?.role) ? currentDepartmentPublisherName() : labelForRole(state.currentProfile?.role));
  }
}

function fillSettingsForm() {
  // Live collection updates must not replace a profile draft or clear credentials.
  if (state.isEditingOrgProfile && orgEditingSessionKey === orgProfileSessionKey()) return;
  if (state.isEditingOrgProfile) cancelOrgProfileEditing();
  const role = canonicalRole(state.currentProfile?.role);
  const isOrganization = role === "organization";
  const isSuperAdmin = role === "super_admin";
  const isBarangay = isBarangayRole(role);
  const isDepartmentStaff = role === "lgu";
  const isMayor = role === "mayor";

  const orgForm = byId("organizationProfileForm");
  const settingsForm = byId("settingsForm");
  if (orgForm) orgForm.hidden = false;
  if (settingsForm) settingsForm.hidden = true;

  // Populate municipality settings form (for super_admin)
  if (byId("mun-name")) byId("mun-name").value = state.settings.municipalityName || "Municipality of Barili";
  if (byId("mun-email")) byId("mun-email").value = state.settings.supportEmail || "support@barili.gov.ph";
  if (byId("mun-phone")) byId("mun-phone").value = state.settings.emergencyPhone || "(032) 470 9201";
  if (byId("concern-sla")) byId("concern-sla").value = state.settings.concernSlaHours || 72;
  if (byId("helpdesk-sla")) byId("helpdesk-sla").value = state.settings.helpdeskSlaHours || 24;
  if (byId("document-processing-days")) byId("document-processing-days").value = state.settings.documentProcessingDays || 5;
  if (byId("alert-expiry-hours")) byId("alert-expiry-hours").value = state.settings.defaultAlertExpiryHours || 24;
  if (byId("default-announcement-notify")) byId("default-announcement-notify").checked = state.settings.defaultAnnouncementNotify !== false;

  // Populate Profile Card
  if (isOrganization) {
    const organization = currentOrganization() || {};
    const orgName = organization.name || state.currentProfile?.organizationName || "Organization Profile";
    if (byId("organizationProfileHeading")) byId("organizationProfileHeading").textContent = orgName;
    const sub = byId("organizationProfileSub");
    if (sub) {
      sub.textContent = `${organization.organizationType || state.currentProfile?.organizationType || "Partner Organization"} • Municipality of Barili`;
    }
    if (byId("organizationProfileEyebrowText")) byId("organizationProfileEyebrowText").textContent = "Authorized Organization";
    if (byId("orgSection1Heading")) byId("orgSection1Heading").textContent = "Organization Details";
    if (byId("orgSection1Sub")) byId("orgSection1Sub").textContent = "Verified organization records";
    if (byId("orgProfileNameLabel")) byId("orgProfileNameLabel").textContent = "Organization Name";
    if (byId("orgProfileNameIcon")) byId("orgProfileNameIcon").textContent = "apartment";
    if (byId("orgProfileTypeLabel")) byId("orgProfileTypeLabel").textContent = "Organization Type";
    if (byId("orgProfileTypeIcon")) byId("orgProfileTypeIcon").textContent = "category";
    if (byId("orgProfileContactPersonLabel")) byId("orgProfileContactPersonLabel").innerHTML = 'Contact Person <b class="req-star" hidden>*</b>';
    if (byId("orgProfileAddressLabel")) byId("orgProfileAddressLabel").innerHTML = 'Address <b class="req-star" hidden>*</b>';
    if (byId("orgFooterLockText")) byId("orgFooterLockText").textContent = "Managed by LGU administration.";

    if (byId("organizationProfileName")) byId("organizationProfileName").value = orgName;
    if (byId("organizationProfileType")) byId("organizationProfileType").value = organization.organizationType || state.currentProfile?.organizationType || "Partner Organization";
    if (byId("organizationProfileContactPerson")) byId("organizationProfileContactPerson").value = organization.contactPerson || state.currentProfile?.name || "";
    if (byId("organizationProfileContactNumber")) byId("organizationProfileContactNumber").value = organization.contactNumber || state.currentProfile?.contactNumber || "";
    if (byId("organizationProfileEmail")) byId("organizationProfileEmail").value = organization.email || state.currentProfile?.email || auth.currentUser?.email || "";
    if (byId("organizationProfileAddress")) byId("organizationProfileAddress").value = organization.address || organization.coverageArea || state.currentProfile?.coverageArea || "";
    const active = !["disabled", "deactivated", "inactive"].includes(normalize(organization.status || state.currentProfile?.status));
    if (byId("organizationProfileStatus")) {
      byId("organizationProfileStatus").textContent = active ? "Active" : "Disabled";
      byId("organizationProfileStatus").className = `status-pill status-pill--${active ? "active" : "deactivated"}`;
    }
  } else {
    // Official Profile (Barangay, LGU, Mayor, Super Admin)
    const profile = state.currentProfile || {};
    const officialName = profile.name || profile.username || "Official User";
    const positionTitle = profile.positionTitle || labelForRole(profile.role);
    const barangayName = currentStaffBarangay() || profile.barangay || "Barili";
    const deptName = currentDepartmentPublisherName() || profile.departmentName || "Municipal Office";

    let eyebrowText = "Verified Official";
    let subtitleText = `${positionTitle} • Municipality of Barili`;
    let typeValue = positionTitle;

    if (isBarangay) {
      eyebrowText = "Verified Barangay Official";
      subtitleText = `${positionTitle} • Barangay ${barangayName}, Barili`;
      typeValue = `${positionTitle} • Brgy. ${barangayName}`;
    } else if (isDepartmentStaff) {
      eyebrowText = "LGU Department Personnel";
      subtitleText = `${positionTitle} • ${deptName}, Barili`;
      typeValue = `${positionTitle} • ${deptName}`;
    } else if (isMayor) {
      eyebrowText = "Municipal Mayor";
      subtitleText = "Office of the Municipal Mayor • Municipality of Barili";
      typeValue = "Municipal Mayor • Barili, Cebu";
    } else if (isSuperAdmin) {
      eyebrowText = "System Administrator";
      subtitleText = "LGU IT Department • Municipality of Barili";
      typeValue = "Administrator • IT Department";
    }

    if (byId("organizationProfileHeading")) byId("organizationProfileHeading").textContent = officialName;
    if (byId("organizationProfileSub")) byId("organizationProfileSub").textContent = subtitleText;
    if (byId("organizationProfileEyebrowText")) byId("organizationProfileEyebrowText").textContent = eyebrowText;
    if (byId("orgSection1Heading")) byId("orgSection1Heading").textContent = "Official Details";
    if (byId("orgSection1Sub")) byId("orgSection1Sub").textContent = "Verified official records";
    if (byId("orgProfileNameLabel")) byId("orgProfileNameLabel").textContent = "Official Full Name";
    if (byId("orgProfileNameIcon")) byId("orgProfileNameIcon").textContent = "badge";
    if (byId("orgProfileTypeLabel")) byId("orgProfileTypeLabel").textContent = "Assigned Role & Office";
    if (byId("orgProfileTypeIcon")) byId("orgProfileTypeIcon").textContent = "work";
    if (byId("orgProfileContactPersonLabel")) byId("orgProfileContactPersonLabel").innerHTML = 'Contact Person <b class="req-star" hidden>*</b>';
    if (byId("orgProfileAddressLabel")) byId("orgProfileAddressLabel").innerHTML = 'Office Address <b class="req-star" hidden>*</b>';
    if (byId("orgFooterLockText")) byId("orgFooterLockText").textContent = "Managed by LGU administration.";

    if (byId("organizationProfileName")) byId("organizationProfileName").value = officialName;
    if (byId("organizationProfileType")) byId("organizationProfileType").value = typeValue;
    if (byId("organizationProfileContactPerson")) byId("organizationProfileContactPerson").value = officialName;
    if (byId("organizationProfileContactNumber")) byId("organizationProfileContactNumber").value = profile.contactNumber || profile.phone || "";
    if (byId("organizationProfileEmail")) byId("organizationProfileEmail").value = profile.email || auth.currentUser?.email || "";
    if (byId("organizationProfileAddress")) byId("organizationProfileAddress").value = profile.address || profile.coverageArea || (isBarangay ? `Barangay Hall, Brgy. ${barangayName}, Barili, Cebu` : "Municipal Hall, Barili, Cebu");
    const active = !["disabled", "deactivated", "inactive"].includes(normalize(profile.status));
    if (byId("organizationProfileStatus")) {
      byId("organizationProfileStatus").textContent = active ? "Active" : "Disabled";
      byId("organizationProfileStatus").className = `status-pill status-pill--${active ? "active" : "deactivated"}`;
    }
  }

  updateOrgPhotoUI();
  setOrgProfileEditing(false);
  updateHeaderAccountCard();
}

// ── Full Profile Photo Viewer & Direct Management ───────────────────
function openFullProfilePhotoModal() {
  const modalOverlay = byId("profilePhotoModalOverlay");
  if (!modalOverlay) return;

  refreshFullProfilePhotoModal();
  modalOverlay.hidden = false;
  modalOverlay.style.display = "flex";
  document.body.style.overflow = "hidden";
  byId("profilePhotoModalCloseBtn")?.focus();
}

function refreshFullProfilePhotoModal() {
  const fullImg = byId("profilePhotoFullImg");
  const fallback = byId("profilePhotoFullFallback");
  const fallbackIcon = byId("profilePhotoFullFallbackIcon");
  const removeBtn = byId("profilePhotoModalRemoveBtn");
  const title = byId("profilePhotoModalTitle");

  const currentUrl = getOrgPhotoUrl();
  const role = canonicalRole(state.currentProfile?.role);
  const isOrg = role === "organization";

  if (title) {
    title.textContent = isOrg ? "Organization Logo / Photo" : "Profile Picture";
  }

  if (fallbackIcon) {
    fallbackIcon.textContent = isOrg ? "corporate_fare" : "account_circle";
  }

  if (currentUrl) {
    if (fullImg) {
      fullImg.src = currentUrl;
      fullImg.hidden = false;
    }
    if (fallback) fallback.hidden = true;
    if (removeBtn) removeBtn.hidden = false;
  } else {
    if (fullImg) {
      fullImg.hidden = true;
      fullImg.src = "";
    }
    if (fallback) fallback.hidden = false;
    if (removeBtn) removeBtn.hidden = true;
  }
}

function closeFullProfilePhotoModal() {
  const modalOverlay = byId("profilePhotoModalOverlay");
  if (!modalOverlay) return;
  modalOverlay.hidden = true;
  modalOverlay.style.display = "none";
  document.body.style.overflow = "";
}

async function uploadAndApplyProfilePhoto(file) {
  if (!file) return;
  const ext = String(file.name || "").split(".").pop().toLowerCase();
  if (!["jpg", "jpeg", "png"].includes(ext) || !["image/jpeg", "image/png"].includes(file.type)) {
    showToast("Please choose a valid JPG or PNG image.", true);
    return;
  }
  if (file.size > 5 * 1024 * 1024) {
    showToast("Profile image must be smaller than 5 MB.", true);
    return;
  }

  // Show local preview immediately so UI is instant and responsive
  const reader = new FileReader();
  reader.onload = (event) => {
    const preview = byId("orgAvatarPreview");
    if (preview) {
      preview.src = event.target.result;
      preview.hidden = false;
    }
    const fallback = byId("orgAvatarFallback");
    if (fallback) fallback.hidden = true;
    const fullImg = byId("profilePhotoFullImg");
    if (fullImg) {
      fullImg.src = event.target.result;
      fullImg.hidden = false;
    }
    const fullFallback = byId("profilePhotoFullFallback");
    if (fullFallback) fullFallback.hidden = true;
    const modalRemoveBtn = byId("profilePhotoModalRemoveBtn");
    if (modalRemoveBtn) modalRemoveBtn.hidden = false;
  };
  reader.readAsDataURL(file);

  const avatarWrapper = byId("orgAvatarClickable");
  if (avatarWrapper) avatarWrapper.classList.add("is-uploading");
  const modalUploadStatus = byId("profilePhotoUploadStatus");
  if (modalUploadStatus) modalUploadStatus.hidden = false;

  const role = canonicalRole(state.currentProfile?.role);
  const isOrganization = role === "organization";
  const uid = auth.currentUser?.uid;

  try {
    let finalPhotoUrl = "";
    try {
      const safeExtension = ["png", "jpg", "jpeg"].includes(ext) ? ext : "jpg";
      const contentType = file.type || (safeExtension === "png" ? "image/png" : "image/jpeg");
      const storagePrefix = isOrganization ? `organizations/${currentOrganizationId() || "org"}` : `users/${uid || "profile"}`;
      const uploadedPath = `${storagePrefix}/photo-${Date.now()}.${safeExtension}`;
      const imageReference = storageRef(storage, uploadedPath);
      await uploadBytes(imageReference, file, { contentType });
      finalPhotoUrl = await getDownloadURL(imageReference);
    } catch (uploadErr) {
      console.warn("Storage upload error (fallback to local preview URL if offline/test):", uploadErr);
      finalPhotoUrl = await new Promise((resolve) => {
        const r = new FileReader();
        r.onload = (e) => resolve(e.target.result);
        r.onerror = () => resolve("");
        r.readAsDataURL(file);
      });
    }

    if (isOrganization) {
      const orgId = currentOrganizationId();
      if (orgId) {
        try {
          const batch = writeBatch(db);
          const updateData = {
            logoUrl: finalPhotoUrl,
            photoUrl: finalPhotoUrl,
            profilePhotoUrl: finalPhotoUrl,
            profilePicture: finalPhotoUrl,
            updatedAt: serverTimestamp(),
            updatedBy: uid || ""
          };
          batch.update(doc(db, "organizations", orgId), updateData);
          if (uid) {
            batch.set(doc(db, "users", uid), {
              photoUrl: finalPhotoUrl,
              profilePhotoUrl: finalPhotoUrl,
              avatarUrl: finalPhotoUrl,
              profilePicture: finalPhotoUrl,
              updatedAt: serverTimestamp()
            }, { merge: true });
          }
          addAuditToBatch(batch, "organization_photo_updated", "organization", orgId, {});
          await batch.commit();
        } catch (dbErr) {
          console.warn("Firestore update skipped or failed:", dbErr);
        }
      }

      const currentOrg = currentOrganization();
      if (currentOrg) {
        currentOrg.logoUrl = finalPhotoUrl;
        currentOrg.photoUrl = finalPhotoUrl;
        currentOrg.profilePhotoUrl = finalPhotoUrl;
        currentOrg.profilePicture = finalPhotoUrl;
      }
    } else if (uid) {
      try {
        await setDoc(doc(db, "users", uid), {
          photoUrl: finalPhotoUrl,
          profilePhotoUrl: finalPhotoUrl,
          avatarUrl: finalPhotoUrl,
          profilePicture: finalPhotoUrl,
          updatedAt: serverTimestamp()
        }, { merge: true });
      } catch (dbErr) {
        console.warn("Firestore user update skipped or failed:", dbErr);
      }
    }

    if (isBarangayRole(role)) {
      const bgyId = currentStaffBarangayId();
      const bgyName = currentStaffBarangay();
      if (bgyId) {
        try {
          await setDoc(doc(db, "barangay_profiles", bgyId), {
            id: bgyId,
            barangay: bgyName || bgyId,
            name: `Barangay ${bgyName || bgyId}`,
            photoUrl: finalPhotoUrl,
            profilePhotoUrl: finalPhotoUrl,
            logoUrl: finalPhotoUrl,
            updatedAt: serverTimestamp(),
            updatedBy: uid || ""
          }, { merge: true });
        } catch (bgyErr) {
          console.warn("Saving to barangay_profiles skipped or failed:", bgyErr);
        }
      }
    }

    // Sync authorPhotoUrl to existing posts authored by this user or barangay
    try {
      const postBatch = writeBatch(db);
      let updatedPostCount = 0;
      if (uid) {
        const qAuthor = query(collection(db, "posts"), where("authorId", "==", uid), limit(100));
        const snapAuthor = await getDocs(qAuthor);
        snapAuthor.forEach((d) => {
          postBatch.update(d.ref, { authorPhotoUrl: finalPhotoUrl, updatedAt: serverTimestamp() });
          updatedPostCount++;
        });
      }
      if (isBarangayRole(role)) {
        const bgyId = currentStaffBarangayId();
        if (bgyId) {
          const qBgy = query(collection(db, "posts"), where("barangayId", "==", bgyId), limit(100));
          const snapBgy = await getDocs(qBgy);
          snapBgy.forEach((d) => {
            postBatch.update(d.ref, { authorPhotoUrl: finalPhotoUrl, updatedAt: serverTimestamp() });
            updatedPostCount++;
          });
        }
      }
      if (updatedPostCount > 0) {
        await postBatch.commit();
      }
    } catch (syncErr) {
      console.warn("Syncing authorPhotoUrl to existing posts skipped:", syncErr);
    }

    if (auth.currentUser) {
      try {
        await updateProfile(auth.currentUser, { photoURL: finalPhotoUrl });
      } catch (authErr) {
        console.warn("Auth photoURL sync skipped:", authErr);
      }
    }

    if (state.currentProfile) {
      state.currentProfile.photoUrl = finalPhotoUrl;
      state.currentProfile.profilePhotoUrl = finalPhotoUrl;
      state.currentProfile.avatarUrl = finalPhotoUrl;
      state.currentProfile.profilePicture = finalPhotoUrl;
    }

    orgPendingPhotoFile = null;
    orgPendingRemovePhoto = false;

    updateOrgPhotoUI();
    updateHeaderAccountCard();
    refreshFullProfilePhotoModal();
    showToast("Profile photo updated successfully.");
  } catch (error) {
    console.error("Failed to update profile photo:", error);
    showToast(`Could not update photo: ${callableErrorMessage(error)}`, true);
  } finally {
    if (avatarWrapper) avatarWrapper.classList.remove("is-uploading");
    if (modalUploadStatus) modalUploadStatus.hidden = true;
    const input = byId("orgProfilePhotoInput");
    if (input) input.value = "";
  }
}

async function removeProfilePhotoImmediately() {
  const currentUrl = getOrgPhotoUrl();
  if (!currentUrl) {
    showToast("No profile photo to remove.", true);
    return;
  }

  const role = canonicalRole(state.currentProfile?.role);
  const isOrganization = role === "organization";
  const uid = auth.currentUser?.uid;

  const removeBtn = byId("profilePhotoModalRemoveBtn");
  if (removeBtn) setButtonBusy(removeBtn, true, "Removing...");

  try {
    if (isOrganization) {
      const orgId = currentOrganizationId();
      if (orgId) {
        try {
          const batch = writeBatch(db);
          batch.update(doc(db, "organizations", orgId), {
            logoUrl: "",
            photoUrl: "",
            profilePhotoUrl: "",
            profilePicture: "",
            updatedAt: serverTimestamp(),
            updatedBy: uid || ""
          });
          if (uid) {
            batch.set(doc(db, "users", uid), {
              photoUrl: "",
              profilePhotoUrl: "",
              avatarUrl: "",
              profilePicture: "",
              updatedAt: serverTimestamp()
            }, { merge: true });
          }
          addAuditToBatch(batch, "organization_photo_removed", "organization", orgId, {});
          await batch.commit();
        } catch (dbErr) {
          console.warn("Firestore update skipped or failed:", dbErr);
        }
      }

      const currentOrg = currentOrganization();
      if (currentOrg) {
        currentOrg.logoUrl = "";
        currentOrg.photoUrl = "";
        currentOrg.profilePhotoUrl = "";
        currentOrg.profilePicture = "";
      }
    } else if (uid) {
      try {
        await setDoc(doc(db, "users", uid), {
          photoUrl: "",
          profilePhotoUrl: "",
          avatarUrl: "",
          profilePicture: "",
          updatedAt: serverTimestamp()
        }, { merge: true });
      } catch (dbErr) {
        console.warn("Firestore update skipped or failed:", dbErr);
      }
    }

    if (isBarangayRole(role)) {
      const bgyId = currentStaffBarangayId();
      if (bgyId) {
        try {
          await setDoc(doc(db, "barangay_profiles", bgyId), {
            photoUrl: "",
            profilePhotoUrl: "",
            logoUrl: "",
            updatedAt: serverTimestamp(),
            updatedBy: uid || ""
          }, { merge: true });
        } catch (bgyErr) {
          console.warn("Clearing barangay_profiles skipped:", bgyErr);
        }
      }
    }

    // Clear authorPhotoUrl on existing posts
    try {
      const postBatch = writeBatch(db);
      let updatedPostCount = 0;
      if (uid) {
        const qAuthor = query(collection(db, "posts"), where("authorId", "==", uid), limit(100));
        const snapAuthor = await getDocs(qAuthor);
        snapAuthor.forEach((d) => {
          postBatch.update(d.ref, { authorPhotoUrl: "", updatedAt: serverTimestamp() });
          updatedPostCount++;
        });
      }
      if (isBarangayRole(role)) {
        const bgyId = currentStaffBarangayId();
        if (bgyId) {
          const qBgy = query(collection(db, "posts"), where("barangayId", "==", bgyId), limit(100));
          const snapBgy = await getDocs(qBgy);
          snapBgy.forEach((d) => {
            postBatch.update(d.ref, { authorPhotoUrl: "", updatedAt: serverTimestamp() });
            updatedPostCount++;
          });
        }
      }
      if (updatedPostCount > 0) {
        await postBatch.commit();
      }
    } catch (syncErr) {
      console.warn("Clearing authorPhotoUrl from existing posts skipped:", syncErr);
    }

    if (auth.currentUser) {
      try {
        await updateProfile(auth.currentUser, { photoURL: "" });
      } catch (authErr) {
        console.warn("Auth photoURL sync skipped:", authErr);
      }
    }

    if (state.currentProfile) {
      state.currentProfile.photoUrl = "";
      state.currentProfile.profilePhotoUrl = "";
      state.currentProfile.avatarUrl = "";
      state.currentProfile.profilePicture = "";
    }

    orgPendingPhotoFile = null;
    orgPendingRemovePhoto = false;

    updateOrgPhotoUI();
    updateHeaderAccountCard();
    closeFullProfilePhotoModal();
    showToast("Profile photo removed successfully.");
  } catch (error) {
    console.error("Failed to remove profile photo:", error);
    showToast(`Could not remove photo: ${callableErrorMessage(error)}`, true);
  } finally {
    if (removeBtn) setButtonBusy(removeBtn, false);
  }
}

