function initAppearanceFeature() {
  const appearanceButtons = document.querySelectorAll("#appearanceButton, [data-open-appearance]");
  const appearanceModal = byId("appearanceModal");
  const closeBtn = byId("appearanceModalClose");
  const modeCards = [...document.querySelectorAll("[data-appearance-mode]")];
  let opener;

  function syncThemeUI(theme) {
    modeCards.forEach((card) => {
      const isSelected = card.dataset.appearanceMode === theme;
      card.classList.toggle("is-active", isSelected);
      card.setAttribute("aria-checked", String(isSelected));
      card.tabIndex = isSelected ? 0 : -1;
    });
  }

  function setTheme(theme) {
    window.ESugidTheme.set(theme);
  }

  function openAppearanceModal(event) {
    if (!appearanceModal) return;
    opener = event.currentTarget;
    appearanceModal.hidden = false;
    appearanceModal.style.removeProperty("display");
    opener.setAttribute("aria-expanded", "true");
    syncThemeUI(window.ESugidTheme.preference);
    modeCards.find(card => card.tabIndex === 0)?.focus();
  }

  function closeAppearanceModal() {
    if (!appearanceModal) return;
    appearanceModal.hidden = true;
    appearanceModal.style.setProperty("display", "none", "important");
    opener?.setAttribute("aria-expanded", "false");
    opener?.focus();
  }

  appearanceButtons.forEach(button => button.addEventListener("click", openAppearanceModal));
  closeBtn?.addEventListener("click", closeAppearanceModal);
  appearanceModal?.addEventListener("click", (event) => {
    if (event.target === appearanceModal) closeAppearanceModal();
  });

  document.addEventListener("keydown", (event) => {
    if (!appearanceModal || appearanceModal.hidden) return;
    if (event.key === "Escape") {
      closeAppearanceModal();
      event.preventDefault();
    } else if (event.key === "Tab") {
      const focusable = [closeBtn, ...modeCards.filter(card => card.tabIndex === 0)];
      const first = focusable[0];
      const last = focusable.at(-1);
      if (event.shiftKey && document.activeElement === first) {
        last?.focus();
        event.preventDefault();
      } else if (!event.shiftKey && document.activeElement === last) {
        first?.focus();
        event.preventDefault();
      }
    }
  });

  modeCards.forEach((card) => {
    card.addEventListener("click", () => {
      const mode = card.dataset.appearanceMode;
      if (mode) setTheme(mode);
    });
    card.addEventListener("keydown", (event) => {
      if (!["ArrowLeft", "ArrowRight", "ArrowUp", "ArrowDown", "Home", "End"].includes(event.key)) return;
      event.preventDefault();
      const index = modeCards.indexOf(card);
      const nextIndex = event.key === "Home" ? 0 : event.key === "End" ? modeCards.length - 1
        : (index + (["ArrowLeft", "ArrowUp"].includes(event.key) ? -1 : 1) + modeCards.length) % modeCards.length;
      setTheme(modeCards[nextIndex].dataset.appearanceMode);
      modeCards[nextIndex].focus();
    });
  });

  window.addEventListener("esugid:themechange", () => syncThemeUI(window.ESugidTheme.preference));
  syncThemeUI(window.ESugidTheme.preference);
}

